  ('581ae866-7516-4166-914e-1d96dc07fa6b', 'f648e83a-2c56-441e-b4e1-32b1eefb47ee', 'scope', '{"en":"What a function can see"}'::jsonb, '{"en":"Local variables, why assigning inside a function does not touch the one outside, and the clean way in and out."}'::jsonb, 5, 7, 'draft'::public.review_status, 'de46925e42c6277b498883600352d9fe'),
  ('15bfa7f2-5148-4a07-a77a-715843c0f20a', 'a5e260d3-fede-4421-8a12-60590f45c369', 'tuples', '{"en":"Tuples — lists that cannot change"}'::jsonb, '{"en":"Grouping values that belong together, and the comma that makes a one-item tuple."}'::jsonb, 1, 6, 'draft'::public.review_status, '06687d40a6044b40b1e63ed77be182ea'),
  ('a2f08dae-1e33-412d-9ac9-0ebd9ea3266b', 'a5e260d3-fede-4421-8a12-60590f45c369', 'unpacking', '{"en":"Unpacking into separate names"}'::jsonb, '{"en":"Taking a tuple apart in one line, swapping two values, and returning more than one thing."}'::jsonb, 2, 6, 'draft'::public.review_status, '8fd589213357ce302290f1583560d43d'),
  ('ab1753c6-d426-4e26-bc24-af2259924d57', 'a5e260d3-fede-4421-8a12-60590f45c369', 'sets', '{"en":"Sets — every value once"}'::jsonb, '{"en":"Collections without duplicates or order, and the fastest way to remove repeats from a list."}'::jsonb, 3, 7, 'draft'::public.review_status, '99754dd413f6aa3233d7e9d0373f5087'),
  ('5d8046f6-19c2-4eba-80c7-175d05b38e6e', 'a5e260d3-fede-4421-8a12-60590f45c369', 'set-operations', '{"en":"Combining sets"}'::jsonb, '{"en":"Union, intersection and difference — in either, in both, in one but not the other."}'::jsonb, 4, 6, 'draft'::public.review_status, 'e9361774257c4e2a9f483fae90d52f62'),
  ('650f7d68-7f25-400b-a2ff-6f3612b0c279', '12989185-5061-4772-9bd7-ddb7c2bdb173', 'creating-dicts', '{"en":"Looking things up by name"}'::jsonb, '{"en":"Keys and values, reading by key, and what happens when a key is missing or repeated."}'::jsonb, 1, 7, 'draft'::public.review_status, '5919e619b0bc5612db0bd0427608a6ab'),
  ('f151fdb9-e874-48b6-9991-84f563877631', '12989185-5061-4772-9bd7-ddb7c2bdb173', 'changing-dicts', '{"en":"Adding, updating and removing entries"}'::jsonb, '{"en":"One assignment to add or update, two ways to remove, and get for keys that may not exist."}'::jsonb, 2, 7, 'draft'::public.review_status, '0437151a8f23bf4d2fa4a7a4c49d5810'),
  ('a6c884c2-5be0-421f-8d45-3357817d3e3c', '12989185-5061-4772-9bd7-ddb7c2bdb173', 'looping-dicts', '{"en":"Going through a dictionary"}'::jsonb, '{"en":"Looping over keys, over key-value pairs with items(), and over values alone."}'::jsonb, 3, 6, 'draft'::public.review_status, 'f4ec210882482642cd99d1e9a2d66117'),
  ('b617c635-8b9a-4dea-b2a7-21ab07b142e7', '12989185-5061-4772-9bd7-ddb7c2bdb173', 'counting-and-nesting', '{"en":"Counting things, and data inside data"}'::jsonb, '{"en":"The counting pattern, and dictionaries that hold lists and other dictionaries."}'::jsonb, 4, 7, 'draft'::public.review_status, '24523f2c319725e196b5459721e638c4'),
  ('9e5ff976-4884-4834-a3b8-6b6297a86a30', 'a957be54-5adf-4712-a925-8955b410784f', 'split-and-join', '{"en":"Splitting text apart and joining it back"}'::jsonb, '{"en":"split() to turn a string into a list, and join() to go back the other way."}'::jsonb, 1, 7, 'draft'::public.review_status, 'aee61213bad8af16099c031d79f2ab7d'),
  ('1132c9f5-6dfc-4c9e-b637-10ef5fed4512', 'a957be54-5adf-4712-a925-8955b410784f', 'searching-text', '{"en":"Searching inside text"}'::jsonb, '{"en":"startswith, endswith, count, find and isdigit — and the find result that means \"not here\"."}'::jsonb, 2, 7, 'draft'::public.review_status, '34e5052d0383099f4cee6f03990a1f2c'),
  ('8f9da6d6-047e-4eea-ad58-29190027b0f0', 'a957be54-5adf-4712-a925-8955b410784f', 'list-comprehensions', '{"en":"Building a list in one line"}'::jsonb, '{"en":"List comprehensions — the loop-and-append pattern, written as a single expression."}'::jsonb, 3, 7, 'draft'::public.review_status, 'b8a6eeb43e1c74d65d94da203b9962bd'),
  ('ba36487d-d2ec-4a8e-a81d-110733d61728', 'a957be54-5adf-4712-a925-8955b410784f', 'filtering-comprehensions', '{"en":"Keeping only what you want"}'::jsonb, '{"en":"Adding a condition to a comprehension, and building dictionaries the same way."}'::jsonb, 4, 7, 'draft'::public.review_status, 'b5dfd4d1e3d93fca1fc80a6285d23297'),
  ('07725667-26a9-4d8b-87c0-53cf36f9d823', '35002fbe-89f7-4308-9928-034a885a79f5', 'exception-types', '{"en":"When something goes wrong"}'::jsonb, '{"en":"What an exception is, and the half-dozen types you will meet most often."}'::jsonb, 1, 7, 'draft'::public.review_status, '121f51efa62c5973aa334a226754fa66'),
  ('5eb1acb5-fffc-424f-bd33-78f57e71fb5c', '35002fbe-89f7-4308-9928-034a885a79f5', 'try-except', '{"en":"Recovering with try and except"}'::jsonb, '{"en":"Catching an exception, carrying on afterwards, and catching only what you expect."}'::jsonb, 2, 7, 'draft'::public.review_status, '5bd73b45cb8b4c2b649119d8f019b70b'),
  ('5ed29179-105c-4b68-b7e1-04ea86b59479', '35002fbe-89f7-4308-9928-034a885a79f5', 'else-and-finally', '{"en":"else and finally"}'::jsonb, '{"en":"Code that runs only on success, and code that runs no matter what."}'::jsonb, 3, 7, 'draft'::public.review_status, 'be2a4ca914da6a0ea76efc677407b4a1'),
  ('e5fa64cb-17c7-4ced-b065-835b001fe16a', '35002fbe-89f7-4308-9928-034a885a79f5', 'raising-exceptions', '{"en":"Raising your own"}'::jsonb, '{"en":"raise for inputs your code cannot accept, and reading the message with as."}'::jsonb, 4, 7, 'draft'::public.review_status, '26bfb815b18da6a8b13bd70b938afbc3'),
  ('1577e1e1-6b67-4f0f-8f0c-1e28b4ab2d5c', 'bba2b10b-9dd8-408c-b4d5-eecfdfb6269f', 'writing-files', '{"en":"Writing to a file"}'::jsonb, '{"en":"open, with, and write — and why write never adds a new line for you."}'::jsonb, 1, 7, 'draft'::public.review_status, 'f399710c6e274a88cbcd27caa1a86729'),
  ('e7f1dd4d-8f04-4719-b48f-d2d0cb16358d', 'bba2b10b-9dd8-408c-b4d5-eecfdfb6269f', 'reading-files', '{"en":"Reading a file back"}'::jsonb, '{"en":"The whole file at once, one line at a time, or as a list — and the new line each line keeps."}'::jsonb, 2, 7, 'draft'::public.review_status, 'ea9f0c52eeed32dd30e26381732043f7'),
  ('e2a0ec36-4611-4139-8ea9-965a5f306bef', 'bba2b10b-9dd8-408c-b4d5-eecfdfb6269f', 'file-modes', '{"en":"Adding to a file, and missing files"}'::jsonb, '{"en":"Append mode, the difference between w and a, and catching a file that is not there."}'::jsonb, 3, 7, 'draft'::public.review_status, 'a7f1c05482259d6049dcac660427e2d3'),
  ('6a824e33-e5cf-48ce-a6cd-b5485f595b76', 'bba2b10b-9dd8-408c-b4d5-eecfdfb6269f', 'processing-lines', '{"en":"One record per line"}'::jsonb, '{"en":"Reading comma-separated records, converting their fields, and writing records back out."}'::jsonb, 4, 8, 'draft'::public.review_status, '94b6202aed22c37745a60a9b9180c637'),
  ('6cc2a5c2-97e2-43da-b162-bff3ef0079e3', '16251265-08c0-435c-9ed9-6b456ba11974', 'importing', '{"en":"Borrowing tools with import"}'::jsonb, '{"en":"import, from ... import, and as — three ways to bring a module''s tools into your program."}'::jsonb, 1, 7, 'draft'::public.review_status, '255797f2aee20406af61593f18e67da8'),
  ('a81d668a-48b5-4976-b445-876b96a9c304', '16251265-08c0-435c-9ed9-6b456ba11974', 'math-module', '{"en":"The math module"}'::jsonb, '{"en":"Rounding up and down on purpose, pi and square roots, and why floats and equality do not mix."}'::jsonb, 2, 7, 'draft'::public.review_status, 'f1201140bb9f6a43c88675286d5a88c2'),
  ('0960fe16-21cb-4f4b-812e-66167b5cf921', '16251265-08c0-435c-9ed9-6b456ba11974', 'random-module', '{"en":"Randomness"}'::jsonb, '{"en":"Dice rolls, random picks and shuffles — and making \"random\" repeatable with a seed."}'::jsonb, 3, 7, 'draft'::public.review_status, '5b67ab9e207d90acea205277b888ec79'),
  ('a284ef71-f492-464a-97ca-5f58ae5b47c8', '16251265-08c0-435c-9ed9-6b456ba11974', 'counter-and-dates', '{"en":"Counting and calendars"}'::jsonb, '{"en":"Counter for counting in one line, and date arithmetic with datetime."}'::jsonb, 4, 7, 'draft'::public.review_status, '55ca9fed3e554dc2d55f8d701f7bed67'),
  ('ef7e193a-d1e2-4f37-9b65-bc9c25e97f69', 'f2d1b38d-ae5a-4308-a7b3-79ae8d5a2f01', 'classes-and-objects', '{"en":"Blueprints and the things made from them"}'::jsonb, '{"en":"Classes, objects, and giving an object its own data."}'::jsonb, 1, 6, 'draft'::public.review_status, 'be15b44d3a5e7f84f779d4c73215b3d2'),
  ('659f290a-3e00-4b81-9972-4e598d2b42dc', 'f2d1b38d-ae5a-4308-a7b3-79ae8d5a2f01', 'init-and-attributes', '{"en":"Setting up a new object"}'::jsonb, '{"en":"__init__, self, and giving every object its own attributes from the start."}'::jsonb, 2, 7, 'draft'::public.review_status, '91142f0776fca95232f858b90d9b78b4'),
  ('21ecdae3-8c50-46eb-b368-e36591f98e73', 'f2d1b38d-ae5a-4308-a7b3-79ae8d5a2f01', 'methods', '{"en":"Giving objects behaviour"}'::jsonb, '{"en":"Methods that read and change an object''s attributes, and the self you never pass yourself."}'::jsonb, 3, 7, 'draft'::public.review_status, '1cbd64dc63513b73e175c8444a80cc94'),
  ('40305ec5-0370-4985-ad6e-554134c14d81', 'f2d1b38d-ae5a-4308-a7b3-79ae8d5a2f01', 'str-method', '{"en":"Choosing how an object prints"}'::jsonb, '{"en":"__str__, and making print, str() and f-strings show something useful."}'::jsonb, 4, 6, 'draft'::public.review_status, 'df7a0a21ef980ba3f0b53d4413756f53'),
  ('7d62e2b5-b672-40a5-8d4e-72cea26fb726', 'f2d1b38d-ae5a-4308-a7b3-79ae8d5a2f01', 'inheritance', '{"en":"Building one class on another"}'::jsonb, '{"en":"Inheriting methods, replacing some of them, and calling the parent''s version with super()."}'::jsonb, 5, 8, 'draft'::public.review_status, 'b1efe953a4169f070340dbe373a0f45d'),
  ('c67de1e5-fb2c-4114-9177-b0b3f72df446', '005294d5-f070-4884-adce-adb37dfc08c7', 'breaking-down-problems', '{"en":"From a problem to a plan"}'::jsonb, '{"en":"Describing the steps in plain words first, and testing with small and awkward examples."}'::jsonb, 1, 7, 'draft'::public.review_status, '1f0a3322a5c3ac8460ad696be798fe01'),
  ('bf086c8a-ca58-41e4-9895-86cb77574926', '005294d5-f070-4884-adce-adb37dfc08c7', 'linear-search', '{"en":"Searching one item at a time"}'::jsonb, '{"en":"Linear search, stopping as soon as you find it, and what \"not found\" should return."}'::jsonb, 2, 7, 'draft'::public.review_status, '3f11180e20606af03665356efcf043f9'),
  ('f7fee9c3-1b51-4e38-afee-b80392ff9c5b', '005294d5-f070-4884-adce-adb37dfc08c7', 'binary-search', '{"en":"Searching by halves"}'::jsonb, '{"en":"Binary search on a sorted list, and why it needs so few checks."}'::jsonb, 3, 8, 'draft'::public.review_status, 'abf1474b0836a217df63b9b424c0f1a8'),
  ('9c569460-bf7e-4954-a766-a690a521a17e', '005294d5-f070-4884-adce-adb37dfc08c7', 'sorting', '{"en":"How sorting works, and sorting by anything"}'::jsonb, '{"en":"Selection sort by hand, then sorted() with a key function to choose what to sort by."}'::jsonb, 4, 8, 'draft'::public.review_status, 'e03d637360aae9af12bbe7285eb51e1a'),
  ('81eb31bd-096a-48a2-8a45-f0eee17f7453', '005294d5-f070-4884-adce-adb37dfc08c7', 'complexity', '{"en":"How work grows with data"}'::jsonb, '{"en":"Counting steps, and the names — O(1), O(log n), O(n), O(n²) — for how fast they grow."}'::jsonb, 5, 8, 'draft'::public.review_status, 'a3f166acc46aa8e610272f571a963648')
