insert into public.lesson_contents (lesson_id, blocks, content_hash) values
  ('ae47f49b-9ada-4145-af64-a445fd72dc15', '[{"type":"text","body":{"en":"Python is a programming language: a way of writing instructions precisely enough that\na computer can carry them out. You write plain text, and Python reads it from top to\nbottom and does what it says.\n"}},{"type":"text","body":{"en":"People choose Python because it reads close to English. Here is a complete, working\nprogram.\n"}},{"type":"code","code":"print(\"Hello!\")\n","output":"Hello!","runnable":true,"caption":{"en":"One line, and it really is the whole program."}},{"type":"text","body":{"en":"The thing that reads your code and runs it is called the **interpreter**. It works\nthrough your file one line at a time, in order. Nothing happens out of sequence, and\nnothing runs until you ask it to.\n"}},{"type":"callout","variant":"note","body":{"en":"Python does not need to be \"compiled\" into a separate program first. You write a file\nand run it. That short loop is a large part of why it suits learning.\n"}},{"type":"question","question_id":"a1a77c7f-c0a4-4320-8fd0-734d9d9d895a"},{"type":"question","question_id":"f931c8e5-5cf2-41f0-95c0-8ee0f585bb40"},{"type":"question","question_id":"2f2a58fa-0c26-4b3d-9b20-825ea7d3be34"},{"type":"question","question_id":"87b202d9-5f8a-4f33-a208-81b1775a74b9"},{"type":"question","question_id":"12c1b591-5eca-4a56-88e1-a6c8847efe6f"}]'::jsonb, '2ada6d36dbb6807542ea9911dc53e8e7'),
  ('8b14ce7b-46ce-44a3-b97a-92d34a1689d4', '[{"type":"text","body":{"en":"`print` is how a program shows something to the person running it. Whatever you put\nbetween the brackets gets displayed.\n"}},{"type":"code","code":"print(\"Learning Python\")\n","output":"Learning Python","runnable":true},{"type":"text","body":{"en":"You can print several things at once by separating them with commas. Python puts a\nsingle space between them.\n"}},{"type":"code","code":"print(\"Total:\", 42)\n","output":"Total: 42","runnable":true,"caption":{"en":"Notice the space between the text and the number — you did not type it."}},{"type":"text","body":{"en":"Each `print` starts a new line, so two prints produce two lines of output.\n"}},{"type":"code","code":"print(\"first\")\nprint(\"second\")\n","output":"first\nsecond","runnable":true},{"type":"callout","variant":"mistake","body":{"en":"Quotes change what a value is. `print(2 + 2)` adds two numbers and shows 4, while\n`print(\"2\" + \"2\")` joins two pieces of text and shows 22.\n"}},{"type":"question","question_id":"3c5222fe-517a-49ac-91d7-1a137a528870"},{"type":"question","question_id":"16cdc674-e894-45ae-b0d6-54446f427e50"},{"type":"question","question_id":"fb9e4bbf-0fd7-435f-b470-ff2be737db00"},{"type":"question","question_id":"772a78bc-1901-431c-b779-cedc8112f099"},{"type":"question","question_id":"d6ea8906-8c5b-4c72-9627-e468f1ab4180"}]'::jsonb, '02f0d8b885e6168282e3eb28c9fb9950'),
  ('a6e49edf-a740-4668-a22d-c1c46a544b0f', '[{"type":"text","body":{"en":"A `#` tells Python to ignore the rest of the line. What follows is for people reading\nthe code, not for the computer.\n"}},{"type":"code","code":"# Work out the delivery charge\nprint(5)\n","output":"5","runnable":true},{"type":"text","body":{"en":"A comment can also sit at the end of a line, after some real code.\n"}},{"type":"code","code":"print(19)  # the customer''s age\n","output":"19","runnable":true},{"type":"callout","variant":"tip","body":{"en":"Explain **why**, not **what**. `# add 1 to the total` repeats what the code already\nsays. `# the list is 1-based in the report` tells the reader something the code cannot.\n"}},{"type":"text","body":{"en":"Putting a `#` in front of a working line is a common trick while you are experimenting:\nthe line stays in the file but stops running. It is easy to forget one there, though.\n"}},{"type":"question","question_id":"ab04f186-d7f8-48e2-8daf-85978472e4bf"},{"type":"question","question_id":"a08adf6b-69a1-46dd-a631-c199ceddbbb6"},{"type":"question","question_id":"bdaf51c1-50b6-4c06-b365-3de70c98ff4b"},{"type":"question","question_id":"c3c78549-af7e-42c7-9962-6c2b9042d5ae"},{"type":"question","question_id":"cf7fcce7-ca2c-446d-8acc-a9827967786e"}]'::jsonb, '32fd4e827e21182b576b9ad4a50c5ca0'),
  ('4df3daa1-5801-4173-b93d-46ce15a385cd', '[{"type":"text","body":{"en":"Every programmer sees errors constantly. They are not a sign you are doing badly —\nthey are Python telling you precisely what it could not do.\n"}},{"type":"text","body":{"en":"An error message has three useful parts: the **line** it happened on, the **type** of\nproblem, and a short **description**. Read it from the bottom up: the last line is\nusually the most specific.\n"}},{"type":"code","code":"print(\"hello\"\n","runnable":false,"caption":{"en":"This is missing a closing bracket. Python reports a SyntaxError and points at the line\nwhere it ran out of patience.\n"}},{"type":"text","body":{"en":"Three types you will meet early. A **SyntaxError** means the text is not valid Python\nat all, so nothing runs.\n\nA **NameError** means you used a name Python has never seen.\n\nA **TypeError** means the values are fine, but not the right kind of value for that\noperation.\n"}},{"type":"callout","variant":"tip","body":{"en":"A SyntaxError often points at the line *after* the real mistake, because that is where\nPython finally noticed. If the reported line looks fine, check the one above it.\n"}},{"type":"question","question_id":"8764fe6c-31ad-43e4-aa11-b920b095f9d2"},{"type":"question","question_id":"95b7fe8c-8ae5-4930-b84a-9d07f3a43192"},{"type":"question","question_id":"6ab13905-9dd5-48b5-b9de-3e36cc96ac0a"},{"type":"question","question_id":"4c85bb3d-07a5-41df-a4f1-ec3fcea3bf10"},{"type":"question","question_id":"a51af7ed-df63-431b-be04-f4762b80590c"}]'::jsonb, '3b7ca9d522a4034f2dcf336d57df4d52'),
  ('a061f1ed-25e6-47db-9bc2-1610f7676d54', '[{"type":"text","body":{"en":"A variable is a name that stands for a value. You create one with `=`, putting the\nname on the left and the value on the right.\n"}},{"type":"code","code":"age = 21\nprint(age)\n","output":"21","runnable":true},{"type":"text","body":{"en":"Read `=` as \"gets\" rather than \"equals\": `age = 21` means *age gets the value 21*. It\nis an instruction, not a statement of fact, and the direction matters — the name on\nthe left receives what is on the right.\n"}},{"type":"text","body":{"en":"Once a name exists you can use it anywhere the value would work.\n"}},{"type":"code","code":"price = 8\nquantity = 3\nprint(price * quantity)\n","output":"24","runnable":true},{"type":"callout","variant":"mistake","body":{"en":"`21 = age` is an error. Python reads the left side as the thing being named, and 21 is\nalready a number — it cannot be given a value.\n"}},{"type":"question","question_id":"04e705b8-a2ca-4e5e-8821-084eed62ab28"},{"type":"question","question_id":"b859ee51-8e4b-4f04-b20c-fc13d23ef29c"},{"type":"question","question_id":"57309f58-3482-4930-9a7f-eaa6801b6b43"},{"type":"question","question_id":"ecc4f458-3c1e-48ba-9f4d-de8125d5c911"},{"type":"question","question_id":"8eb4cb1b-0219-4f10-bffd-6d834b5c220b"}]'::jsonb, '6f4a0fe0ae2cef4c0a8707c0bfecca7a'),
  ('3fba4acd-580c-4b58-bb81-3723335f9c95', '[{"type":"text","body":{"en":"Python has only a few rules about names. A name may contain letters, digits and\nunderscores; it may not start with a digit; and it may not contain a space.\n"}},{"type":"code","code":"user_name = \"Ana\"\nscore2 = 17\nprint(user_name, score2)\n","output":"Ana 17","runnable":true},{"type":"text","body":{"en":"Names are case-sensitive, so `total` and `Total` are two different variables. That\ncatches people out constantly.\n"}},{"type":"text","body":{"en":"Beyond the rules there is a convention: Python programmers use `lower_case_with_\nunderscores`. Following it makes your code look like everyone else''s, which makes it\neasier for others — and for you in six months.\n"}},{"type":"callout","variant":"tip","body":{"en":"A good name says what the value means, not what type it is. `price` beats `p`, and\n`days_remaining` beats `number`.\n"}},{"type":"question","question_id":"b623e3ea-65c0-41aa-9282-1255ae18f0f0"},{"type":"question","question_id":"93dcaabb-c9f7-4388-8dd7-be3e2ca2aeae"},{"type":"question","question_id":"91102369-a309-4de8-be34-02c6bc4c6f72"},{"type":"question","question_id":"5adb7977-9faa-4c44-97f9-851a07dc8c95"},{"type":"question","question_id":"796c7463-0715-40eb-a3e5-52c014b93b0e"}]'::jsonb, 'e29742c0ffe941c2557a3fdca36f4f05'),
  ('e4d23af9-8917-4945-b4aa-a5ec4878dba5', '[{"type":"text","body":{"en":"A variable can be given a new value at any time. The old one is simply replaced.\n"}},{"type":"code","code":"lives = 3\nlives = 2\nprint(lives)\n","output":"2","runnable":true},{"type":"text","body":{"en":"A variable can also be updated using its own current value. Python works out the right\nside first, then stores the result in the name on the left.\n"}},{"type":"code","code":"score = 10\nscore = score + 5\nprint(score)\n","output":"15","runnable":true,"caption":{"en":"`score = score + 5` reads oddly, until you remember `=` means \"gets\"."}},{"type":"text","body":{"en":"Because that pattern is so common, Python has a shorthand: `score += 5` does exactly\nthe same thing.\n"}},{"type":"code","code":"score = 10\nscore += 5\nscore -= 3\nprint(score)\n","output":"12","runnable":true},{"type":"callout","variant":"mistake","body":{"en":"Printing before the update shows the old value. The line that prints decides what you\nsee, not the line that assigns.\n"}},{"type":"question","question_id":"cd3ed4c6-272d-4c33-bd40-e633e6e1fbff"},{"type":"question","question_id":"56285afe-a6a1-4276-ba21-e15aa10d47f6"},{"type":"question","question_id":"697c0320-a823-46f5-a1d5-bbcd013107db"},{"type":"question","question_id":"51f8fc43-8f18-407a-8c3c-6969ed20a125"},{"type":"question","question_id":"184ed59e-ff4f-47c2-a320-351d98580148"}]'::jsonb, '99b765fc4e161b3d9a7874c30f67188e'),
  ('1efcab6f-3118-4d16-966a-83214cc494b8', '[{"type":"text","body":{"en":"Variables become useful when you combine them. Arithmetic works exactly as you would\nexpect, and the result can be stored in a new name.\n"}},{"type":"code","code":"hours = 7\nrate = 12\npay = hours * rate\nprint(pay)\n","output":"84","runnable":true},{"type":"text","body":{"en":"Text can be combined too, with `+`. This is called concatenation, and it joins the\npieces exactly — no space is added for you.\n"}},{"type":"code","code":"first = \"Ada\"\nlast = \"Lovelace\"\nprint(first + \" \" + last)\n","output":"Ada Lovelace","runnable":true,"caption":{"en":"The `\" \"` in the middle is a space, added deliberately."}},{"type":"text","body":{"en":"What you cannot do is add text to a number. Python refuses rather than guessing which\none you meant.\n"}},{"type":"code","code":"age = 21\nprint(\"Age: \" + str(age))\n","output":"Age: 21","runnable":true,"caption":{"en":"`str(age)` turns the number into text first, so `+` has two pieces of text to join."}},{"type":"callout","variant":"note","body":{"en":"`print(\"Age:\", age)` does the same job with less effort — commas handle mixed types on\ntheir own. Reach for `str()` when you need the pieces joined exactly.\n"}},{"type":"question","question_id":"89444f12-ab43-44e5-a276-b4bab12c8bc8"},{"type":"question","question_id":"315015b6-963b-4cfb-acc9-ea68b8e5ae51"},{"type":"question","question_id":"94627b6b-6cda-4f26-bdc7-17ce7531e214"},{"type":"question","question_id":"b1b87037-2ac7-4068-8dcc-aab0c1172c19"},{"type":"question","question_id":"f178061f-8985-4d79-81f2-e2daf4bfb9ae"}]'::jsonb, 'd0ceab87f0b90fe1c4ea06afaef8b3f9'),
  ('b2755a55-41d3-4e4f-83c0-afef79f9be61', '[{"type":"text","body":{"en":"Python has two everyday kinds of number. Whole numbers like `7` or `-3` are called\n**int**, short for integer. Numbers with a decimal point like `7.0` or `2.5` are called\n**float**. The built-in `type()` tells you which one you are holding.\n"}},{"type":"code","code":"print(type(7))\nprint(type(7.0))\n","output":"<class ''int''>\n<class ''float''>","runnable":true,"caption":{"en":"The decimal point alone is enough to make `7.0` a float."}},{"type":"text","body":{"en":"Most arithmetic keeps the type you started with, but division is different: `/` always\ngives a float, even when the answer is a whole number. Mixing an int and a float also\ngives a float.\n"}},{"type":"code","code":"print(10 / 2)\nprint(10 * 2)\nprint(3 + 0.5)\n","output":"5.0\n20\n3.5","runnable":true},{"type":"callout","variant":"note","body":{"en":"`7` and `7.0` compare as equal, but they are still different types. Python keeps track\nof the difference even when the value looks the same.\n"}},{"type":"text","body":{"en":"Floats are stored in binary, so some decimals cannot be represented exactly. The error\nis tiny, but it shows when you print the raw result. `round()` tidies it up for display.\n"}},{"type":"code","code":"print(0.1 + 0.2)\nprint(round(0.1 + 0.2, 2))\n","output":"0.30000000000000004\n0.3","runnable":true,"caption":{"en":"This is not a Python bug — almost every programming language behaves the same way."}},{"type":"question","question_id":"ea50311a-4796-4b21-8610-4868aa91e956"},{"type":"question","question_id":"de36e0df-ace2-4d08-88c7-dd0996bd9f88"},{"type":"question","question_id":"1888a90a-fb27-43f9-be70-593e413ddb7b"},{"type":"question","question_id":"c9c099ea-454f-4d6f-bf47-b5db8b522daf"},{"type":"question","question_id":"d06ac792-4b99-4520-8e22-340efc8ebeaa"},{"type":"question","question_id":"727abeac-6d68-437a-8634-ad4d3b12264c"}]'::jsonb, 'a6857fad176044a19e17b845cd537641'),
  ('2b995cc8-265a-440c-b602-a63eca6a08ad', '[{"type":"text","body":{"en":"Text in Python is called a **string**, and its type is `str`. The quotes are what make\nit text: `42` is a number, but `\"42\"` is two characters that happen to be digits.\n"}},{"type":"code","code":"print(type(\"42\"))\nprint(type(42))\n","output":"<class ''str''>\n<class ''int''>","runnable":true},{"type":"text","body":{"en":"`len()` counts the characters in a string. Spaces and punctuation count too.\n"}},{"type":"code","code":"print(len(\"Python\"))\nprint(len(\"hi there!\"))\n","output":"6\n9","runnable":true},{"type":"text","body":{"en":"A **boolean** holds one of exactly two values: `True` or `False`. Its type is `bool`.\nYou rarely type them by hand — comparisons produce them for you.\n"}},{"type":"code","code":"print(3 > 2)\nprint(10 == 11)\nprint(type(True))\n","output":"True\nFalse\n<class ''bool''>","runnable":true},{"type":"callout","variant":"mistake","body":{"en":"`True` and `False` must start with a capital letter. Lowercase `true` is not a value\nPython knows — it looks for a variable called `true` and stops with a NameError.\n"}},{"type":"question","question_id":"e3ce4890-1d0b-496f-94de-1648107212d4"},{"type":"question","question_id":"855ff9dc-c9b3-4af2-a161-bc2b7445ab64"},{"type":"question","question_id":"15cac6fb-f82c-4769-a6ca-47ce3feb372a"},{"type":"question","question_id":"c432c489-9171-4e39-9a1e-856c51a451fb"},{"type":"question","question_id":"4b76e759-379a-451b-9586-2e7e0c7d1239"},{"type":"question","question_id":"7189db76-c3df-40d8-b022-86b67b79a76e"}]'::jsonb, '62138f86e798deb382de38b2c85dd181'),
  ('4853a1ed-eb9c-4c8f-9387-6c2b7aaa2fdf', '[{"type":"text","body":{"en":"Each type has a function with the same name that builds a new value of that type:\n`int()`, `float()` and `str()`. You need them most when text arrives and you want to do\narithmetic with it, or when a number needs to be joined to text.\n"}},{"type":"code","code":"print(int(\"25\") + 5)\nprint(float(\"2.5\") * 2)\nprint(str(99) + \"!\")\n","output":"30\n5.0\n99!","runnable":true},{"type":"text","body":{"en":"Converting a float to an int does **not** round it. `int()` simply drops everything\nafter the decimal point. If you want rounding, ask for it with `round()`.\n"}},{"type":"code","code":"print(int(3.9))\nprint(round(3.9))\n","output":"3\n4","runnable":true,"caption":{"en":"`int(3.9)` is 3, not 4. This one catches almost everyone at least once."}},{"type":"callout","variant":"mistake","body":{"en":"`int(\"3.5\")` fails with a ValueError: the text has to look like a whole number. Go\nthrough `float()` first when the text might have a decimal point.\n"}},{"type":"code","code":"print(int(float(\"3.5\")))\n","output":"3","runnable":true},{"type":"question","question_id":"5dedd6e1-6fed-4171-b9ea-4f41fa58f35e"},{"type":"question","question_id":"3aa8b19e-d725-4beb-ae3b-47d23e9b96d7"},{"type":"question","question_id":"596d6609-d882-4297-b007-ceb1f1b1b629"},{"type":"question","question_id":"08e80b18-640c-483d-a908-9c3126eb8635"},{"type":"question","question_id":"535c4b97-d472-46a4-b0fe-5c5d8b301676"},{"type":"question","question_id":"7a270675-4baf-4d32-be72-af11fe9ab41d"},{"type":"question","question_id":"6047dd29-2efc-43ac-b87b-ec496d00bbf4"}]'::jsonb, '0e820ede7c69e93a084485d3ee90ffbb'),
  ('6cdd8360-333c-4eee-ae88-b7aa7120493c', '[{"type":"text","body":{"en":"Sometimes a variable needs to exist before it has anything useful in it. Python has a\nspecial value for that: `None`. It means \"nothing here yet\", and it has a type of its\nown.\n"}},{"type":"code","code":"result = None\nprint(result)\nprint(type(result))\n","output":"None\n<class ''NoneType''>","runnable":true},{"type":"text","body":{"en":"You also get `None` back from anything that does its job without producing a value.\n`print()` is one: it shows text on the screen, but the value it returns is `None`.\n"}},{"type":"code","code":"x = print(\"hi\")\nprint(x)\n","output":"hi\nNone","runnable":true,"caption":{"en":"The first line prints \"hi\"; the value stored in `x` is `None`."}},{"type":"callout","variant":"note","body":{"en":"`None` is not zero and not an empty string. It is its own thing: the absence of a\nvalue, rather than a value that happens to be small or empty.\n"}},{"type":"text","body":{"en":"`isinstance(value, type)` asks a yes-or-no question: is this value of that type? It\nanswers with a boolean, which makes it easy to use in decisions later on.\n"}},{"type":"code","code":"print(isinstance(3, int))\nprint(isinstance(\"3\", int))\nprint(isinstance(2.5, float))\n","output":"True\nFalse\nTrue","runnable":true},{"type":"question","question_id":"8850d187-073e-4873-8d4c-a2f22c18757c"},{"type":"question","question_id":"bba88ba8-52b7-4ffb-ac24-2b84c1eb027d"},{"type":"question","question_id":"87dabe33-20ab-44ce-989c-0f1c12098b69"},{"type":"question","question_id":"ff17234b-2f61-4398-963a-a36a0029d38c"},{"type":"question","question_id":"97b67f1b-3915-4b3b-88cb-d34ded78907a"}]'::jsonb, '1e7278402b6560f70d87596c2074058d'),
  ('07903697-df6e-4c58-9684-0b81fbf1fe92', '[{"type":"text","body":{"en":"You already know `+`, `-`, `*` and `/`. Python has three more arithmetic operators\nthat come up constantly. `//` divides and throws away the remainder. `%` gives **only**\nthe remainder. `**` raises a number to a power.\n"}},{"type":"code","code":"print(17 // 5)\nprint(17 % 5)\nprint(2 ** 10)\n","output":"3\n2\n1024","runnable":true,"caption":{"en":"17 is three fives with two left over — `//` gives the three, `%` gives the two."}},{"type":"text","body":{"en":"`%` is the easiest way to tell whether a number is even: an even number leaves nothing\nover when divided by 2.\n"}},{"type":"code","code":"print(10 % 2)\nprint(7 % 2)\n","output":"0\n1","runnable":true},{"type":"callout","variant":"tip","body":{"en":"`number % 2 == 0` is the standard way to ask \"is this even?\". You will see it in\nalmost every program that sorts things into two groups.\n"}},{"type":"text","body":{"en":"One surprise: `//` always rounds **down**, towards the smaller number. For positive\nnumbers that just drops the decimals, but for negative numbers it goes further away\nfrom zero.\n"}},{"type":"code","code":"print(7 // 2)\nprint(-7 // 2)\n","output":"3\n-4","runnable":true,"caption":{"en":"-3.5 rounded down is -4, not -3."}},{"type":"question","question_id":"ec2f7e2a-3150-4053-87f4-7d352ccff0c9"},{"type":"question","question_id":"cd1bfcc4-5907-46d8-8d52-559d9ecbb065"},{"type":"question","question_id":"930cf6d1-4bfd-4908-adea-7b8b00a3b042"},{"type":"question","question_id":"c5a0574a-2bcf-434e-842e-dbd0a4020e30"},{"type":"question","question_id":"7a23abe7-7374-4901-9cc6-8795fff9d58e"},{"type":"question","question_id":"0c36abc9-f0d4-40ff-a758-051d7141afee"}]'::jsonb, '954722e1dbcc0a66a96d596e045a0bfd'),
  ('ba67a0e1-2d0c-4b41-b0b5-33e49b82a647', '[{"type":"text","body":{"en":"When an expression has several operators, Python does not simply work left to right.\nIt follows the same order as maths: powers first, then multiplication and division,\nthen addition and subtraction.\n"}},{"type":"code","code":"print(2 + 3 * 4)\nprint((2 + 3) * 4)\n","output":"14\n20","runnable":true,"caption":{"en":"The multiplication happens first unless parentheses say otherwise."}},{"type":"text","body":{"en":"Operators on the same level are worked out from left to right. That matters for `-`\nand `/`, where the order changes the answer.\n"}},{"type":"code","code":"print(10 - 4 - 3)\nprint(100 / 10 / 2)\n","output":"3\n5.0","runnable":true,"caption":{"en":"(10 - 4) - 3 is 3, and (100 / 10) / 2 is 5.0."}},{"type":"callout","variant":"tip","body":{"en":"When you are not sure, add parentheses. They cost nothing, and the next person to read\nthe line — often you, next month — will not have to work out the rules.\n"}},{"type":"text","body":{"en":"A long calculation is easier to get right when you split it into steps and give each\nstep a name. Each line can then use the result of the line before.\n"}},{"type":"code","code":"price = 20\ndiscounted = price * 0.75\nwith_tax = discounted * 1.2\nprint(with_tax)\n","output":"18.0","runnable":true},{"type":"question","question_id":"e79896d5-48d3-446f-b0c0-b8c5b9053a07"},{"type":"question","question_id":"12ded32d-64f9-42b0-b3ff-9b98ac4d7e9c"},{"type":"question","question_id":"70a4c1f0-f06d-4303-9cf3-150ab4ce3ce0"},{"type":"question","question_id":"edfad4eb-a21e-4cd1-8de0-a24ceada9aee"},{"type":"question","question_id":"fb1a96b8-36ff-4532-b93b-7238acffc652"},{"type":"question","question_id":"6605e3c0-e432-4890-8166-bcf799e9f0c3"}]'::jsonb, 'fb58c2a1e2d9c792c40673bf8bc599dd'),
  ('175a507f-9409-48a6-8f22-1a6ec4f34c17', '[{"type":"text","body":{"en":"Comparison operators ask a question about two values and answer with `True` or\n`False`. There are six: `==` equal, `!=` not equal, `<` less than, `>` greater than,\n`<=` less than or equal, and `>=` greater than or equal.\n"}},{"type":"code","code":"x = 7\nprint(x > 5)\nprint(x == 7)\nprint(x != 7)\n","output":"True\nTrue\nFalse","runnable":true},{"type":"callout","variant":"mistake","body":{"en":"One `=` **stores** a value; two `==` **compare** values. Mixing them up is one of the\nmost common beginner mistakes, and Python will often refuse to run the line at all.\n"}},{"type":"text","body":{"en":"The boundary matters. `<` does not include the value itself, and `<=` does. Getting\nthis wrong by one is so common it has a name: an off-by-one error.\n"}},{"type":"code","code":"print(10 < 10)\nprint(10 <= 10)\n","output":"False\nTrue","runnable":true},{"type":"text","body":{"en":"Python lets you chain comparisons the way you would write them in maths. `13 <= age <=\n19` means both comparisons must be true.\n"}},{"type":"code","code":"age = 15\nprint(13 <= age <= 19)\n","output":"True","runnable":true},{"type":"question","question_id":"0ac326d0-b910-42af-bc63-d22b220741e4"},{"type":"question","question_id":"21fc7883-109b-4b04-8817-efb8a3ffa3f3"},{"type":"question","question_id":"3ad72061-ec3a-4624-8a15-993d39e39d37"},{"type":"question","question_id":"2ccae378-e741-4e78-8840-b0060a3818e2"},{"type":"question","question_id":"8b27c027-0176-4763-924f-fb53f840ce8e"},{"type":"question","question_id":"cc092fcd-d8d0-4e5d-80ea-74ae2204bb67"}]'::jsonb, '6506e92ab13126f1b5e92a977eba0a26'),
  ('25cc8af2-388a-4aee-bceb-4c8cd486ca30', '[{"type":"text","body":{"en":"Three words combine booleans. `and` is True only when **both** sides are True. `or` is\nTrue when **at least one** side is True. `not` flips a single value to its opposite.\n"}},{"type":"code","code":"print(True and False)\nprint(True or False)\nprint(not True)\n","output":"False\nTrue\nFalse","runnable":true},{"type":"text","body":{"en":"Their real use is joining comparisons into one question, the way you would say it in\na sentence: old enough **and** holding a ticket.\n"}},{"type":"code","code":"age = 20\nhas_ticket = True\nprint(age >= 18 and has_ticket)\nprint(age < 12 or age > 65)\n","output":"True\nFalse","runnable":true,"caption":{"en":"20 is neither under 12 nor over 65, so the `or` is False."}},{"type":"callout","variant":"tip","body":{"en":"`not` is worked out before `and`, and `and` before `or`. As with arithmetic, you can\nmake the order obvious with parentheses instead of relying on the rule.\n"}},{"type":"question","question_id":"e635fa8e-2152-466b-8d56-507deda73d01"},{"type":"question","question_id":"0811d96b-4240-4daa-8ea3-be5efefa1f9a"},{"type":"question","question_id":"831e1ba4-060b-46d8-94cc-965fa183c572"},{"type":"question","question_id":"436e11b6-fb85-401f-a117-4f15cf9c6ef2"},{"type":"question","question_id":"963bd77f-5961-4520-9e24-23987b7c4423"},{"type":"question","question_id":"d3f0083b-e0f0-4c3c-ad21-aabe606fbe40"}]'::jsonb, '224643c69d3767fc6d0e57db3df7735a'),
  ('6e1b0021-5c8b-408c-8bd3-26299d15cfef', '[{"type":"text","body":{"en":"Several operators work on strings too. `+` joins two strings and `*` repeats one. The\n`in` operator asks whether one piece of text appears anywhere inside another.\n"}},{"type":"code","code":"print(\"ha\" + \"ha\")\nprint(\"-\" * 10)\nprint(\"py\" in \"python\")\n","output":"haha\n----------\nTrue","runnable":true},{"type":"callout","variant":"note","body":{"en":"Every string comparison is case-sensitive. To Python, `\"P\"` and `\"p\"` are two\ncompletely different characters.\n"}},{"type":"code","code":"print(\"Py\" in \"python\")\nprint(\"Python\" == \"python\")\n","output":"False\nFalse","runnable":true},{"type":"text","body":{"en":"`<` and `>` compare strings character by character, the way a dictionary is ordered.\nOne twist: every capital letter comes before every lowercase letter.\n"}},{"type":"code","code":"print(\"apple\" < \"banana\")\nprint(\"Zebra\" < \"apple\")\n","output":"True\nTrue","runnable":true,"caption":{"en":"\"Z\" is a capital, so it sorts before any lowercase letter."}},{"type":"question","question_id":"d305bd23-4f0c-4f73-a8d6-1b04557b418c"},{"type":"question","question_id":"8b811e1e-f896-4afc-a934-9dbf7302b3af"},{"type":"question","question_id":"3934cd27-0056-4a23-b3fd-5a82ef0565d0"},{"type":"question","question_id":"0cdc7170-23f8-4738-b544-1169d4f11974"},{"type":"question","question_id":"e2f96f83-b5bc-4be0-8522-4d403607dd92"},{"type":"question","question_id":"ba788b60-3d6a-4acf-8b13-24c876850681"}]'::jsonb, 'f414f927b963289e8ebb553b94f11e4c'),
  ('2aa52e4e-d060-476c-a7c3-ab6f3f0bae46', '[{"type":"text","body":{"en":"A string can be written with single quotes or double quotes — Python treats them the\nsame. The useful part is that one kind can appear inside the other without trouble.\n"}},{"type":"code","code":"print(''She said \"hi\"'')\nprint(\"It''s fine\")\n","output":"She said \"hi\"\nIt''s fine","runnable":true},{"type":"text","body":{"en":"Some characters cannot be typed straight into a string. A backslash starts an\n**escape sequence**: `\\n` means a new line, `\\\"` means a double quote, and `\\\\` means\none real backslash.\n"}},{"type":"code","code":"print(\"line one\\nline two\")\nprint(\"C:\\\\files\")\n","output":"line one\nline two\nC:\\files","runnable":true,"caption":{"en":"`\\n` is one character — a line break — even though it takes two keystrokes to write."}},{"type":"callout","variant":"mistake","body":{"en":"The quotes at each end must match. `\"hi''` starts with a double quote and ends with a\nsingle one, so Python never finds the end of the string and reports a SyntaxError.\n"}},{"type":"question","question_id":"6531dfd0-cc1e-41a4-b8b4-5bd7bcbe94d9"},{"type":"question","question_id":"2c86eb73-0e8b-4922-9cfd-efa5113c3f5b"},{"type":"question","question_id":"2b0a4eb1-eabd-4ceb-974c-3e777d0a3b8a"},{"type":"question","question_id":"e8b29806-b74c-4f8a-824b-3ebb28b07e20"},{"type":"question","question_id":"289e7203-f369-4460-b7a5-ddf3d3934357"}]'::jsonb, 'c563416c3c460da63a9575f98881b29d'),
  ('337a55fa-37c4-4d19-87bb-eb125093290c', '[{"type":"text","body":{"en":"Every character in a string has a position, called its **index**. Square brackets\nafter the string pick one out. The first character is at index `0`, not 1.\n"}},{"type":"code","code":"word = \"Python\"\nprint(word[0])\nprint(word[5])\n","output":"P\nn","runnable":true,"caption":{"en":"Six characters, so the positions run from 0 to 5."}},{"type":"text","body":{"en":"Negative indexes count backwards from the end. `-1` is always the last character, `-2`\nthe one before it, however long the string is.\n"}},{"type":"code","code":"word = \"Python\"\nprint(word[-1])\nprint(word[-2])\n","output":"n\no","runnable":true},{"type":"callout","variant":"mistake","body":{"en":"The last index is always one less than the length. Asking for `word[6]` on a\nsix-letter word is past the end, and Python stops with an IndexError.\n"}},{"type":"question","question_id":"0253124a-2c47-46f2-bbd5-95c55914913b"},{"type":"question","question_id":"a78877a5-ee39-44e8-a074-aa9d9e5366bd"},{"type":"question","question_id":"5ca3ac04-b028-4701-8e41-b219ea27c65a"},{"type":"question","question_id":"c2aedeeb-d57b-4635-ad68-87602e5221ec"},{"type":"question","question_id":"525f80ed-f057-4aaf-8b6d-0c3ffd4ada58"},{"type":"question","question_id":"be69e6ef-d979-41ab-88e5-934a12f22220"}]'::jsonb, '7172823b9b837bf2a8f3308e9c884eb3'),
  ('9a76c6fd-c3b6-44cf-8fca-e424ac03d8f9', '[{"type":"text","body":{"en":"A **slice** takes a piece out of a string. `word[start:stop]` begins at `start` and\ngoes up to — but not including — `stop`.\n"}},{"type":"code","code":"word = \"Python\"\nprint(word[0:2])\nprint(word[2:6])\n","output":"Py\nthon","runnable":true,"caption":{"en":"`[0:2]` is positions 0 and 1. Position 2 is where the slice stops, so it is left out."}},{"type":"text","body":{"en":"Leave out the start to begin at the very beginning, or leave out the stop to run to\nthe very end.\n"}},{"type":"code","code":"word = \"Python\"\nprint(word[:3])\nprint(word[3:])\n","output":"Pyt\nhon","runnable":true},{"type":"callout","variant":"tip","body":{"en":"Because the stop is not included, `word[:3]` and `word[3:]` fit together perfectly\nwith no overlap and no gap. Joined, they always give back the whole word.\n"}},{"type":"text","body":{"en":"A third number sets the **step**. A step of 2 takes every second character, and a step\nof -1 walks backwards — the shortest way to reverse a string.\n"}},{"type":"code","code":"word = \"Python\"\nprint(word[::2])\nprint(word[::-1])\n","output":"Pto\nnohtyP","runnable":true},{"type":"question","question_id":"b8306d93-0775-4853-b921-7209ec347066"},{"type":"question","question_id":"6bdeb65c-f9ce-47bd-9f44-4d594d4720bb"},{"type":"question","question_id":"7bb0e1df-b4e5-4338-98e7-26036ddee92c"},{"type":"question","question_id":"1aa88729-d977-470d-af51-bd576a44facc"},{"type":"question","question_id":"568f9101-7e51-443a-9048-ae3b71177ab9"}]'::jsonb, '17fe087e6799b7d098a3755be7adeb66'),
  ('4a9f9773-c6c9-4873-8084-cf230f79c381', '[{"type":"text","body":{"en":"Joining text with `+` and `str()` works, but it gets clumsy fast. An **f-string** is\nsimpler: put an `f` just before the opening quote, then write any value inside curly\nbraces `{}` wherever you want it to appear.\n"}},{"type":"code","code":"name = \"Ada\"\nage = 36\nprint(f\"{name} is {age} years old\")\n","output":"Ada is 36 years old","runnable":true,"caption":{"en":"No `str()` needed — the f-string converts the number for you."}},{"type":"text","body":{"en":"Whatever is inside the braces is real Python, worked out before the text is built. You\ncan do arithmetic right there.\n"}},{"type":"code","code":"age = 36\nprint(f\"Next year: {age + 1}\")\n","output":"Next year: 37","runnable":true},{"type":"text","body":{"en":"After a colon inside the braces you can say how a value should look. `:.2f` means\n\"as a decimal with exactly two digits after the point\" — ideal for prices.\n"}},{"type":"code","code":"price = 3.5\nprint(f\"Total: {price:.2f}\")\n","output":"Total: 3.50","runnable":true},{"type":"callout","variant":"mistake","body":{"en":"Forget the `f` and nothing is filled in: `print(\"{name}\")` prints the braces and the\nword exactly as written.\n"}},{"type":"question","question_id":"41b7ecbc-6373-47b6-be68-3527ecff4f66"},{"type":"question","question_id":"ca7a8093-efdf-4f07-952e-89f198850e3a"},{"type":"question","question_id":"96b2ca33-d0a8-45a1-b292-13a777454d18"},{"type":"question","question_id":"babf8462-5bcc-4f75-9b50-c99a507dcdd8"},{"type":"question","question_id":"c6770581-a5bb-404e-b07a-0b354d24962b"},{"type":"question","question_id":"3362370d-e7ee-4bf8-bc64-aabe91c36e4c"}]'::jsonb, 'f2ce006994a611528cf2c14e5fe9798f'),
  ('ec113538-c53e-4725-858f-e002722477c1', '[{"type":"text","body":{"en":"A **method** is a function that belongs to a value. You call it with a dot after the\nvalue: `text.upper()`. Strings come with dozens of them; a handful cover most needs.\n"}},{"type":"code","code":"word = \"Hello\"\nprint(word.upper())\nprint(word.lower())\n","output":"HELLO\nhello","runnable":true},{"type":"text","body":{"en":"`strip()` removes spaces from both ends — handy for text someone typed. `replace()`\nswaps every copy of one piece of text for another.\n"}},{"type":"code","code":"raw = \"  hi  \"\nprint(raw.strip() + \"!\")\nprint(\"cat\".replace(\"c\", \"b\"))\n","output":"hi!\nbat","runnable":true},{"type":"text","body":{"en":"Strings can never be changed in place. A method does not alter the string you called\nit on — it hands back a **new** string. To keep the result, store it.\n"}},{"type":"code","code":"name = \"sam\"\nname.upper()\nprint(name)\nname = name.upper()\nprint(name)\n","output":"sam\nSAM","runnable":true,"caption":{"en":"The second line builds \"SAM\" and throws it away. The fourth line keeps it."}},{"type":"callout","variant":"mistake","body":{"en":"Calling a method on its own line and expecting the variable to change is one of the\nmost common string bugs. Nothing breaks — the variable simply stays the same.\n"}},{"type":"question","question_id":"a8bf8dbb-a9fd-4869-ad57-b2728e095a2d"},{"type":"question","question_id":"72e13076-03dd-42e4-a331-19a841b1d5e2"},{"type":"question","question_id":"4bc46b6f-6b7f-4acc-a361-e5116a913626"},{"type":"question","question_id":"f1c958d5-9e51-4c79-80a6-6dd98507e393"},{"type":"question","question_id":"5b507580-b48d-4c30-a901-ec4feabb2989"},{"type":"question","question_id":"5547081d-873d-47f2-a6eb-fd38514ac781"}]'::jsonb, '85399a8ec3bc1431c40f9cc6ab11876b'),
  ('c37dd7cc-f1df-4bd0-a741-63174d5dd4e2', '[{"type":"text","body":{"en":"An `if` statement runs some lines only when a condition is True. The line ends with a\ncolon, and the lines that belong to it are **indented** — pushed in by four spaces.\n"}},{"type":"code","code":"temperature = 30\nif temperature > 25:\n    print(\"It''s hot\")\nprint(\"Done\")\n","output":"It''s hot\nDone","runnable":true},{"type":"text","body":{"en":"The indentation is not decoration. It is how Python knows which lines belong to the\n`if`. The line that is not indented runs whatever happens.\n"}},{"type":"code","code":"temperature = 10\nif temperature > 25:\n    print(\"It''s hot\")\nprint(\"Done\")\n","output":"Done","runnable":true,"caption":{"en":"10 is not above 25, so the indented line is skipped. \"Done\" still prints."}},{"type":"callout","variant":"mistake","body":{"en":"Two errors you will meet early: forgetting the colon at the end of the `if` line gives\na SyntaxError, and indenting lines by different amounts gives an IndentationError.\n"}},{"type":"question","question_id":"4ef18f70-2100-4bef-aea3-106901dbc542"},{"type":"question","question_id":"fa2e0990-70fd-4ab9-ba28-9405645447bb"},{"type":"question","question_id":"b5af4e72-abbd-420c-8b2c-fabdc6120f2c"},{"type":"question","question_id":"ecea39aa-60eb-46b5-a71a-152ceb6b6dbb"},{"type":"question","question_id":"9cb611ad-025b-45c8-af77-d1aa6a66eda3"}]'::jsonb, '3c1299ea7bb2c6b1e6f3b11961946623'),
  ('d8e1f3f4-3857-4b1b-a3ad-a4e75d8eaff9', '[{"type":"text","body":{"en":"`else` gives an `if` a second path. When the condition is True, the `if` block runs;\nwhen it is False, the `else` block runs instead. Exactly one of the two always happens.\n"}},{"type":"code","code":"age = 15\nif age >= 18:\n    print(\"Adult\")\nelse:\n    print(\"Minor\")\n","output":"Minor","runnable":true},{"type":"text","body":{"en":"`else` has no condition of its own. It catches everything the `if` did not, which\nmakes it perfect for splitting things into two groups.\n"}},{"type":"code","code":"n = 7\nif n % 2 == 0:\n    print(\"even\")\nelse:\n    print(\"odd\")\n","output":"odd","runnable":true},{"type":"callout","variant":"tip","body":{"en":"`else` lines up with its `if` — same indentation, not further in. Its own block is then\nindented beneath it, just like the `if` block.\n"}},{"type":"question","question_id":"67f03725-aab9-49ad-8da8-33f803e2da55"},{"type":"question","question_id":"ccb6aee2-6970-4446-a092-59f495e363e6"},{"type":"question","question_id":"1aa3ef4f-9078-4301-b7f5-0c4e65603873"},{"type":"question","question_id":"07341cbb-364d-4c8e-954f-5b68aa339023"},{"type":"question","question_id":"d520a066-0bdf-4a8f-96e6-be829b7d2659"}]'::jsonb, '457b108faa5b49db03dfdbea366a30f9'),
  ('8e0aadeb-48fd-438e-b2cf-26546a943d23', '[{"type":"text","body":{"en":"`elif` means \"else if\". It adds another condition to check, but only when everything\nabove it was False. Python goes down the chain and runs the **first** block whose\ncondition is True, then skips the rest.\n"}},{"type":"code","code":"score = 72\nif score >= 90:\n    print(\"A\")\nelif score >= 70:\n    print(\"B\")\nelif score >= 50:\n    print(\"C\")\nelse:\n    print(\"F\")\n","output":"B","runnable":true,"caption":{"en":"72 is also at least 50, but the chain stopped at the first match."}},{"type":"text","body":{"en":"Because the first match wins, the order of the conditions matters. Put the widest\ncondition first and the narrower ones below it never get a chance.\n"}},{"type":"code","code":"score = 95\nif score >= 50:\n    print(\"C\")\nelif score >= 90:\n    print(\"A\")\n","output":"C","runnable":true,"caption":{"en":"95 is at least 50, so the chain stops there — the A branch is never checked."}},{"type":"callout","variant":"tip","body":{"en":"When conditions overlap, go from the most specific to the most general. In a grading\nchain that means highest threshold first.\n"}},{"type":"question","question_id":"6ffc7716-119e-4b06-b745-de8e4746c5b0"},{"type":"question","question_id":"668cce95-c43d-46cd-a2d6-616593090160"},{"type":"question","question_id":"77b6cabb-7ea7-4e97-8b3a-7ae6f8ef1a25"},{"type":"question","question_id":"0e34bf48-95f3-413c-bbfb-fd8255908e11"},{"type":"question","question_id":"0fc974ea-ae63-45d0-bf9f-4e11f5cbeb91"},{"type":"question","question_id":"24d72f0b-743d-4d00-8911-0edfbfee206d"}]'::jsonb, '16174584b12a48c142e1d51f06581780'),
  ('c0c663c6-9bd5-4bb6-929a-fe0c32662a1f', '[{"type":"text","body":{"en":"The `and`, `or` and `not` you already know work inside an `if`. They let one\ncondition check several things at once.\n"}},{"type":"code","code":"age = 25\nhas_licence = True\nif age >= 18 and has_licence:\n    print(\"Can drive\")\n","output":"Can drive","runnable":true},{"type":"text","body":{"en":"An `if` can also sit inside another `if`. This is called **nesting**: the inner\ncondition is only checked when the outer one was True.\n"}},{"type":"code","code":"logged_in = True\nis_admin = False\nif logged_in:\n    print(\"Welcome\")\n    if is_admin:\n        print(\"Admin panel\")\n","output":"Welcome","runnable":true,"caption":{"en":"The inner block is indented twice — once for each `if` it belongs to."}},{"type":"callout","variant":"tip","body":{"en":"Two nested `if` statements with nothing else between them can usually become one `if`\njoined with `and`. Flatter code is easier to read.\n"}},{"type":"question","question_id":"d93d6c81-9ed7-4347-b973-86d31d937fdf"},{"type":"question","question_id":"4be79f7e-7474-4fc4-bd38-b0d0a0954bc6"},{"type":"question","question_id":"7df95cef-4b60-4950-b105-6d946e628d5f"},{"type":"question","question_id":"1c061773-3fce-460b-96aa-e56b45d3f48b"},{"type":"question","question_id":"4784193d-7810-4c8c-bbf6-536706a6e9d9"},{"type":"question","question_id":"d3b3189d-8e06-4845-bf41-0cfc9c3b9358"}]'::jsonb, '65f99dcfb896f53acf0f426fb2c9a21a'),
  ('099bf83e-ec7b-40b3-8cf2-df36c7cd2ae2', '[{"type":"text","body":{"en":"An `if` does not need a comparison. You can give it any value, and Python decides\nwhether that value counts as True or False. Zero, an empty string and `None` count as\nFalse. Almost everything else counts as True.\n"}},{"type":"code","code":"name = \"\"\nif name:\n    print(\"Hello, \" + name)\nelse:\n    print(\"No name given\")\n","output":"No name given","runnable":true,"caption":{"en":"An empty string counts as False, so the else runs."}},{"type":"text","body":{"en":"`bool()` shows how any value would be judged.\n"}},{"type":"code","code":"print(bool(0))\nprint(bool(\"hi\"))\nprint(bool(None))\nprint(bool(\" \"))\n","output":"False\nTrue\nFalse\nTrue","runnable":true},{"type":"callout","variant":"mistake","body":{"en":"A string holding a single space is not empty — it has one character in it — so it\ncounts as True. So does the text `\"False\"` and the text `\"0\"`.\n"}},{"type":"question","question_id":"60417e1e-5d45-4ed2-8a5d-e9963a9b1f92"},{"type":"question","question_id":"0a364aef-0d64-4761-b1f6-b10d9365c630"},{"type":"question","question_id":"1b756faf-fca5-43a4-bc79-eb0d7b881959"},{"type":"question","question_id":"25e3e0e1-1cb3-49d8-a8b7-ceaa07ee1cec"},{"type":"question","question_id":"22a51a4d-8edc-46f6-a633-1925284e3467"},{"type":"question","question_id":"e3640abe-7d79-4e98-8ff6-8d283876859f"}]'::jsonb, '22fc8d0d09034aeda696916ae429ab1f'),
  ('6cc91223-f2b0-4539-952b-1d175e4028bd', '[{"type":"text","body":{"en":"A `for` loop runs its block once for every value it is given. `range(n)` gives the\nwhole numbers from 0 up to — but not including — `n`, so the block runs `n` times.\n"}},{"type":"code","code":"for i in range(3):\n    print(i)\n","output":"0\n1\n2","runnable":true,"caption":{"en":"Three rounds, with `i` taking the values 0, 1 and 2."}},{"type":"text","body":{"en":"`range` works just like a slice. Give it a start and a stop to choose the numbers, and\na third value to set the step.\n"}},{"type":"code","code":"for n in range(1, 10, 3):\n    print(n)\n","output":"1\n4\n7","runnable":true},{"type":"text","body":{"en":"The loop variable can be used inside the block like any other variable.\n"}},{"type":"code","code":"for i in range(1, 4):\n    print(i * i)\n","output":"1\n4\n9","runnable":true},{"type":"callout","variant":"tip","body":{"en":"You choose the loop variable''s name. `i` is the tradition for a plain counter, but a\nname that says what the number means — `row`, `day`, `attempt` — reads better.\n"}},{"type":"question","question_id":"21185e35-52ff-40a4-ab73-0789dea55e48"},{"type":"question","question_id":"846e7193-56e9-4fbe-a207-430219111682"},{"type":"question","question_id":"e9a61fc4-efec-4883-acf5-9edb70320ae1"},{"type":"question","question_id":"60fabb31-7658-498e-b4ec-647ff2be2730"},{"type":"question","question_id":"6d51da10-a311-4092-9ba7-01c8d065e5c3"},{"type":"question","question_id":"39105601-87f3-4da5-9f66-3ea3aea04afa"}]'::jsonb, '236ec116dceb3fdee31fb6732f89a567'),
  ('d232a459-bd8d-4693-bf98-a0f9dd4dda19', '[{"type":"text","body":{"en":"A `for` loop works with more than `range`. Give it a string and it hands you the\ncharacters one at a time, in order.\n"}},{"type":"code","code":"for ch in \"hi!\":\n    print(ch)\n","output":"h\ni\n!","runnable":true},{"type":"text","body":{"en":"Put an `if` inside the loop to act on only some of the characters.\n"}},{"type":"code","code":"for ch in \"banana\":\n    if ch == \"a\":\n        print(\"found an a\")\n","output":"found an a\nfound an a\nfound an a","runnable":true},{"type":"text","body":{"en":"When you need each character''s position as well, loop over `range(len(word))` and use\nthe number to index the string.\n"}},{"type":"code","code":"word = \"ok\"\nfor i in range(len(word)):\n    print(i, word[i])\n","output":"0 o\n1 k","runnable":true},{"type":"callout","variant":"tip","body":{"en":"Loop over the string itself whenever you only need the characters. It is shorter, and\nthere is no index to get wrong.\n"}},{"type":"question","question_id":"6a55409d-8e8b-41e2-9e46-cb427caaef78"},{"type":"question","question_id":"831e54d6-70e7-4413-8a3f-06c4e2f41e2e"},{"type":"question","question_id":"6d2515fa-751c-4673-b859-04094666dcf7"},{"type":"question","question_id":"327c0d3d-7e30-4933-af23-fdc93931dc4d"},{"type":"question","question_id":"c06dda55-c363-4905-a69b-398dcf3b8259"}]'::jsonb, '45ef6b0aab0bd3e9da60633d943c7f07'),
  ('4291ae6f-d928-4188-a14d-1d3d17a87d13', '[{"type":"text","body":{"en":"Many loops build up a single answer. The shape is always the same: create a variable\n**before** the loop, update it **inside** the loop, and use it **after** the loop.\nThat variable is called an **accumulator**.\n"}},{"type":"code","code":"total = 0\nfor n in range(1, 5):\n    total = total + n\nprint(total)\n","output":"10","runnable":true,"caption":{"en":"0 + 1 + 2 + 3 + 4, one addition per round."}},{"type":"text","body":{"en":"Counting works the same way: start at zero and add one each time something matches.\n`+=` is the usual shorthand for \"add to what is already there\".\n"}},{"type":"code","code":"count = 0\nfor ch in \"mississippi\":\n    if ch == \"s\":\n        count += 1\nprint(count)\n","output":"4","runnable":true},{"type":"callout","variant":"mistake","body":{"en":"Creating the accumulator **inside** the loop resets it every round, so only the last\nround survives. If a total comes out suspiciously small, check where it starts.\n"}},{"type":"question","question_id":"a3a017a5-c967-41a6-84d4-302683dec12f"},{"type":"question","question_id":"e242dc64-8079-48c9-8344-44df2256167a"},{"type":"question","question_id":"1a06968f-91a8-4fcc-af34-6c941771a4f8"},{"type":"question","question_id":"62947901-fd50-4d57-a367-77a033513309"},{"type":"question","question_id":"c465ce29-f126-46b7-ad8f-ac1a2a3cabb2"},{"type":"question","question_id":"7f71af00-2d68-4542-bf54-e38a83022ade"}]'::jsonb, '872310e0b85b12e7376dbfb6e82df36f'),
  ('14558780-0061-4706-8700-39d8d24f1dfd', '[{"type":"text","body":{"en":"A `while` loop repeats its block for as long as its condition stays True. The\ncondition is checked before every round, including the first.\n"}},{"type":"code","code":"n = 3\nwhile n > 0:\n    print(n)\n    n -= 1\nprint(\"Liftoff\")\n","output":"3\n2\n1\nLiftoff","runnable":true},{"type":"text","body":{"en":"Use `while` when you do not know in advance how many rounds you need — only when to\nstop. Here the loop keeps doubling until the number passes 100.\n"}},{"type":"code","code":"n = 1\nwhile n < 100:\n    n = n * 2\nprint(n)\n","output":"128","runnable":true},{"type":"callout","variant":"mistake","body":{"en":"Something inside the loop has to move the condition towards False. Forget `n -= 1`\nin the first example and the condition stays True forever — an **infinite loop** that\nonly stops when the program is forced to quit.\n"}},{"type":"question","question_id":"ede2ad3a-f487-4ddb-8b72-4cf5e4152362"},{"type":"question","question_id":"2824bcbe-710d-40cf-850a-223a6bc5a084"},{"type":"question","question_id":"52727a5b-e83b-427e-820c-86e61ced685f"},{"type":"question","question_id":"9b9757f7-7788-4f74-92ee-8acdd2cfe07b"},{"type":"question","question_id":"30e1653f-1bfe-4781-b351-93ad9e2c9ec7"}]'::jsonb, 'cc7f25ec8fb6350f34b2f1589e696665'),
  ('d09cc47b-e32a-447b-af4a-5f7da1b4977a', '[{"type":"text","body":{"en":"Two keywords change the flow of a loop from inside. `break` leaves the loop\nimmediately. `continue` skips the rest of the current round and moves on to the next.\n"}},{"type":"code","code":"for n in range(1, 10):\n    if n == 4:\n        break\n    print(n)\n","output":"1\n2\n3","runnable":true,"caption":{"en":"At 4 the loop ends — 4 and everything after it are never printed."}},{"type":"code","code":"for n in range(1, 6):\n    if n % 2 == 0:\n        continue\n    print(n)\n","output":"1\n3\n5","runnable":true,"caption":{"en":"Even numbers skip the print, but the loop carries on with the next number."}},{"type":"text","body":{"en":"`break` is how you stop searching once you have found what you were looking for —\nthere is no point checking the rest.\n"}},{"type":"code","code":"for ch in \"python\":\n    if ch == \"h\":\n        print(\"found h\")\n        break\n","output":"found h","runnable":true},{"type":"callout","variant":"tip","body":{"en":"`while True:` with a `break` inside is a common shape when the moment to stop is only\nknown halfway through a round.\n"}},{"type":"question","question_id":"c626273c-c3e8-4428-a119-f7d256b1634b"},{"type":"question","question_id":"eee7d121-1792-4e1e-bc88-b38c8f9a6a4b"},{"type":"question","question_id":"5c6fdd65-46d2-4e29-acfc-f182291d9ceb"},{"type":"question","question_id":"ce805186-f9a0-4471-8b6f-92e7ec47947b"},{"type":"question","question_id":"f0eb7171-62b7-4496-aa8f-c9cda46bec06"},{"type":"question","question_id":"db033ab0-235a-451f-835b-7169b7d17456"}]'::jsonb, '981b91e5304f35556d5fa227f4c2b03f'),
  ('44d74ec8-5c2d-4058-a32d-1f7ce23306a5', '[{"type":"text","body":{"en":"A **list** holds several values in order. You write it with square brackets, the\nvalues separated by commas. `len()` tells you how many items it holds.\n"}},{"type":"code","code":"scores = [90, 72, 85]\nprint(scores)\nprint(len(scores))\n","output":"[90, 72, 85]\n3","runnable":true},{"type":"text","body":{"en":"Items are numbered from 0, exactly like the characters of a string, and negative\nindexes count from the end.\n"}},{"type":"code","code":"scores = [90, 72, 85]\nprint(scores[0])\nprint(scores[-1])\n","output":"90\n85","runnable":true},{"type":"text","body":{"en":"A list can hold any kind of value, and even a mixture. A list with nothing in it — an\nempty list — is written `[]`.\n"}},{"type":"code","code":"things = [\"pen\", 3, True]\nprint(things)\nprint(len([]))\n","output":"[''pen'', 3, True]\n0","runnable":true},{"type":"callout","variant":"note","body":{"en":"When Python prints a list, it shows strings with single quotes, whichever quotes you\ntyped. The quotes tell you those items are text rather than numbers.\n"}},{"type":"question","question_id":"8156fa2c-053b-4f5c-81fa-a2981ec6a27b"},{"type":"question","question_id":"e2ca0431-63a0-47a5-b4c4-b9dd778945a3"},{"type":"question","question_id":"527c9244-929b-4bcb-9d4e-e64a8f7b59e1"},{"type":"question","question_id":"0f5a3f0f-157b-496e-adfd-06bcbf4da82f"},{"type":"question","question_id":"c5cfbf37-11f3-4e59-aa8e-ddeec72cea7e"}]'::jsonb, 'ed7de550b78c10df9c8b4507864c8c7e'),
  ('987d919a-d772-4bdb-b0f8-4df9a3fa70b9', '[{"type":"text","body":{"en":"Unlike strings, lists can be changed after they are made. Assigning to an index\nreplaces the item at that position.\n"}},{"type":"code","code":"pets = [\"cat\", \"dog\"]\npets[1] = \"fish\"\nprint(pets)\n","output":"[''cat'', ''fish'']","runnable":true},{"type":"text","body":{"en":"Four methods cover most changes. `append(x)` adds to the end, `insert(i, x)` puts `x`\nat position `i`, `remove(x)` deletes the first item equal to `x`, and `pop()` removes\nthe last item and hands it back to you.\n"}},{"type":"code","code":"items = [\"a\", \"b\"]\nitems.append(\"c\")\nitems.insert(0, \"z\")\nprint(items)\n","output":"[''z'', ''a'', ''b'', ''c'']","runnable":true},{"type":"code","code":"items = [\"z\", \"a\", \"b\", \"c\"]\nitems.remove(\"a\")\nlast = items.pop()\nprint(items)\nprint(last)\n","output":"[''z'', ''b'']\nc","runnable":true},{"type":"callout","variant":"mistake","body":{"en":"List methods change the list itself and return `None`. Writing `items =\nitems.append(\"x\")` replaces your list with `None` — the opposite of string methods,\nwhere you must store the result.\n"}},{"type":"question","question_id":"78b61558-b0e6-428d-a8c8-97dfb5a81451"},{"type":"question","question_id":"cd97ceba-bdeb-47e2-9af8-1ac77ca1ef1e"},{"type":"question","question_id":"fc2de227-3763-4f61-8d25-2fd7e63dac5d"},{"type":"question","question_id":"0431de16-9740-46c2-88a9-536cbd108318"},{"type":"question","question_id":"af5b1088-9d30-49e9-b160-1081f8cf9a49"},{"type":"question","question_id":"30d9213c-eb26-41bd-adf9-ca5c48a100d8"}]'::jsonb, '9bebfe6963d736b736945d1db20f4465'),
  ('060e29d3-2c05-4689-86e1-84833ccc852d', '[{"type":"text","body":{"en":"A `for` loop walks through a list one item at a time, just as it walks through the\ncharacters of a string.\n"}},{"type":"code","code":"for name in [\"Ann\", \"Bo\", \"Cy\"]:\n    print(\"Hi \" + name)\n","output":"Hi Ann\nHi Bo\nHi Cy","runnable":true},{"type":"text","body":{"en":"The accumulator pattern works on lists too. Adding up a list of prices is the\nclassic example.\n"}},{"type":"code","code":"prices = [4, 10, 6]\ntotal = 0\nfor p in prices:\n    total += p\nprint(total)\n","output":"20","runnable":true},{"type":"text","body":{"en":"To build a **new** list from an old one, start with an empty list and `append` to it\ninside the loop.\n"}},{"type":"code","code":"nums = [1, 2, 3]\ndoubled = []\nfor n in nums:\n    doubled.append(n * 2)\nprint(doubled)\n","output":"[2, 4, 6]","runnable":true},{"type":"text","body":{"en":"`in` asks whether a value appears anywhere in a list, the same way it does for text.\n"}},{"type":"code","code":"print(\"Bo\" in [\"Ann\", \"Bo\"])\n","output":"True","runnable":true},{"type":"callout","variant":"tip","body":{"en":"Avoid removing items from a list while you are looping over it — the loop loses its\nplace and skips items. Build a new list of the items you want to keep instead.\n"}},{"type":"question","question_id":"ec67d062-ab75-4c43-a664-1a1cb3213895"},{"type":"question","question_id":"8d4251d2-6875-4914-a86f-d301a757b835"},{"type":"question","question_id":"90c68858-651e-459b-b4fb-bb55237e6b0e"},{"type":"question","question_id":"1e2e8121-fe6f-4e67-b788-d8b5972cefd5"},{"type":"question","question_id":"cb8e7982-9003-4421-9319-a3f0c5b7fb88"},{"type":"question","question_id":"fc52ab2e-fa11-4174-a799-68acecb2e156"}]'::jsonb, '2b28e3f15e159a57b5d9259320681786'),
  ('99d03e20-2ae2-48b7-b027-5d1ba3c0d9d2', '[{"type":"text","body":{"en":"Assigning a list to a second name does **not** copy it. Both names now point at the\nsame list, so a change made through either name shows up through both.\n"}},{"type":"code","code":"a = [1, 2]\nb = a\nb.append(3)\nprint(a)\n","output":"[1, 2, 3]","runnable":true,"caption":{"en":"Nothing was appended to `a` — and yet `a` changed, because `a` and `b` are the same list."}},{"type":"text","body":{"en":"When you want an independent list, ask for a copy. `a.copy()` and the full slice\n`a[:]` both build a new list with the same items.\n"}},{"type":"code","code":"a = [1, 2]\nb = a.copy()\nb.append(3)\nprint(a)\nprint(b)\n","output":"[1, 2]\n[1, 2, 3]","runnable":true},{"type":"text","body":{"en":"Slicing a list works exactly as it does for strings, and always gives a new list.\n"}},{"type":"code","code":"nums = [10, 20, 30, 40]\nprint(nums[1:3])\n","output":"[20, 30]","runnable":true},{"type":"callout","variant":"mistake","body":{"en":"When a list seems to change on its own, look for a second name pointing at it. This\nis one of the most common bugs in Python programs of every size.\n"}},{"type":"question","question_id":"6fb452f6-4590-4b8b-8cc4-ca594028f2bb"},{"type":"question","question_id":"58084b0f-f972-4d9a-afbc-2064c4ae9f40"},{"type":"question","question_id":"a4bc30c9-aa01-4958-aa02-bf753b3c7a08"},{"type":"question","question_id":"cb5e85b0-e114-44a1-b71e-669fa367670c"},{"type":"question","question_id":"a876a506-1be3-4e01-ab50-606e234229ee"}]'::jsonb, 'a2753f1572c15b83e38bd0c92ddd4352'),
  ('7b4ae357-f8bf-4856-b6e7-be4fefe594fe', '[{"type":"text","body":{"en":"Python has built-in functions for the questions you ask a list of numbers most often.\n"}},{"type":"code","code":"nums = [4, 1, 7]\nprint(sum(nums))\nprint(min(nums))\nprint(max(nums))\n","output":"12\n1\n7","runnable":true},{"type":"text","body":{"en":"There are two ways to sort. `sorted(nums)` builds a **new** sorted list and leaves\nthe original alone. `nums.sort()` sorts the list **in place** and returns `None`.\n"}},{"type":"code","code":"nums = [3, 1, 2]\nprint(sorted(nums))\nprint(nums)\nnums.sort()\nprint(nums)\n","output":"[1, 2, 3]\n[3, 1, 2]\n[1, 2, 3]","runnable":true},{"type":"text","body":{"en":"Both accept `reverse=True` to sort from largest to smallest.\n"}},{"type":"code","code":"print(sorted([3, 1, 2], reverse=True))\n","output":"[3, 2, 1]","runnable":true},{"type":"callout","variant":"mistake","body":{"en":"`nums = nums.sort()` sorts the list and then replaces it with `None`. Use either\n`nums.sort()` on its own line, or `nums = sorted(nums)`.\n"}},{"type":"question","question_id":"e5e2b894-b717-408d-be17-6f246c6d1bb1"},{"type":"question","question_id":"a968fa95-141d-4083-83c1-ca57df59e7fb"},{"type":"question","question_id":"293e4f1d-291c-4873-a345-0b0272bf2fd3"},{"type":"question","question_id":"027273f0-076d-4b97-99a0-29733042272b"},{"type":"question","question_id":"a39d1155-48fc-4786-ba49-67d668a2f09a"},{"type":"question","question_id":"90971466-ba83-4a37-8404-bd166e63fe1c"}]'::jsonb, '7b2c0b39f4a20afd4d820a28e2364d14'),
  ('7cdeab88-9b51-474c-89cd-351e7ff4895e', '[{"type":"text","body":{"en":"A **function** is a named block of code you can run whenever you like. You create one\nwith `def`, a name, brackets and a colon, then indent the lines that belong to it.\nRunning it is called **calling** it: write its name followed by brackets.\n"}},{"type":"code","code":"def greet():\n    print(\"Hello!\")\n\ngreet()\ngreet()\n","output":"Hello!\nHello!","runnable":true,"caption":{"en":"Written once, used twice."}},{"type":"text","body":{"en":"Defining a function only stores it for later. Nothing inside it runs until something\ncalls it.\n"}},{"type":"code","code":"def shout():\n    print(\"HEY\")\n\nprint(\"start\")\n","output":"start","runnable":true,"caption":{"en":"`shout` is defined but never called, so \"HEY\" is never printed."}},{"type":"callout","variant":"tip","body":{"en":"Functions let you write something once and use it many times, and they let you give\na clear name to a step. `print_receipt()` says more than twenty lines of printing.\n"}},{"type":"question","question_id":"6b491324-c74e-450e-ac92-2cd2a7cf55da"},{"type":"question","question_id":"d0e421da-7c49-449e-87b1-85f8e8970cf8"},{"type":"question","question_id":"8cfae932-3bfb-471c-aba5-78d378d7b54c"},{"type":"question","question_id":"ca21c309-63be-4092-bef6-4e58e0863611"},{"type":"question","question_id":"92e02a50-703b-4fab-a6c9-50488ecac8bc"}]'::jsonb, 'c335bd22e69b3243596b8a87b37d1393'),
  ('b3d55681-24cb-451f-b9b3-ba15d269ba33', '[{"type":"text","body":{"en":"A function becomes far more useful when it can work on different values each time.\nNames inside the brackets of a `def` are **parameters**. The values you pass when\ncalling are **arguments**.\n"}},{"type":"code","code":"def greet(name):\n    print(\"Hello, \" + name)\n\ngreet(\"Ada\")\ngreet(\"Linus\")\n","output":"Hello, Ada\nHello, Linus","runnable":true},{"type":"text","body":{"en":"A function can take several parameters, separated by commas. Arguments are matched\nto them in order: the first argument to the first parameter, and so on.\n"}},{"type":"code","code":"def describe(name, age):\n    print(f\"{name} is {age}\")\n\ndescribe(\"Sam\", 12)\n","output":"Sam is 12","runnable":true},{"type":"callout","variant":"mistake","body":{"en":"Pass too few or too many arguments and Python refuses with a TypeError that says how\nmany it expected. It will not guess which one you left out.\n"}},{"type":"question","question_id":"38038d86-7918-4b9d-9c0e-a644a8296ae9"},{"type":"question","question_id":"40549fe6-33e1-4a66-bc90-952c982e138e"},{"type":"question","question_id":"24d7fb88-84a7-4fcb-9955-a56c5aba7738"},{"type":"question","question_id":"de783549-ba6e-49f6-9c7d-fcb7b7672867"},{"type":"question","question_id":"0f1e9f43-c693-493d-ba2b-a3edb30b8e3a"},{"type":"question","question_id":"fc21b405-77cb-4819-aff9-4a10e4a53c8b"}]'::jsonb, '993aec73f107638690b016cc2772e86c'),
  ('812a8031-d53b-4ae0-bc13-517856c5c4ab', '[{"type":"text","body":{"en":"`return` hands a value back to whoever called the function. The call itself then\nstands for that value, so you can store it, print it or use it in a calculation.\n"}},{"type":"code","code":"def square(n):\n    return n * n\n\nresult = square(4)\nprint(result + 1)\n","output":"17","runnable":true},{"type":"text","body":{"en":"`print` and `return` are easy to confuse. `print` shows a value on the screen and\nkeeps nothing. A function that only prints gives back `None`.\n"}},{"type":"code","code":"def show(n):\n    print(n)\n\nx = show(3)\nprint(x)\n","output":"3\nNone","runnable":true},{"type":"text","body":{"en":"`return` also ends the function immediately. Lines after it are never reached,\nwhich makes it handy for leaving early once the answer is known.\n"}},{"type":"code","code":"def check(n):\n    if n < 0:\n        return \"negative\"\n    return \"ok\"\n\nprint(check(-2))\nprint(check(5))\n","output":"negative\nok","runnable":true},{"type":"callout","variant":"mistake","body":{"en":"Printing inside a function when you meant to return is a very common mix-up. The\nvalue appears on screen, so everything looks fine — until another line tries to use\nit and gets `None`.\n"}},{"type":"question","question_id":"37c4c1fe-7d92-413d-bb0d-3ad5cc18fcc6"},{"type":"question","question_id":"0796c892-cbf5-4f3a-a9d8-c7fe98ee6c6b"},{"type":"question","question_id":"ec9498bd-589d-4514-81ab-3004772072c7"},{"type":"question","question_id":"0e28c005-b444-4d8e-aa3a-aa861afb973c"},{"type":"question","question_id":"2adb0700-645c-4b62-a616-710f168637ac"},{"type":"question","question_id":"99ef81cb-f07f-4fe6-864b-1fb36f3dccac"}]'::jsonb, '885ac53a90e8c93f0eca7bdae8ddf4c2'),
  ('d7ee5965-25be-4a57-bb15-7bf92ec6b0ef', '[{"type":"text","body":{"en":"A parameter can have a **default value**, written with `=` in the definition. If the\ncaller leaves that argument out, the default is used.\n"}},{"type":"code","code":"def greet(name, greeting=\"Hello\"):\n    print(f\"{greeting}, {name}!\")\n\ngreet(\"Ana\")\ngreet(\"Ana\", \"Hi\")\n","output":"Hello, Ana!\nHi, Ana!","runnable":true},{"type":"text","body":{"en":"You can also name an argument in the call: `parameter=value`. These are **keyword\narguments**, and because they say where they go, their order no longer matters.\nYou have used one already — `reverse=True` in `sorted`.\n"}},{"type":"code","code":"def describe(name, age):\n    print(f\"{name} is {age}\")\n\ndescribe(age=30, name=\"Kim\")\n","output":"Kim is 30","runnable":true},{"type":"callout","variant":"note","body":{"en":"In a definition, parameters with defaults must come after the ones without. In a\ncall, plain arguments must come before named ones.\n"}},{"type":"question","question_id":"d4330159-d1bd-469f-a2f0-0fc9e9f19350"},{"type":"question","question_id":"2ec5c6b3-fe02-440d-890e-31cd8999fd7c"},{"type":"question","question_id":"70805913-d33a-4b39-a439-dd29a8132d4a"},{"type":"question","question_id":"6da6aca2-41d2-4d4a-8159-123e4ed12c00"},{"type":"question","question_id":"2c9184b3-009c-4cae-93cf-f8985cb4bd43"}]'::jsonb, '8ac40eb1d552fc0e1966c42cd1abc51d'),
  ('581ae866-7516-4166-914e-1d96dc07fa6b', '[{"type":"text","body":{"en":"A variable created inside a function is **local**: it exists only while the function\nruns and disappears when it finishes. Code outside cannot see it.\n"}},{"type":"code","code":"def make():\n    secret = 42\n\nmake()\nprint(\"done\")\n","output":"done","runnable":true,"caption":{"en":"Adding `print(secret)` at the end would stop with a NameError."}},{"type":"text","body":{"en":"A function can **read** a variable from outside. But assigning to a name inside a\nfunction creates a new local variable, even if one with the same name exists outside.\nThe outside one is left untouched.\n"}},{"type":"code","code":"count = 10\n\ndef change():\n    count = 99\n\nchange()\nprint(count)\n","output":"10","runnable":true},{"type":"text","body":{"en":"The clean way to get values in and out is the way you already know: parameters in,\n`return` out, and assign the result where you need it.\n"}},{"type":"code","code":"def bump(n):\n    return n + 1\n\ncount = 10\ncount = bump(count)\nprint(count)\n","output":"11","runnable":true},{"type":"callout","variant":"tip","body":{"en":"Python does have a `global` keyword that lets a function change an outside variable.\nIt works, but it makes code hard to follow. Parameters and `return` are almost always\nthe better choice.\n"}},{"type":"question","question_id":"656c1077-f4b0-419b-9940-a215ee93a31b"},{"type":"question","question_id":"c5636918-ec9c-4b3b-b958-194c731a3edb"},{"type":"question","question_id":"d3792168-03cb-4d20-aaf6-044cf785fd4b"},{"type":"question","question_id":"09c07e0b-f03c-4824-952f-bbdc7ecc11ce"},{"type":"question","question_id":"7b8659fb-52e2-4b9f-b9f7-8a96f16b3bd3"},{"type":"question","question_id":"6ff913e9-3ac9-4f1b-bffe-86de45b260c1"}]'::jsonb, 'e8626793bd9ddbff7803298d23694369'),
  ('15bfa7f2-5148-4a07-a77a-715843c0f20a', '[{"type":"text","body":{"en":"A **tuple** is written with round brackets instead of square ones. You read it like a\nlist — by index, with `len`, in a loop — but once made, it can never be changed.\n"}},{"type":"code","code":"point = (3, 4)\nprint(point)\nprint(point[0])\nprint(len(point))\n","output":"(3, 4)\n3\n2","runnable":true},{"type":"text","body":{"en":"Use a tuple for values that belong together and should stay together: a pair of\ncoordinates, a date, a colour. Trying to change an item stops with a TypeError.\n"}},{"type":"callout","variant":"mistake","body":{"en":"A tuple with one item needs a trailing comma: `(5,)`. Without it, `(5)` is just the\nnumber 5 in brackets — the comma makes the tuple, not the brackets.\n"}},{"type":"code","code":"print(type((5,)))\nprint(type((5)))\n","output":"<class ''tuple''>\n<class ''int''>","runnable":true},{"type":"question","question_id":"02e40778-0056-42ed-bf57-d1ee9d904841"},{"type":"question","question_id":"b7a5eb75-06f8-4eb8-a3e0-83544f89812c"},{"type":"question","question_id":"aca22f62-cc85-4a16-bd45-581e09990f22"},{"type":"question","question_id":"fd168007-e40b-4d76-b29b-5a4fc8054e9c"},{"type":"question","question_id":"0003f234-e5b4-4ea2-9941-1ebbae11bd12"},{"type":"question","question_id":"eade48ee-8dd5-4446-bf4c-dcd5b026bfca"}]'::jsonb, '4812025a63bf13d83256693f9e8d3fc3'),
  ('a2f08dae-1e33-412d-9ac9-0ebd9ea3266b', '[{"type":"text","body":{"en":"**Unpacking** gives each item of a tuple its own name in a single line. Put as many\nnames on the left as there are items on the right.\n"}},{"type":"code","code":"point = (3, 4)\nx, y = point\nprint(x)\nprint(y)\n","output":"3\n4","runnable":true},{"type":"text","body":{"en":"The same trick swaps two variables without a temporary third one. The right-hand side\nis worked out first, then unpacked into the names on the left.\n"}},{"type":"code","code":"a = 1\nb = 2\na, b = b, a\nprint(a, b)\n","output":"2 1","runnable":true},{"type":"text","body":{"en":"A function can return several values separated by commas. Python packs them into a\ntuple, and the caller unpacks them.\n"}},{"type":"code","code":"def min_max(nums):\n    return min(nums), max(nums)\n\nlow, high = min_max([4, 9, 1])\nprint(low, high)\n","output":"1 9","runnable":true},{"type":"callout","variant":"mistake","body":{"en":"The number of names must match the number of items exactly. Too few or too many and\nPython stops with a ValueError rather than guessing which ones you meant.\n"}},{"type":"question","question_id":"a3a740fa-70eb-4144-8231-e4836059a814"},{"type":"question","question_id":"1f13623d-4195-4104-9918-6afde3374279"},{"type":"question","question_id":"0224dc49-3b33-41c2-965f-6237bbbaa09a"},{"type":"question","question_id":"dc7ace75-5bcd-4a09-bbda-0cdcc291f53a"},{"type":"question","question_id":"f000d6ea-2dd3-4a72-855b-7bac547636e7"},{"type":"question","question_id":"7df53ac2-7525-4174-816b-e3546e11fde4"}]'::jsonb, 'b180c8ba860224102b0a8fe9b32e8712'),
  ('ab1753c6-d426-4e26-bc24-af2259924d57', '[{"type":"text","body":{"en":"A **set** holds each value at most once. It is written with curly braces, duplicates\nare dropped automatically, and the items have no fixed order.\n"}},{"type":"code","code":"nums = {3, 1, 3, 2, 1}\nprint(len(nums))\nprint(sorted(nums))\n","output":"3\n[1, 2, 3]","runnable":true,"caption":{"en":"`sorted` gives a list in a predictable order — useful because a set has none."}},{"type":"text","body":{"en":"Turning a list into a set is the quickest way to find its distinct values.\n"}},{"type":"code","code":"names = [\"ann\", \"bo\", \"ann\"]\nunique = set(names)\nprint(len(unique))\n","output":"2","runnable":true},{"type":"text","body":{"en":"`add` puts a value in (doing nothing if it is already there), and `in` checks\nmembership — very quickly, even for huge sets.\n"}},{"type":"code","code":"seen = set()\nseen.add(\"a\")\nseen.add(\"a\")\nseen.add(\"b\")\nprint(sorted(seen))\nprint(\"b\" in seen)\n","output":"[''a'', ''b'']\nTrue","runnable":true},{"type":"callout","variant":"mistake","body":{"en":"`{}` is an empty **dictionary**, not an empty set. Write `set()` when you need an\nempty set. And because a set has no order, it has no positions: `s[0]` is an error.\n"}},{"type":"question","question_id":"67ed400e-3e29-4c5d-81a4-e06dcbac67fb"},{"type":"question","question_id":"e1709c38-90db-4a97-91cb-da70ce146b70"},{"type":"question","question_id":"63c60114-bafa-4b36-b646-c025191361c1"},{"type":"question","question_id":"83bed6ad-5a68-48ae-bec3-c108110c2907"},{"type":"question","question_id":"c3cd2823-8169-419e-9f14-9fe98133150d"},{"type":"question","question_id":"28a0eef2-de28-43b7-aa3c-c181152606d8"}]'::jsonb, 'a172cc11ac526465d0e61daf72cd28c4'),
  ('5d8046f6-19c2-4eba-80c7-175d05b38e6e', '[{"type":"text","body":{"en":"Sets can be combined like the circles in a Venn diagram. `a | b` is everything in\neither set, `a & b` is only what is in both, and `a - b` is what is in `a` but not in\n`b`.\n"}},{"type":"code","code":"a = {1, 2, 3}\nb = {2, 3, 4}\nprint(sorted(a | b))\nprint(sorted(a & b))\nprint(sorted(a - b))\n","output":"[1, 2, 3, 4]\n[2, 3]\n[1]","runnable":true},{"type":"text","body":{"en":"These turn questions about groups into one line each. Who is friends with both Ann and\nEve?\n"}},{"type":"code","code":"ann = {\"Bo\", \"Cy\", \"Di\"}\neve = {\"Cy\", \"Di\", \"Fi\"}\nprint(sorted(ann & eve))\n","output":"[''Cy'', ''Di'']","runnable":true},{"type":"callout","variant":"tip","body":{"en":"`|` and `&` give the same result either way round, but `-` does not: `a - b` and\n`b - a` are usually different sets.\n"}},{"type":"question","question_id":"3ee0ecbd-c02d-4f6f-9625-273639d9d6bb"},{"type":"question","question_id":"46141c3f-3006-4fb1-9ce7-f30866142419"},{"type":"question","question_id":"ccad9325-f95b-45c6-b9bd-c118cd3ccce2"},{"type":"question","question_id":"97683c03-50ed-42c9-82dc-f88b9aee978c"},{"type":"question","question_id":"dbb03cad-1331-4f1d-afa7-3692410110e0"},{"type":"question","question_id":"d90b0b91-d76d-40cf-8be8-a26fd895ff53"}]'::jsonb, '87ae125f5a984b226adfaff16d3e2485'),
  ('650f7d68-7f25-400b-a2ff-6f3612b0c279', '[{"type":"text","body":{"en":"A **dictionary** stores values under **keys**, so you look things up by name rather\nthan by position. It is written with curly braces, each entry as `key: value`.\n"}},{"type":"code","code":"ages = {\"Ann\": 31, \"Bo\": 25}\nprint(ages[\"Bo\"])\nprint(len(ages))\n","output":"25\n2","runnable":true,"caption":{"en":"`len` counts the entries — key-value pairs — not keys and values separately."}},{"type":"text","body":{"en":"Every key is unique. Write the same key twice and the later value wins; there is only\never one entry per key.\n"}},{"type":"code","code":"d = {\"a\": 1, \"a\": 2}\nprint(d)\n","output":"{''a'': 2}","runnable":true},{"type":"text","body":{"en":"`in` checks the **keys** of a dictionary, which is the safe way to ask before looking\nsomething up.\n"}},{"type":"code","code":"ages = {\"Ann\": 31, \"Bo\": 25}\nprint(\"Cy\" in ages)\n","output":"False","runnable":true},{"type":"callout","variant":"mistake","body":{"en":"Asking for a key that is not there — `ages[\"Cy\"]` — stops with a KeyError. Check with\n`in` first, or use `get`, which the next lesson covers.\n"}},{"type":"question","question_id":"75135521-9aae-48b7-8b72-bf2423c8b2f3"},{"type":"question","question_id":"891c88ca-41b2-4d9b-b99d-eeedae98ec5c"},{"type":"question","question_id":"4c697ce5-4dd3-4f90-9d47-bd3c019fc2a2"},{"type":"question","question_id":"3bfecd74-6b24-45c2-96c0-b89adc6f89ea"},{"type":"question","question_id":"41d3fe4c-ea78-46be-882a-c9325e6c7b84"},{"type":"question","question_id":"12695697-963f-4a78-90ee-231969916194"}]'::jsonb, 'ee5a976618536f48377215c51a143ea4'),
  ('f151fdb9-e874-48b6-9991-84f563877631', '[{"type":"text","body":{"en":"Assigning to a key does one of two things: it adds a new entry if the key is new, or\nreplaces the value if the key already exists.\n"}},{"type":"code","code":"stock = {\"apples\": 5}\nstock[\"pears\"] = 3\nstock[\"apples\"] = 4\nprint(stock)\n","output":"{''apples'': 4, ''pears'': 3}","runnable":true},{"type":"text","body":{"en":"`pop(key)` removes an entry and hands back its value. `del d[key]` removes it without\nhanding anything back.\n"}},{"type":"code","code":"stock = {\"apples\": 4, \"pears\": 3}\nremoved = stock.pop(\"pears\")\nprint(removed)\nprint(stock)\n","output":"3\n{''apples'': 4}","runnable":true},{"type":"text","body":{"en":"`get(key, default)` looks a key up without the risk of a KeyError. If the key is\nmissing, you get the default instead.\n"}},{"type":"code","code":"stock = {\"apples\": 4}\nprint(stock.get(\"kiwi\", 0))\nprint(stock.get(\"apples\", 0))\n","output":"0\n4","runnable":true},{"type":"callout","variant":"tip","body":{"en":"Use `get` with a default whenever \"missing\" simply means zero, empty or none. It\nturns a crash into a sensible answer.\n"}},{"type":"question","question_id":"a6b9c681-2b47-419f-adc5-036e6396ec9e"},{"type":"question","question_id":"7136a62f-73d9-4954-b566-ffbbdf019eb5"},{"type":"question","question_id":"9b7f51b4-ce1f-4985-bc1a-b0fa31261e82"},{"type":"question","question_id":"16f5724b-9b41-48a4-b790-c84e4f610df1"},{"type":"question","question_id":"569caed6-189a-4e42-947c-ecc2776f4c7d"},{"type":"question","question_id":"43b4405b-0708-45e8-9dd5-a053e422f5d4"}]'::jsonb, '89f5b1007d1e68d451177d5e7f55da5f'),
  ('a6c884c2-5be0-421f-8d45-3357817d3e3c', '[{"type":"text","body":{"en":"A `for` loop over a dictionary gives you its **keys**, in the order they were added.\n"}},{"type":"code","code":"ages = {\"Ann\": 31, \"Bo\": 25}\nfor name in ages:\n    print(name)\n","output":"Ann\nBo","runnable":true},{"type":"text","body":{"en":"When you need both halves, loop over `items()`. Each round hands you a key and its\nvalue, which you unpack into two names.\n"}},{"type":"code","code":"ages = {\"Ann\": 31, \"Bo\": 25}\nfor name, age in ages.items():\n    print(f\"{name}: {age}\")\n","output":"Ann: 31\nBo: 25","runnable":true},{"type":"text","body":{"en":"`values()` gives just the values — handy with `sum`, `max` and friends.\n"}},{"type":"code","code":"ages = {\"Ann\": 31, \"Bo\": 25}\nprint(sum(ages.values()))\n","output":"56","runnable":true},{"type":"callout","variant":"note","body":{"en":"Dictionaries remember the order entries were added in, so looping over one always\ngives the same order. That has been guaranteed since Python 3.7.\n"}},{"type":"question","question_id":"21af6227-413b-4389-8255-33cccdfc3a2f"},{"type":"question","question_id":"093a73da-de48-42ce-ace7-46ce731ebea0"},{"type":"question","question_id":"17d36542-6e97-4216-8398-2566ee549099"},{"type":"question","question_id":"3084efe9-1c6e-46a3-a44b-8564a33b997b"},{"type":"question","question_id":"5325e94f-7f03-41b9-a0f1-5edd53c603da"},{"type":"question","question_id":"7b054955-2c11-46c1-b527-098a2c9b8499"}]'::jsonb, 'cb2867c1f516482dfc1bd423ee8fea50'),
  ('b617c635-8b9a-4dea-b2a7-21ab07b142e7', '[{"type":"text","body":{"en":"Counting how often each thing appears is one of the most common jobs a dictionary\ndoes. For every item, add one to its count, using `get` so a new item starts at zero.\n"}},{"type":"code","code":"counts = {}\nfor ch in \"banana\":\n    counts[ch] = counts.get(ch, 0) + 1\nprint(counts)\n","output":"{''b'': 1, ''a'': 3, ''n'': 2}","runnable":true},{"type":"text","body":{"en":"A value can be anything — including a list or another dictionary. Read a nested\nlookup from left to right: first the key, then whatever you do to what it holds.\n"}},{"type":"code","code":"student = {\"name\": \"Ann\", \"grades\": [9, 7, 10]}\nprint(student[\"grades\"][0])\nprint(max(student[\"grades\"]))\n","output":"9\n10","runnable":true,"caption":{"en":"`student[\"grades\"]` is the list; `[0]` is its first item."}},{"type":"text","body":{"en":"A list of dictionaries is how most real data is shaped — one dictionary per person,\nproduct or order.\n"}},{"type":"code","code":"people = [{\"name\": \"Ann\", \"age\": 31}, {\"name\": \"Bo\", \"age\": 25}]\nfor p in people:\n    print(p[\"name\"])\n","output":"Ann\nBo","runnable":true},{"type":"callout","variant":"tip","body":{"en":"When a nested lookup fails, split it into steps and print each one. You will see\nexactly which level held something other than what you expected.\n"}},{"type":"question","question_id":"4d1051d0-d2dd-45d5-80fa-1fde7dc5fb54"},{"type":"question","question_id":"f0c3ccc9-2d0c-4e76-b4ff-c500252d5ec1"},{"type":"question","question_id":"a06e95c7-d429-4a90-aa07-cefc2e03b089"},{"type":"question","question_id":"19797c18-cb7d-4a46-ad0e-d5b9f94d00b5"},{"type":"question","question_id":"f037a66c-b82e-45ba-88c6-1a486a697365"},{"type":"question","question_id":"1165f73b-6499-4d6f-ab07-f54ff7c894de"}]'::jsonb, '5f9a3501debb9d6a7fdb15cd2154dfc6'),
  ('9e5ff976-4884-4834-a3b8-6b6297a86a30', '[{"type":"text","body":{"en":"`split()` breaks a string into a list of pieces. With no argument it splits on any\nrun of spaces, which gives you the words. Pass a separator to split on something else.\n"}},{"type":"code","code":"print(\"the quick fox\".split())\nprint(\"a,b,c\".split(\",\"))\n","output":"[''the'', ''quick'', ''fox'']\n[''a'', ''b'', ''c'']","runnable":true},{"type":"text","body":{"en":"`join()` goes the other way, gluing a list of strings together. It is called on the\n**separator**, with the list as its argument — which reads backwards at first.\n"}},{"type":"code","code":"words = [\"red\", \"green\", \"blue\"]\nprint(\", \".join(words))\nprint(\"-\".join(words))\n","output":"red, green, blue\nred-green-blue","runnable":true},{"type":"callout","variant":"mistake","body":{"en":"`join` only accepts strings. A list of numbers has to be turned into strings first,\nor Python stops with a TypeError.\n"}},{"type":"text","body":{"en":"Together they make quick work of everyday text jobs, such as counting the words in a\nsentence.\n"}},{"type":"code","code":"sentence = \"Python is fun to learn\"\nprint(len(sentence.split()))\n","output":"5","runnable":true},{"type":"question","question_id":"65dd190b-48db-4aac-ac43-4903962692a0"},{"type":"question","question_id":"b8d58212-99a3-489a-b76f-4802a8035d1d"},{"type":"question","question_id":"f6724920-1afe-4c67-8ba3-8e87a487609a"},{"type":"question","question_id":"50290bbc-86b2-48f5-b4cd-5437735384fb"},{"type":"question","question_id":"368edf22-577f-4fc5-bc1a-d338760f9d62"},{"type":"question","question_id":"443ffa94-c5e9-4237-ab86-0bd6262f9a0c"}]'::jsonb, '6e5618dd862ec47ea646b6c3892f8a0c'),
  ('1132c9f5-6dfc-4c9e-b637-10ef5fed4512', '[{"type":"text","body":{"en":"`startswith` and `endswith` answer yes-or-no questions about the ends of a string —\nperfect for file names and prefixes.\n"}},{"type":"code","code":"name = \"report.pdf\"\nprint(name.endswith(\".pdf\"))\nprint(name.startswith(\"rep\"))\n","output":"True\nTrue","runnable":true},{"type":"text","body":{"en":"`count` tells you how often a piece appears. `find` tells you **where** it first\nappears, as an index — or `-1` if it is not there at all.\n"}},{"type":"code","code":"s = \"banana\"\nprint(s.count(\"a\"))\nprint(s.find(\"n\"))\nprint(s.find(\"z\"))\n","output":"3\n2\n-1","runnable":true},{"type":"text","body":{"en":"`isdigit` checks whether every character is a digit — a good test before handing text\nto `int()`.\n"}},{"type":"code","code":"print(\"2024\".isdigit())\nprint(\"20.5\".isdigit())\n","output":"True\nFalse","runnable":true},{"type":"callout","variant":"mistake","body":{"en":"Never use `find` as a yes-or-no test. A match at the very start returns 0, which\ncounts as False, and \"not found\" returns -1, which counts as True. For yes or no, use\n`in`.\n"}},{"type":"question","question_id":"c88c8ffc-d55b-44ec-bfdb-97f74209ebfc"},{"type":"question","question_id":"d48fb0c8-0541-4fa9-91b5-f3784d47ca63"},{"type":"question","question_id":"5ae0cdf3-c9d9-492b-bd08-fba35ef0b581"},{"type":"question","question_id":"e7fd3142-411f-48bf-a727-904b78513a0b"},{"type":"question","question_id":"efcbb282-226f-462b-85cf-083d19298ec1"},{"type":"question","question_id":"5fb63869-9c75-4039-bf8f-37dc34764606"}]'::jsonb, 'be0f0cdd597783ba70de132b4e47f2d4'),
  ('8f9da6d6-047e-4eea-ad58-29190027b0f0', '[{"type":"text","body":{"en":"You have built new lists with a loop and `append` many times. A **list\ncomprehension** does the same in one line: `[expression for item in items]`.\n"}},{"type":"code","code":"nums = [1, 2, 3]\ndoubled = [n * 2 for n in nums]\nprint(doubled)\n","output":"[2, 4, 6]","runnable":true,"caption":{"en":"Read it as \"n times 2, for each n in nums\"."}},{"type":"text","body":{"en":"It works with any sequence — a range, a string, another list — and the expression can\nbe anything, including method calls.\n"}},{"type":"code","code":"print([n * n for n in range(1, 5)])\nprint([w.upper() for w in [\"hi\", \"yo\"]])\n","output":"[1, 4, 9, 16]\n[''HI'', ''YO'']","runnable":true},{"type":"text","body":{"en":"It is also the neat way to convert a whole list at once — for example, numbers into\nstrings so they can be joined.\n"}},{"type":"code","code":"nums = [1, 2, 3]\nprint(\", \".join([str(n) for n in nums]))\n","output":"1, 2, 3","runnable":true},{"type":"callout","variant":"tip","body":{"en":"A comprehension is for building a list. If the line starts getting hard to read, a\nnormal loop is perfectly good Python.\n"}},{"type":"question","question_id":"a5e40663-80d5-4ec2-8abb-20c0d7856a26"},{"type":"question","question_id":"c7cd8338-58b5-4881-a5ec-f707e32faa50"},{"type":"question","question_id":"0cc6589e-e778-44db-a768-f9e425328287"},{"type":"question","question_id":"6e4ba95a-f697-4aaf-9769-e618c5ae3186"},{"type":"question","question_id":"bb8b2d2a-4e36-4a07-ab91-155aac401772"},{"type":"question","question_id":"a32c7c2e-d9a7-4931-b27e-45e3093c59ca"}]'::jsonb, 'a5d3b490e00f59caac19d54905d89124'),
  ('ba36487d-d2ec-4a8e-a81d-110733d61728', '[{"type":"text","body":{"en":"Add `if condition` at the end of a comprehension and only the items that pass are\nkept. Everything else is simply left out.\n"}},{"type":"code","code":"nums = [1, 2, 3, 4, 5, 6]\nevens = [n for n in nums if n % 2 == 0]\nprint(evens)\n","output":"[2, 4, 6]","runnable":true},{"type":"text","body":{"en":"Transforming and filtering can happen in the same line. The condition is checked\nfirst; only the survivors are transformed.\n"}},{"type":"code","code":"words = [\"apple\", \"fig\", \"banana\"]\nprint([w.upper() for w in words if len(w) > 3])\n","output":"[''APPLE'', ''BANANA'']","runnable":true},{"type":"text","body":{"en":"Curly braces with `key: value` build a dictionary instead — a **dict comprehension**.\n"}},{"type":"code","code":"words = [\"hi\", \"hello\"]\nlengths = {w: len(w) for w in words}\nprint(lengths)\n","output":"{''hi'': 2, ''hello'': 5}","runnable":true},{"type":"callout","variant":"note","body":{"en":"The `if` at the end filters — it decides whether an item is kept. It does not choose\nbetween two values, and it takes no `else`.\n"}},{"type":"question","question_id":"7a5e66c3-f24c-4685-b77c-9fa9134b9279"},{"type":"question","question_id":"2440dc6c-f750-4df2-99d3-22179b0b0a11"},{"type":"question","question_id":"28ea0cb6-6965-495f-8908-16b585366abb"},{"type":"question","question_id":"72b4d213-107e-4e55-97e5-f640ba0428b3"},{"type":"question","question_id":"3ac4a194-a5cc-418f-b3e2-66c8b7b6cbfe"},{"type":"question","question_id":"50d2a84e-f084-47d1-8bb6-c79589496698"}]'::jsonb, 'ff7fa41159afb05669c9fc829e1d6437'),
  ('07725667-26a9-4d8b-87c0-53cf36f9d823', '[{"type":"text","body":{"en":"When a problem happens while a program is running, Python **raises an exception**.\nEach exception has a type that names the kind of problem. If nothing deals with it,\nthe program stops there and prints the error.\n"}},{"type":"code","code":"print(int(\"42\"))\nprint(int(\"abc\"))\nprint(\"never reached\")\n","runnable":false,"caption":{"en":"The first line prints 42. The second stops the program with a ValueError, so the last line never runs."}},{"type":"text","body":{"en":"A handful of types cover most early mistakes. A **ValueError** means the right type\nbut an unusable value, like `int(\"abc\")`. A **TypeError** means the wrong type for the\noperation, like `\"a\" + 1`.\n"}},{"type":"text","body":{"en":"A **KeyError** is a missing dictionary key, and an **IndexError** is a position past\nthe end of a list or string. A **ZeroDivisionError** is dividing by zero, and a\n**NameError** is a name Python has never seen.\n"}},{"type":"callout","variant":"tip","body":{"en":"The last line of an error message always names the type and says what went wrong.\nRead that line first — it usually tells you exactly where to look.\n"}},{"type":"question","question_id":"4d4e8b91-884b-45b4-95d5-40af41d120a5"},{"type":"question","question_id":"7341b873-f452-482d-9f0a-8553f8ef7400"},{"type":"question","question_id":"d76b9fc6-bd77-44a8-806c-e5105670d97b"},{"type":"question","question_id":"76eb667e-3d72-470c-b581-a493ecddaf79"},{"type":"question","question_id":"9562393e-68e5-481c-b8cf-034a9f8795cf"},{"type":"question","question_id":"5029fba1-05d1-4d7a-bc7b-d4169438e182"}]'::jsonb, '67000ddfb824459a4e1a957204ac35fa'),
  ('5eb1acb5-fffc-424f-bd33-78f57e71fb5c', '[{"type":"text","body":{"en":"`try` runs code that might fail. If an exception of the type named in `except` happens,\nPython jumps to the `except` block instead of stopping — and the program carries on\nafter it.\n"}},{"type":"code","code":"text = \"abc\"\ntry:\n    number = int(text)\n    print(number)\nexcept ValueError:\n    print(\"That is not a number\")\nprint(\"Still running\")\n","output":"That is not a number\nStill running","runnable":true},{"type":"text","body":{"en":"When nothing goes wrong, the `except` block is skipped entirely.\n"}},{"type":"code","code":"text = \"42\"\ntry:\n    number = int(text)\n    print(number)\nexcept ValueError:\n    print(\"That is not a number\")\nprint(\"Still running\")\n","output":"42\nStill running","runnable":true},{"type":"text","body":{"en":"Name the exception you expect. A lookup in a dictionary can fail with a KeyError, so\nthat is what you catch.\n"}},{"type":"code","code":"prices = {\"tea\": 2}\ntry:\n    print(prices[\"cake\"])\nexcept KeyError:\n    print(\"No such item\")\n","output":"No such item","runnable":true},{"type":"callout","variant":"mistake","body":{"en":"A bare `except:` with no type catches everything — including your own typos and\nbugs you have not found yet. Catch the specific exception you expect instead.\n"}},{"type":"question","question_id":"95690bd6-0107-44e6-8e1d-108ef14dc137"},{"type":"question","question_id":"acb5f9f0-53e9-4c1c-9b38-7a64e4fd8fc2"},{"type":"question","question_id":"8738addb-c60a-422d-888b-63745d11e63c"},{"type":"question","question_id":"bc6ed8df-980f-41bc-bbe5-9d677624734c"},{"type":"question","question_id":"c26ad780-73fb-45e7-8f1f-5f6346e6cd00"},{"type":"question","question_id":"5e7a2cfc-f037-4254-8d6b-7e94fbbd64db"}]'::jsonb, '22529f6ae9a96c74457f9e4c275f3eb4'),
  ('5ed29179-105c-4b68-b7e1-04ea86b59479', '[{"type":"text","body":{"en":"An `else` after the `except` blocks runs only when the `try` block raised nothing. It\nis the place for code that depends on the risky part having worked.\n"}},{"type":"code","code":"try:\n    n = int(\"5\")\nexcept ValueError:\n    print(\"bad input\")\nelse:\n    print(n * 10)\n","output":"50","runnable":true},{"type":"text","body":{"en":"`finally` runs whatever happened — after success, after a caught exception, even when\nan exception is on its way out uncaught.\n"}},{"type":"code","code":"try:\n    result = 10 / 0\nexcept ZeroDivisionError:\n    print(\"cannot divide\")\nfinally:\n    print(\"done\")\n","output":"cannot divide\ndone","runnable":true},{"type":"callout","variant":"tip","body":{"en":"`finally` is for tidying up: closing something you opened, or noting that a job has\nfinished. Keep the `try` block itself as short as possible, so it is clear which line\nyou expect to fail.\n"}},{"type":"question","question_id":"0f426b80-e1a3-45f2-99a8-e64e2665d5da"},{"type":"question","question_id":"8266f32a-5dc0-4341-928b-76f40f9c64ee"},{"type":"question","question_id":"a007461d-fcd4-46d0-b343-d16950b3b201"},{"type":"question","question_id":"4b6b2cb7-f022-49b2-a7bd-ed203e755cfa"},{"type":"question","question_id":"9414c9e6-6237-4fa7-8b48-e0a772162b28"},{"type":"question","question_id":"84d74457-926f-4867-8af7-7942f8ecc100"}]'::jsonb, '5a88c477f5212e1a2dfb95b61a5c4096'),
  ('e5fa64cb-17c7-4ced-b065-835b001fe16a', '[{"type":"text","body":{"en":"Your own functions can raise exceptions too. When a function is given something it\ncannot sensibly work with, `raise` stops it with a clear message.\n"}},{"type":"code","code":"def set_age(age):\n    if age < 0:\n        raise ValueError(\"Age cannot be negative\")\n    return age\n\nprint(set_age(20))\n","output":"20","runnable":true},{"type":"text","body":{"en":"Callers handle your exception like any other. Adding `as e` to the `except` line gives\nyou the exception itself, and printing it shows its message.\n"}},{"type":"code","code":"def set_age(age):\n    if age < 0:\n        raise ValueError(\"Age cannot be negative\")\n    return age\n\ntry:\n    set_age(-3)\nexcept ValueError as e:\n    print(e)\n","output":"Age cannot be negative","runnable":true},{"type":"callout","variant":"tip","body":{"en":"Raising early with a clear message beats returning an odd value like -1 that the\ncaller may forget to check. A loud problem is found; a quiet one spreads.\n"}},{"type":"question","question_id":"194dc819-edc9-4c69-8b9d-d1bda6b8d15f"},{"type":"question","question_id":"dce29517-a2c5-4781-8623-d908e4cdc09d"},{"type":"question","question_id":"c975dba7-dac8-4f8a-b711-4ccbc0d95480"},{"type":"question","question_id":"476584ca-c5d9-4ca5-b7f3-0036cae600b9"},{"type":"question","question_id":"2e7b74d2-b6eb-4211-a666-9ef4c69e3467"},{"type":"question","question_id":"6cfd95ad-6b69-4dc5-8c2a-52d0618d948f"}]'::jsonb, '1083ae34ed8a7ee9626f00f8645791ff'),
  ('1577e1e1-6b67-4f0f-8f0c-1e28b4ab2d5c', '[{"type":"text","body":{"en":"Variables disappear when a program ends; files do not. `open(name, \"w\")` opens a file\nfor **writing**, creating it if it does not exist. Doing it inside a `with` block\nmeans the file is closed properly as soon as the block ends.\n"}},{"type":"code","code":"with open(\"notes.txt\", \"w\") as f:\n    f.write(\"Buy milk\\n\")\n    f.write(\"Call Ann\\n\")\n\nwith open(\"notes.txt\") as f:\n    print(f.read())\n","output":"Buy milk\nCall Ann","runnable":true,"caption":{"en":"The second block reads the file back, to show what was written."}},{"type":"text","body":{"en":"`write` puts exactly the text you give it into the file — nothing more. It adds no\nspace and no new line, so you write `\\n` yourself wherever a line should end.\n"}},{"type":"code","code":"with open(\"n.txt\", \"w\") as f:\n    f.write(\"a\")\n    f.write(\"b\")\n\nwith open(\"n.txt\") as f:\n    print(f.read())\n","output":"ab","runnable":true},{"type":"callout","variant":"mistake","body":{"en":"Opening a file with `\"w\"` empties it immediately — before you have written a single\ncharacter. Whatever was in it is gone.\n"}},{"type":"question","question_id":"91892586-3f70-457a-b28f-882ecf1d46da"},{"type":"question","question_id":"f13c2eb2-a2ab-4cd8-9b0e-a7e0c1e55829"},{"type":"question","question_id":"94af7099-d1f3-4fe0-b619-93ed1f043e18"},{"type":"question","question_id":"292c9701-f553-4096-9ad9-943a15e20a79"},{"type":"question","question_id":"c7677b62-d31d-467a-92d5-eb1c53db60f8"},{"type":"question","question_id":"af58fb9a-9840-4d8e-9aa7-6c80b1a816b5"}]'::jsonb, '28f1d744d0c38218a474e02b79976ebf'),
  ('e7f1dd4d-8f04-4719-b48f-d2d0cb16358d', '[{"type":"text","body":{"en":"With no mode, `open` reads. `read()` gives you the whole file as one string. Looping\nover the file gives you one line at a time — and each line still ends with its `\\n`,\nwhich `strip()` removes.\n"}},{"type":"code","code":"with open(\"fruit.txt\", \"w\") as f:\n    f.write(\"apple\\nbanana\\ncherry\\n\")\n\nwith open(\"fruit.txt\") as f:\n    for line in f:\n        print(line.strip())\n","output":"apple\nbanana\ncherry","runnable":true},{"type":"text","body":{"en":"`readlines()` reads every line into a list. Printing that list shows the `\\n` at the\nend of each line.\n"}},{"type":"code","code":"with open(\"fruit.txt\", \"w\") as f:\n    f.write(\"apple\\nbanana\\n\")\n\nwith open(\"fruit.txt\") as f:\n    lines = f.readlines()\n\nprint(lines)\nprint(len(lines))\n","output":"[''apple\\n'', ''banana\\n'']\n2","runnable":true},{"type":"callout","variant":"mistake","body":{"en":"Forget `strip()` and every printed line is followed by a blank one: the `\\n` from the\nfile, plus the one `print` always adds.\n"}},{"type":"question","question_id":"4421f41c-65ac-4b3d-b601-458a892b2c0a"},{"type":"question","question_id":"fe34f8a8-13ef-4521-84c7-6b35a11bd8ff"},{"type":"question","question_id":"aec6f855-c84f-45f6-8860-7afcb57872cb"},{"type":"question","question_id":"2bfcb5b0-1a0a-419f-ae6f-0e4151bd10a2"},{"type":"question","question_id":"0e4dc94c-d4b5-40e5-955d-90b5835a31b6"},{"type":"question","question_id":"daebbf25-2733-419a-a5de-09a3ed32716b"}]'::jsonb, '222806975aec8c6a06d309dd7a9c6f81'),
  ('e2a0ec36-4611-4139-8ea9-965a5f306bef', '[{"type":"text","body":{"en":"Mode `\"a\"` means **append**: the file is opened and everything you write goes on the\nend. Nothing already in it is lost.\n"}},{"type":"code","code":"with open(\"log.txt\", \"w\") as f:\n    f.write(\"start\\n\")\n\nwith open(\"log.txt\", \"a\") as f:\n    f.write(\"more\\n\")\n\nwith open(\"log.txt\") as f:\n    print(f.read().strip())\n","output":"start\nmore","runnable":true},{"type":"text","body":{"en":"Reading a file that does not exist raises a **FileNotFoundError**. It is caught like\nany other exception.\n"}},{"type":"code","code":"try:\n    with open(\"missing.txt\") as f:\n        print(f.read())\nexcept FileNotFoundError:\n    print(\"No such file\")\n","output":"No such file","runnable":true},{"type":"callout","variant":"tip","body":{"en":"`\"r\"` reads, `\"w\"` starts fresh, `\"a\"` adds to the end. Mixing up `\"w\"` and `\"a\"` is\nthe classic way to lose data, so decide which one you mean every time.\n"}},{"type":"question","question_id":"10c7d616-17eb-4449-b7a1-c0e29b272a76"},{"type":"question","question_id":"e543b358-bfea-4b83-ba47-c9746ac04d29"},{"type":"question","question_id":"ed9dc2cc-fe8d-471d-95f2-325ea6d72287"},{"type":"question","question_id":"88b39fdd-eb52-496f-9889-5a25d6365458"},{"type":"question","question_id":"7497513c-c2fa-400e-abbf-c46e5ad049b1"},{"type":"question","question_id":"f440acdc-e228-4841-a4cf-95c15e5ec247"}]'::jsonb, '3cfc49c4d6c1bd54c7f9183723fdb609'),
  ('6a824e33-e5cf-48ce-a6cd-b5485f595b76', '[{"type":"text","body":{"en":"Real files usually hold one record per line, with the fields separated by a comma.\nStrip the line, split it on the comma, and unpack the fields into names.\n"}},{"type":"code","code":"with open(\"scores.txt\", \"w\") as f:\n    f.write(\"Ann,82\\nBo,75\\nCy,91\\n\")\n\ntotal = 0\nwith open(\"scores.txt\") as f:\n    for line in f:\n        name, score = line.strip().split(\",\")\n        total += int(score)\nprint(total)\n","output":"248","runnable":true},{"type":"text","body":{"en":"Writing records works the other way: build each line with an f-string and end it with\n`\\n`.\n"}},{"type":"code","code":"people = [(\"Ann\", 31), (\"Bo\", 25)]\nwith open(\"people.txt\", \"w\") as f:\n    for name, age in people:\n        f.write(f\"{name},{age}\\n\")\n\nwith open(\"people.txt\") as f:\n    print(f.read().strip())\n","output":"Ann,31\nBo,25","runnable":true},{"type":"callout","variant":"note","body":{"en":"Everything read from a text file is a string — even \"82\". Convert with `int()` or\n`float()` before doing any arithmetic.\n"}},{"type":"question","question_id":"b08ac551-f354-4535-8e20-30cad1c0fd7f"},{"type":"question","question_id":"1501dfaa-df08-4dfd-86dd-8dcd6b277faa"},{"type":"question","question_id":"97b610da-2de9-4b9b-a57b-37b04b3efd0e"},{"type":"question","question_id":"eecfb256-753d-4d67-94f8-4d3dd8f0fe13"},{"type":"question","question_id":"3bd9492b-85ba-42f8-a0d0-e405a5fb8d7d"},{"type":"question","question_id":"1dd7718f-a6db-4924-890a-27112846bb3c"}]'::jsonb, '23231d493adc77fc81ba192587186c63'),
  ('6cc2a5c2-97e2-43da-b162-bff3ef0079e3', '[{"type":"text","body":{"en":"Python comes with a large **standard library**: modules full of ready-made tools.\n`import` brings a module into your program, and you reach its tools with a dot.\n"}},{"type":"code","code":"import math\nprint(math.sqrt(16))\nprint(math.pi)\n","output":"4.0\n3.141592653589793","runnable":true},{"type":"text","body":{"en":"`from module import name` brings in a single name, which you then use without the\nprefix. `import module as short` gives the module a shorter name.\n"}},{"type":"code","code":"from math import sqrt\nprint(sqrt(25))\n\nimport math as m\nprint(m.floor(2.7))\n","output":"5.0\n2","runnable":true},{"type":"callout","variant":"mistake","body":{"en":"Never name your own file `math.py` or `random.py`. Python finds your file first, and\nthe real module becomes unreachable from that folder.\n"}},{"type":"callout","variant":"tip","body":{"en":"Put imports at the top of the file. Plain `import math` keeps it obvious where each\nname comes from, so prefer it until the prefix really gets in the way.\n"}},{"type":"question","question_id":"07aac42b-ee0d-4b92-a829-38f1085f786b"},{"type":"question","question_id":"30f46ab3-d4c5-4526-a3e8-9e978c64d299"},{"type":"question","question_id":"72d453c7-d766-4196-983f-bfb654da13dd"},{"type":"question","question_id":"d2162dcf-05f4-4a3d-a5c1-cddb3002f70f"},{"type":"question","question_id":"cb5e06ee-e1de-4246-b6bd-00d7a418ebfe"},{"type":"question","question_id":"046c6e69-ebc9-4280-8c4e-a9a41d4735e1"}]'::jsonb, '737235116379bcdf7a74e17771d0e6d5'),
  ('a81d668a-48b5-4976-b445-876b96a9c304', '[{"type":"text","body":{"en":"`math.floor` always rounds **down** and `math.ceil` always rounds **up**, whatever the\ndecimals. `round` goes to the nearest whole number instead.\n"}},{"type":"code","code":"import math\nprint(math.floor(3.7))\nprint(math.ceil(3.2))\nprint(round(3.7))\n","output":"3\n4\n4","runnable":true},{"type":"text","body":{"en":"`math.pi` holds π to full precision, and `math.gcd` finds the greatest common divisor\nof two whole numbers.\n"}},{"type":"code","code":"import math\nr = 2\nprint(round(math.pi * r ** 2, 2))\nprint(math.gcd(12, 18))\n","output":"12.57\n6","runnable":true,"caption":{"en":"The area of a circle with radius 2, rounded to two decimal places."}},{"type":"callout","variant":"note","body":{"en":"Most `math` functions work with floats and return floats. Because floats are\napproximations, compare them with care: a result that should be exactly 2 may be off\nin the sixteenth decimal place.\n"}},{"type":"question","question_id":"b23baab9-c72c-4c1c-8d1a-c089dd46f518"},{"type":"question","question_id":"1f3ceb11-49a6-4443-8602-d4a909d95f30"},{"type":"question","question_id":"0c48cd12-021a-4a52-b2b9-398149290bed"},{"type":"question","question_id":"c3975d0e-b039-44f5-8b0e-01c6384f1cca"},{"type":"question","question_id":"0ee6853c-0c74-46c1-8924-3037ee9808f7"},{"type":"question","question_id":"2b57a00d-ec2b-4b87-a31b-dcd988ef613d"}]'::jsonb, '9cd8c732d30dfeaf1d97291d9ac457f9'),
  ('0960fe16-21cb-4f4b-812e-66167b5cf921', '[{"type":"text","body":{"en":"The `random` module produces unpredictable values. `randint(a, b)` gives a whole\nnumber from `a` to `b` — both ends included, unlike `range`.\n"}},{"type":"code","code":"import random\nroll = random.randint(1, 6)\nprint(1 <= roll <= 6)\n","output":"True","runnable":true,"caption":{"en":"The roll itself changes every run. What never changes is that it lands between 1 and 6."}},{"type":"text","body":{"en":"`choice` picks one item from a list, and `shuffle` rearranges a list in place.\n"}},{"type":"code","code":"import random\ncolours = [\"red\", \"green\", \"blue\"]\nprint(random.choice(colours) in colours)\n\ncards = [1, 2, 3, 4]\nrandom.shuffle(cards)\nprint(sorted(cards))\n","output":"True\n[1, 2, 3, 4]","runnable":true,"caption":{"en":"Shuffling changes the order, never the items."}},{"type":"text","body":{"en":"`random.seed(n)` makes the sequence repeatable: the same seed always produces the same\n\"random\" values. That is invaluable when testing a game.\n"}},{"type":"code","code":"import random\nrandom.seed(42)\nfirst = random.randint(1, 100)\nrandom.seed(42)\nsecond = random.randint(1, 100)\nprint(first == second)\n","output":"True","runnable":true},{"type":"callout","variant":"note","body":{"en":"`random` is fine for games and simulations. For anything secret, such as passwords or\ntokens, Python has a separate module called `secrets`.\n"}},{"type":"question","question_id":"1beca1db-9654-442f-9851-2fac22b0bda6"},{"type":"question","question_id":"d4e26083-02c6-465d-89dc-41bfe3edc3f5"},{"type":"question","question_id":"5b5432b8-3b56-47ed-a3d9-7a1dd9a393c2"},{"type":"question","question_id":"2834ca5e-73f3-40f9-abf6-9071835e48e7"},{"type":"question","question_id":"8f8132ee-c982-475b-9099-a324454886fc"},{"type":"question","question_id":"d3582b11-daf5-471f-997e-3c239f7243ef"}]'::jsonb, '87f42b8d4c278cc6c7a084bd63d7cbbe'),
  ('a284ef71-f492-464a-97ca-5f58ae5b47c8', '[{"type":"text","body":{"en":"`Counter`, from the `collections` module, does the counting pattern in one line.\n`most_common(n)` gives the `n` most frequent items with their counts.\n"}},{"type":"code","code":"from collections import Counter\ncounts = Counter(\"banana\")\nprint(counts[\"a\"])\nprint(counts.most_common(1))\n","output":"3\n[(''a'', 3)]","runnable":true},{"type":"text","body":{"en":"The `datetime` module handles dates. Subtracting one `date` from another gives a\nduration, and its `.days` is the number of days between them.\n"}},{"type":"code","code":"from datetime import date\nstart = date(2024, 1, 1)\nend = date(2024, 3, 1)\nprint((end - start).days)\nprint(end.year)\n","output":"60\n2024","runnable":true,"caption":{"en":"31 days of January plus 29 of February — 2024 was a leap year."}},{"type":"text","body":{"en":"`timedelta` moves a date forward or back. Month and year boundaries are handled for\nyou.\n"}},{"type":"code","code":"from datetime import date, timedelta\nd = date(2024, 12, 30)\nprint(d + timedelta(days=3))\n","output":"2025-01-02","runnable":true},{"type":"callout","variant":"tip","body":{"en":"`date.today()` gives the real current date, which is what an app usually wants. These\nexamples use fixed dates so that the answers never change.\n"}},{"type":"question","question_id":"628732f3-579e-42b4-8b9e-c511dd76e832"},{"type":"question","question_id":"c8b1362a-eb04-408c-bdc6-4049cb4f2f14"},{"type":"question","question_id":"424f3bff-68c1-4df7-be46-d0d59c961e45"},{"type":"question","question_id":"d9120875-f9b5-4770-8c26-133c6caeb39e"},{"type":"question","question_id":"89eb101e-4a27-4671-9a94-d50906246020"},{"type":"question","question_id":"5315abf0-798a-49d7-956f-d2d8b16b17c7"}]'::jsonb, '3c94ed0a0f14089dbb98085adc0aa91a'),
  ('ef7e193a-d1e2-4f37-9b65-bc9c25e97f69', '[{"type":"text","body":{"en":"A **class** is a blueprint for a kind of thing. An **object** is one thing built from\nthat blueprint. You have used objects all along — every string and every list is one.\nNow you can design your own.\n"}},{"type":"code","code":"class Dog:\n    pass\n\nrex = Dog()\nfido = Dog()\nprint(isinstance(rex, Dog))\nprint(rex is fido)\n","output":"True\nFalse","runnable":true,"caption":{"en":"`pass` means \"nothing here yet\". Two calls to `Dog()` build two separate dogs."}},{"type":"text","body":{"en":"An object can carry its own data in **attributes**, reached with a dot. The next\nlesson shows the proper way to set them up; for now, one can simply be assigned.\n"}},{"type":"code","code":"class Dog:\n    pass\n\nrex = Dog()\nrex.name = \"Rex\"\nprint(rex.name)\n","output":"Rex","runnable":true},{"type":"callout","variant":"note","body":{"en":"Class names are written in CapitalisedWords — `Dog`, `BankAccount` — which tells a\nreader at a glance that the name is a class and not a variable.\n"}},{"type":"callout","variant":"mistake","body":{"en":"The brackets matter. `rex = Dog()` builds a new dog; `rex = Dog` just gives the\nblueprint itself a second name.\n"}},{"type":"question","question_id":"5191e30e-d6d4-425c-9b6c-f209366f52cc"},{"type":"question","question_id":"e4e86d2b-571b-42a5-942d-4edfa00265c8"},{"type":"question","question_id":"12a22054-2a7d-44e1-92f3-e334c3e89dd5"},{"type":"question","question_id":"7a215518-1a69-44d9-b734-a42b160f7a0b"},{"type":"question","question_id":"9eb5dc5d-5f4f-43fb-84ad-337f052a69a2"}]'::jsonb, 'c85cad4f1e05050d14b2a7cb56476fe2'),
  ('659f290a-3e00-4b81-9972-4e598d2b42dc', '[{"type":"text","body":{"en":"A method called `__init__` runs automatically every time an object is created. Its\nfirst parameter, `self`, is the new object itself, and assigning to `self.something`\ngives that object an attribute.\n"}},{"type":"code","code":"class Dog:\n    def __init__(self, name, age):\n        self.name = name\n        self.age = age\n\nrex = Dog(\"Rex\", 3)\nprint(rex.name, rex.age)\n","output":"Rex 3","runnable":true,"caption":{"en":"You pass only name and age. Python supplies self for you."}},{"type":"text","body":{"en":"Every object gets its own attributes. Changing one dog''s name has no effect on any\nother dog.\n"}},{"type":"code","code":"class Dog:\n    def __init__(self, name):\n        self.name = name\n\na = Dog(\"Rex\")\nb = Dog(\"Fido\")\nprint(a.name)\nprint(b.name)\n","output":"Rex\nFido","runnable":true},{"type":"callout","variant":"mistake","body":{"en":"Writing `name = name` inside `__init__` only creates a local variable, which vanishes\nwhen `__init__` ends. It must be `self.name = name` for the object to keep it.\n"}},{"type":"question","question_id":"e7f83003-447d-498a-91c8-edd153c5900e"},{"type":"question","question_id":"9b29f805-37fc-4213-a04a-93c2305493e2"},{"type":"question","question_id":"940e37d7-3289-46db-aada-2d07d7ad960a"},{"type":"question","question_id":"6e782a0c-f07d-4384-82c8-0a1f916a8183"},{"type":"question","question_id":"0c7ed0dd-091b-4270-bd9a-0425af8c2afc"},{"type":"question","question_id":"d58dd52d-24c2-4136-8096-457ddb912b1f"}]'::jsonb, 'c6b16d7c360c9ddcda6a68a0b4de5cfc'),
  ('21ecdae3-8c50-46eb-b368-e36591f98e73', '[{"type":"text","body":{"en":"A **method** is a function defined inside a class. Its first parameter is always\n`self`, which gives it access to the object''s attributes.\n"}},{"type":"code","code":"class Rectangle:\n    def __init__(self, w, h):\n        self.w = w\n        self.h = h\n\n    def area(self):\n        return self.w * self.h\n\nr = Rectangle(3, 4)\nprint(r.area())\n","output":"12","runnable":true},{"type":"text","body":{"en":"Methods can change an object as well as read it. The changes last, because they are\nmade to the object''s own attributes.\n"}},{"type":"code","code":"class Account:\n    def __init__(self):\n        self.balance = 0\n\n    def deposit(self, amount):\n        self.balance += amount\n\nacc = Account()\nacc.deposit(50)\nacc.deposit(25)\nprint(acc.balance)\n","output":"75","runnable":true},{"type":"callout","variant":"note","body":{"en":"When calling a method you never pass `self`. Python passes the object before the dot\nfor you: `r.area()` is really `Rectangle.area(r)`.\n"}},{"type":"question","question_id":"4022d91c-58f8-49ce-85a3-2c8f3f0ab363"},{"type":"question","question_id":"2377c20d-f693-4989-b2b7-501335001297"},{"type":"question","question_id":"e2474450-e270-4cce-868a-6344c24d1f2b"},{"type":"question","question_id":"789e7ca4-e82e-4d48-b46e-6e4beb370686"},{"type":"question","question_id":"42cb0f90-a903-42a1-bf77-c7d96ff647da"},{"type":"question","question_id":"abf28095-14cf-46df-aa83-b0ee84971488"}]'::jsonb, '185524509b61fe6315ed634941bfe682'),
  ('40305ec5-0370-4985-ad6e-554134c14d81', '[{"type":"text","body":{"en":"Printing an object of your own class normally shows its class name and a memory\naddress — accurate, but useless to a person. Define a method called `__str__` that\nreturns a string, and that string is what `print` shows.\n"}},{"type":"code","code":"class Point:\n    def __init__(self, x, y):\n        self.x = x\n        self.y = y\n\n    def __str__(self):\n        return f\"({self.x}, {self.y})\"\n\np = Point(2, 5)\nprint(p)\n","output":"(2, 5)","runnable":true},{"type":"text","body":{"en":"`str()` and f-strings use the same method, so one definition covers every way the\nobject is turned into text.\n"}},{"type":"code","code":"class Point:\n    def __init__(self, x, y):\n        self.x = x\n        self.y = y\n\n    def __str__(self):\n        return f\"({self.x}, {self.y})\"\n\np = Point(2, 5)\nprint(f\"Point: {p}\")\nprint(str(p) == \"(2, 5)\")\n","output":"Point: (2, 5)\nTrue","runnable":true},{"type":"callout","variant":"mistake","body":{"en":"`__str__` must **return** a string. Printing inside it and returning nothing makes\nPython stop with a TypeError the moment the object is printed.\n"}},{"type":"question","question_id":"b8ac82ed-d2ce-46e5-917d-218d97e9f093"},{"type":"question","question_id":"7a79455c-e362-424c-abd4-281799b79bef"},{"type":"question","question_id":"d3632037-f3b2-4669-816c-bc9c2074401d"},{"type":"question","question_id":"6001b7df-dd23-448e-ae29-862af8cbeaa2"},{"type":"question","question_id":"6c5e2cf7-8f55-4271-ac84-6d1074eefd88"}]'::jsonb, '5ec1b6ece3b1d34cdaa56dab159f5594'),
  ('7d62e2b5-b672-40a5-8d4e-72cea26fb726', '[{"type":"text","body":{"en":"A class can **inherit** from another: write the parent in brackets after the new\nclass''s name. The child gets every method of the parent, and can replace — or\n**override** — any of them with its own version.\n"}},{"type":"code","code":"class Animal:\n    def __init__(self, name):\n        self.name = name\n\n    def speak(self):\n        return \"...\"\n\nclass Dog(Animal):\n    def speak(self):\n        return \"Woof\"\n\nclass Cat(Animal):\n    def speak(self):\n        return \"Meow\"\n\nfor pet in [Dog(\"Rex\"), Cat(\"Tom\")]:\n    print(pet.name, pet.speak())\n","output":"Rex Woof\nTom Meow","runnable":true,"caption":{"en":"Neither Dog nor Cat defines __init__, so both use Animal''s."}},{"type":"text","body":{"en":"When a child needs to add to the parent''s setup rather than replace it, `super()`\ncalls the parent''s version.\n"}},{"type":"code","code":"class Animal:\n    def __init__(self, name):\n        self.name = name\n\nclass Dog(Animal):\n    def __init__(self, name, breed):\n        super().__init__(name)\n        self.breed = breed\n\nd = Dog(\"Rex\", \"Beagle\")\nprint(d.name, d.breed)\n","output":"Rex Beagle","runnable":true},{"type":"callout","variant":"tip","body":{"en":"Inherit when the child really is a kind of the parent — a Dog is an Animal. When one\nthing merely uses another, give it an attribute instead.\n"}},{"type":"question","question_id":"477c626d-febf-4b8b-8f0d-cbf6180da4e4"},{"type":"question","question_id":"8aa2e230-9a56-4588-afca-09d67237f0cf"},{"type":"question","question_id":"b3bbc269-0537-4bf6-abad-50399d1b4ec6"},{"type":"question","question_id":"dcacb064-2af9-4a62-b267-180863d75ac9"},{"type":"question","question_id":"ae6e155f-e419-476c-b4f8-d711848c11e2"},{"type":"question","question_id":"f2b1c927-5189-406a-b0ac-47d2745e7087"}]'::jsonb, 'd86f1424d20a8a91ea37329bebe01a33'),
  ('c67de1e5-fb2c-4114-9177-b0b3f72df446', '[{"type":"text","body":{"en":"Most problems feel hard until they are broken into steps. Before writing any code,\ndescribe what you would do by hand, in plain words. Each step usually becomes a few\nlines of code — or a function of its own.\n"}},{"type":"text","body":{"en":"Take \"find the longest word in a sentence\". By hand: split the sentence into words,\nremember the longest one seen so far, compare each word with it, and hand back the\nwinner. That description is already most of the program.\n"}},{"type":"code","code":"def longest_word(sentence):\n    best = \"\"\n    for word in sentence.split():\n        if len(word) > len(best):\n            best = word\n    return best\n\nprint(longest_word(\"the quick brown fox\"))\n","output":"quick","runnable":true,"caption":{"en":"\"quick\" and \"brown\" are both five letters. `>` only replaces on a strictly longer word, so the first one wins."}},{"type":"text","body":{"en":"Then test with small examples — especially awkward ones. What happens with an empty\nsentence? With a tie? Knowing the answer to those is what separates code that works\nfrom code that happens to work.\n"}},{"type":"code","code":"def longest_word(sentence):\n    best = \"\"\n    for word in sentence.split():\n        if len(word) > len(best):\n            best = word\n    return best\n\nprint(longest_word(\"\") == \"\")\n","output":"True","runnable":true},{"type":"callout","variant":"tip","body":{"en":"When you are stuck, solve a tiny version on paper first and write down exactly what you\ndid. Those notes are the plan.\n"}},{"type":"question","question_id":"f63f5f1f-e3e9-4539-abbc-4511683e6e65"},{"type":"question","question_id":"8952c80d-4290-43d5-9201-e1dc4141974a"},{"type":"question","question_id":"10bdcc64-5027-49c8-a47d-fb406de78b36"},{"type":"question","question_id":"647d8445-b52e-448a-8825-21290203b32c"},{"type":"question","question_id":"a5b4a90d-32fa-411e-86c5-fd308ed31b08"}]'::jsonb, '0fa00ee73687adb0826de291749f7423'),
  ('bf086c8a-ca58-41e4-9895-86cb77574926', '[{"type":"text","body":{"en":"**Linear search** checks each item in turn until it finds the target. It returns the\nposition where it found it, or -1 to say \"not here\".\n"}},{"type":"code","code":"def find(items, target):\n    for i in range(len(items)):\n        if items[i] == target:\n            return i\n    return -1\n\nprint(find([4, 8, 15], 8))\nprint(find([4, 8, 15], 99))\n","output":"1\n-1","runnable":true,"caption":{"en":"The `return` inside the loop stops the search the moment the target is found."}},{"type":"text","body":{"en":"Python already does linear search for you: `in` answers yes or no, and a list''s\n`index` method gives the position. Unlike `find` above, `index` raises a ValueError\nwhen the item is missing.\n"}},{"type":"code","code":"nums = [4, 8, 15]\nprint(15 in nums)\nprint(nums.index(15))\n","output":"True\n2","runnable":true},{"type":"callout","variant":"note","body":{"en":"In the worst case — the target is last, or not there at all — linear search looks at\nevery single item. Twice the data means twice the checks.\n"}},{"type":"question","question_id":"e243dda0-6dbd-4305-b621-99bc63281d86"},{"type":"question","question_id":"dbb8cb4a-0987-4742-9373-bfec05fd5369"},{"type":"question","question_id":"1ac71d7c-01fb-4222-a634-9d1e42831160"},{"type":"question","question_id":"455a6f98-0480-42d4-911d-76d6de5b32ef"},{"type":"question","question_id":"9b247d5b-684d-4736-86c5-2e2dedbf1e8d"},{"type":"question","question_id":"bdeabf1b-dba9-4494-ac3c-b5bcf569ff56"}]'::jsonb, '89ce6d1a26dee3710e34ff3535c46eb5'),
  ('f7fee9c3-1b51-4e38-afee-b80392ff9c5b', '[{"type":"text","body":{"en":"When a list is **sorted**, you can search it far faster. Look at the middle item. If\nthe target is bigger, it can only be in the right half; if smaller, only in the left.\nThrow the other half away and repeat.\n"}},{"type":"code","code":"def binary_search(items, target):\n    low = 0\n    high = len(items) - 1\n    while low <= high:\n        mid = (low + high) // 2\n        if items[mid] == target:\n            return mid\n        elif items[mid] < target:\n            low = mid + 1\n        else:\n            high = mid - 1\n    return -1\n\nnums = [2, 5, 8, 12, 16, 23, 38]\nprint(binary_search(nums, 23))\nprint(binary_search(nums, 7))\n","output":"5\n-1","runnable":true,"caption":{"en":"`low` and `high` mark the part of the list still worth searching."}},{"type":"text","body":{"en":"Every check halves what is left. A thousand items need at most about 10 checks; a\nmillion need about 20. A linear search of that million could need a million.\n"}},{"type":"callout","variant":"mistake","body":{"en":"Binary search only works on a sorted list. On an unsorted one it throws away halves\nthat may hold the target, and reports \"not found\" for items that are there.\n"}},{"type":"question","question_id":"081e539c-bf6d-49ca-9903-7ff8888e30f3"},{"type":"question","question_id":"408ff317-0f94-41f9-aaf1-0ed0df8af64b"},{"type":"question","question_id":"7e4846a1-8a46-4082-98b8-eebb0c418137"},{"type":"question","question_id":"170f6997-d041-4045-b622-5d3e8fe935b1"},{"type":"question","question_id":"c2f2c3ff-78f6-4c77-b4a7-c286092caf1d"},{"type":"question","question_id":"7e2e57ce-4a3d-4743-8cba-97dd3162e7b8"}]'::jsonb, '30fa9d13a01c691e2913e8c56f6e8a98'),
  ('9c569460-bf7e-4954-a766-a690a521a17e', '[{"type":"text","body":{"en":"`sorted()` does the work for you, but seeing one sort built by hand shows what it\ninvolves. **Selection sort** repeatedly finds the smallest remaining item and swaps\nit to the front.\n"}},{"type":"code","code":"def selection_sort(items):\n    items = items[:]\n    for i in range(len(items)):\n        smallest = i\n        for j in range(i + 1, len(items)):\n            if items[j] < items[smallest]:\n                smallest = j\n        items[i], items[smallest] = items[smallest], items[i]\n    return items\n\nprint(selection_sort([5, 2, 9, 1]))\n","output":"[1, 2, 5, 9]","runnable":true,"caption":{"en":"`items[:]` makes a copy first, so the caller''s list is left untouched."}},{"type":"text","body":{"en":"In real code, use `sorted`. Its `key` argument takes a function that says **what** to\nsort by. With `key=len`, words are sorted by their length.\n"}},{"type":"code","code":"words = [\"banana\", \"fig\", \"cherry\"]\nprint(sorted(words, key=len))\n","output":"[''fig'', ''banana'', ''cherry'']","runnable":true,"caption":{"en":"banana and cherry tie on length, so they keep their original order."}},{"type":"code","code":"def age(person):\n    return person[1]\n\npeople = [(\"Ann\", 31), (\"Bo\", 25), (\"Cy\", 40)]\nprint(sorted(people, key=age))\n","output":"[(''Bo'', 25), (''Ann'', 31), (''Cy'', 40)]","runnable":true},{"type":"callout","variant":"note","body":{"en":"`key` takes the function itself, without brackets: `key=len`, not `key=len()`.\n`sorted` calls it once for every item.\n"}},{"type":"question","question_id":"72157474-3210-4c3f-a6b8-827cc3d4f47f"},{"type":"question","question_id":"ec9c6a27-8a70-4dd8-9dc4-b49d5463c65b"},{"type":"question","question_id":"1743b141-96c6-4e59-b025-414608bb9f6a"},{"type":"question","question_id":"5c036228-c9d9-4dd9-aa79-0ded7be58b33"},{"type":"question","question_id":"ef7df51d-6374-496b-85bd-3b1334b336c6"},{"type":"question","question_id":"356e7236-1507-47f0-993e-b2093fb748d9"}]'::jsonb, '1fbebe864574baa853930bbd4249cc47'),
  ('81eb31bd-096a-48a2-8a45-f0eee17f7453', '[{"type":"text","body":{"en":"Two programs can give the same answer and still differ hugely in how much work they\ndo. The useful question is how that work **grows** as the data gets bigger. You can\nfind out by counting steps.\n"}},{"type":"code","code":"def count_steps(n):\n    steps = 0\n    for i in range(n):\n        steps += 1\n    return steps\n\nprint(count_steps(10), count_steps(100))\n","output":"10 100","runnable":true,"caption":{"en":"One loop — ten times the data, ten times the work."}},{"type":"code","code":"def pair_steps(n):\n    steps = 0\n    for i in range(n):\n        for j in range(n):\n            steps += 1\n    return steps\n\nprint(pair_steps(10), pair_steps(100))\n","output":"100 10000","runnable":true,"caption":{"en":"A loop inside a loop — ten times the data, a hundred times the work."}},{"type":"text","body":{"en":"**Big-O** notation names these growth rates. **O(1)** is constant, like reading\n`items[0]`. **O(log n)** grows very slowly, like binary search. **O(n)** grows in step\nwith the data, like linear search. **O(n²)** is a loop inside a loop over the same\ndata.\n"}},{"type":"callout","variant":"tip","body":{"en":"For a few hundred items none of this matters. It matters as data grows: ten times\nmore means ten times the work for O(n), a hundred times for O(n²), and barely any\nmore for O(log n).\n"}},{"type":"question","question_id":"03c44efe-fe67-4e7a-b589-0e1af7c4ff40"},{"type":"question","question_id":"556fcb7a-5c52-4495-8a74-3000b26049b3"},{"type":"question","question_id":"b3eaf188-9c1e-4ce5-a54f-1e4487315c55"},{"type":"question","question_id":"b7f5a017-85d0-43da-a7a3-f93bf57efc62"},{"type":"question","question_id":"9fb55aff-f7b1-467c-8092-b5da56f3a70b"},{"type":"question","question_id":"85b325e3-0acc-4378-bf3b-62353a5f9dcc"}]'::jsonb, '53697147fc8d504156647f44cbab26ef')
on conflict (lesson_id) do update set
  blocks = excluded.blocks,
  content_hash = excluded.content_hash
;

insert into public.questions (id, lesson_id, type, difficulty, prompt, code_snippet, payload, explanation, hint, xp_reward, is_premium, is_challenge_eligible, is_exam_eligible, skill_tags, order_index, review_status, content_hash) values
  ('a1a77c7f-c0a4-4320-8fd0-734d9d9d895a', 'ae47f49b-9ada-4145-af64-a445fd72dc15', 'true_false'::public.question_type, 'easy'::public.difficulty_level, '{"en":"Python runs the lines of a program from top to bottom, in order."}'::jsonb, null, '{}'::jsonb, '{"en":"Yes. The interpreter starts at the first line and works downwards. Later you will meet ways to repeat lines or skip them, but the default is always straight down.\n"}'::jsonb, null, null, false, true, true, array['python-basics']::text[], 1, 'reviewed'::public.review_status, 'e08364592067d834f438ded580e435c0'),
  ('f931c8e5-5cf2-41f0-95c0-8ee0f585bb40', 'ae47f49b-9ada-4145-af64-a445fd72dc15', 'multiple_choice'::public.question_type, 'easy'::public.difficulty_level, '{"en":"What is the interpreter?"}'::jsonb, null, '{"options":[{"id":"reads-and-runs","text":{"en":"The program that reads your code and carries out the instructions"}},{"id":"text-editor","text":{"en":"The editor you type your code into"}},{"id":"error-checker","text":{"en":"A tool that only checks your code for mistakes"}},{"id":"website","text":{"en":"The website where Python is downloaded"}}]}'::jsonb, '{"en":"The interpreter is what actually runs your program. Your editor helps you write the text, but on its own it does nothing — the interpreter is what turns that text into something happening.\n"}'::jsonb, '{"en":"Think about which one does something when you press \"run\"."}'::jsonb, null, false, true, true, array['python-basics']::text[], 2, 'reviewed'::public.review_status, '82ab22103bb28f33106620c62587f1ef'),
  ('2f2a58fa-0c26-4b3d-9b20-825ea7d3be34', 'ae47f49b-9ada-4145-af64-a445fd72dc15', 'predict_output'::public.question_type, 'easy'::public.difficulty_level, '{"en":"What does this program print?"}'::jsonb, 'print("Python")
', '{"input":"text"}'::jsonb, '{"en":"`print` shows whatever is inside the brackets. The quotes mark where the text starts and ends — they tell Python how much of the line is text, and are not printed.\n"}'::jsonb, null, null, false, true, true, array['python-basics', 'printing']::text[], 3, 'reviewed'::public.review_status, '872d6698b50f1f97c9587834a59efa62'),
  ('87b202d9-5f8a-4f33-a208-81b1775a74b9', 'ae47f49b-9ada-4145-af64-a445fd72dc15', 'multiple_select'::public.question_type, 'medium'::public.difficulty_level, '{"en":"Which of these are true about Python?"}'::jsonb, null, '{"options":[{"id":"reads-like-english","text":{"en":"Its syntax is designed to be readable"}},{"id":"runs-top-to-bottom","text":{"en":"A program runs from top to bottom by default"}},{"id":"needs-compiling","text":{"en":"You must compile a program into a separate file before running it"}},{"id":"only-websites","text":{"en":"It can only be used to build websites"}},{"id":"plain-text","text":{"en":"You write programs as plain text"}}]}'::jsonb, '{"en":"Python is plain text, readable, and runs top to bottom. It does not need a separate compile step, and it is used well beyond the web — data analysis, automation, science and more.\n"}'::jsonb, null, null, false, true, true, array['python-basics']::text[], 4, 'reviewed'::public.review_status, 'b2f6854bc20beb3fe60ebf71266cfe31'),
  ('12c1b591-5eca-4a56-88e1-a6c8847efe6f', 'ae47f49b-9ada-4145-af64-a445fd72dc15', 'multiple_choice'::public.question_type, 'easy'::public.difficulty_level, '{"en":"You have written a Python file but never run it. What has happened so far?"}'::jsonb, null, '{"options":[{"id":"nothing","text":{"en":"Nothing — it is just text until the interpreter runs it"}},{"id":"half","text":{"en":"Python has already run the first line"}},{"id":"checked","text":{"en":"Python has checked the whole file for mistakes"}},{"id":"saved-output","text":{"en":"The output has been saved, ready to show"}}]}'::jsonb, '{"en":"A Python file is only text until something runs it. That is why a mistake can sit in a file unnoticed for a long time — nobody finds it until that line actually runs.\n"}'::jsonb, null, null, false, false, true, array['python-basics']::text[], 5, 'reviewed'::public.review_status, '3efc35f3cace1483f16cf4de7d8c5b7a'),
  ('3c5222fe-517a-49ac-91d7-1a137a528870', '8b14ce7b-46ce-44a3-b97a-92d34a1689d4', 'predict_output'::public.question_type, 'easy'::public.difficulty_level, '{"en":"What does this print?"}'::jsonb, 'print("Score:", 10)
', '{"input":"text"}'::jsonb, '{"en":"The comma separates two items, and Python joins them with a single space. You did not type that space — printing several items always puts one between each pair.\n"}'::jsonb, null, null, false, true, true, array['printing']::text[], 1, 'reviewed'::public.review_status, 'de65b20984cefbd40d9cf9430a77d68d'),
  ('16cdc674-e894-45ae-b0d6-54446f427e50', '8b14ce7b-46ce-44a3-b97a-92d34a1689d4', 'predict_output'::public.question_type, 'easy'::public.difficulty_level, '{"en":"What does this print?"}'::jsonb, 'print("up")
print("down")
', '{"input":"choice","options":[{"id":"two-lines","text":{"en":"up\ndown"}},{"id":"one-line-space","text":{"en":"up down"}},{"id":"one-line-joined","text":{"en":"updown"}},{"id":"reversed","text":{"en":"down\nup"}}]}'::jsonb, '{"en":"Every `print` ends its line, so two calls give two lines. They run in the order they are written, which is why \"up\" comes first.\n"}'::jsonb, null, null, false, true, true, array['printing']::text[], 2, 'reviewed'::public.review_status, '3f95e0bba2b584e33b3c041bceb06823'),
  ('fb9e4bbf-0fd7-435f-b470-ff2be737db00', '8b14ce7b-46ce-44a3-b97a-92d34a1689d4', 'fill_blank'::public.question_type, 'easy'::public.difficulty_level, '{"en":"Complete the line so the program displays the word Ready."}'::jsonb, '___("Ready")
', '{"input":"tokens","tokens":["print","show","display","say"]}'::jsonb, '{"en":"`print` is the built-in name Python understands. `show`, `display` and `say` read like English but mean nothing to Python — it only knows the names it was given.\n"}'::jsonb, '{"en":"Which of these have you actually seen in a Python program?"}'::jsonb, null, false, true, true, array['printing']::text[], 3, 'reviewed'::public.review_status, 'cea77a7a26811b582b99acd09ebc7a98'),
  ('772a78bc-1901-431c-b779-cedc8112f099', '8b14ce7b-46ce-44a3-b97a-92d34a1689d4', 'multiple_choice'::public.question_type, 'medium'::public.difficulty_level, '{"en":"What does `print(\"3\" + \"4\")` display?"}'::jsonb, null, '{"options":[{"id":"joined","text":{"en":"34"}},{"id":"added","text":{"en":"7"}},{"id":"spaced","text":{"en":"3 4"}},{"id":"error","text":{"en":"An error, because you cannot add text"}}]}'::jsonb, '{"en":"Both values are text, because of the quotes. For text, `+` means \"join end to end\", so \"3\" and \"4\" become \"34\". Without the quotes it would be arithmetic and give 7.\n"}'::jsonb, '{"en":"Look carefully at where the quotes are."}'::jsonb, null, false, true, true, array['printing', 'data-types']::text[], 4, 'reviewed'::public.review_status, '81887c8ba7362644fe8eb1aade8db081'),
  ('d6ea8906-8c5b-4c72-9627-e468f1ab4180', '8b14ce7b-46ce-44a3-b97a-92d34a1689d4', 'code_ordering'::public.question_type, 'medium'::public.difficulty_level, '{"en":"Arrange these lines so the program counts down from three."}'::jsonb, null, '{"lines":[{"id":"three","text":"print(3)"},{"id":"two","text":"print(2)"},{"id":"one","text":"print(1)"},{"id":"go","text":"print(\"Go!\")"}]}'::jsonb, '{"en":"Python runs lines top to bottom, so the order you write them in is exactly the order they happen in. Counting down means writing them in descending order.\n"}'::jsonb, null, null, false, true, true, array['printing', 'python-basics']::text[], 5, 'reviewed'::public.review_status, '8b46c31353c233c03b6997b4f4a7048f'),
  ('ab04f186-d7f8-48e2-8daf-85978472e4bf', 'a6e49edf-a740-4668-a22d-c1c46a544b0f', 'true_false'::public.question_type, 'easy'::public.difficulty_level, '{"en":"Python runs the text that comes after a `#`."}'::jsonb, null, '{}'::jsonb, '{"en":"It ignores it completely. Everything from the `#` to the end of that line is for the reader, which is exactly why commenting out a line stops it working.\n"}'::jsonb, null, null, false, true, true, array['comments']::text[], 1, 'reviewed'::public.review_status, '558bfedb4442bd6bb71060a46902f2c8'),
  ('a08adf6b-69a1-46dd-a631-c199ceddbbb6', 'a6e49edf-a740-4668-a22d-c1c46a544b0f', 'predict_output'::public.question_type, 'easy'::public.difficulty_level, '{"en":"What does this print?"}'::jsonb, '# print("one")
print("two")
', '{"input":"text"}'::jsonb, '{"en":"The first line is commented out, so it never runs. Only the second line produces output — which is why a stray `#` can make code look broken for no visible reason.\n"}'::jsonb, null, null, false, true, true, array['comments', 'printing']::text[], 2, 'reviewed'::public.review_status, 'e78ebd9e1c58a2314732ce4bd89fd3b5'),
  ('bdaf51c1-50b6-4c06-b365-3de70c98ff4b', 'a6e49edf-a740-4668-a22d-c1c46a544b0f', 'multiple_choice'::public.question_type, 'medium'::public.difficulty_level, '{"en":"Which comment is the most useful?"}'::jsonb, null, '{"options":[{"id":"why","text":{"en":"# prices are stored in cents to avoid rounding errors"}},{"id":"what","text":{"en":"# print the price"}},{"id":"obvious","text":{"en":"# this is a comment"}},{"id":"empty","text":{"en":"#"}}]}'::jsonb, '{"en":"The first says something the code cannot: a decision and its reason. The others repeat what is already visible, which means they add reading work without adding understanding — and they go stale when the code changes.\n"}'::jsonb, null, null, false, true, false, array['comments']::text[], 3, 'reviewed'::public.review_status, 'f2cf3fae8026872fa2d12ce61121e67a'),
  ('c3c78549-af7e-42c7-9962-6c2b9042d5ae', 'a6e49edf-a740-4668-a22d-c1c46a544b0f', 'fill_blank'::public.question_type, 'easy'::public.difficulty_level, '{"en":"Complete the line so Python ignores the note at the end."}'::jsonb, 'print("done") ___ finished for today
', '{"input":"tokens","tokens":["#","//","--","**"]}'::jsonb, '{"en":"Python uses `#`. The others start comments in other languages — `//` in JavaScript, `--` in SQL — and Python would try to read them as code and fail.\n"}'::jsonb, null, null, false, true, true, array['comments']::text[], 4, 'reviewed'::public.review_status, '18092a800b31554a822e9eeab149a61c'),
  ('cf7fcce7-ca2c-446d-8acc-a9827967786e', 'a6e49edf-a740-4668-a22d-c1c46a544b0f', 'debugging'::public.question_type, 'medium'::public.difficulty_level, '{"en":"This should greet the user and then show the total, but the greeting never appears. Which line is the problem?\n"}'::jsonb, '# print("Welcome!")
total = 12
print(total)
', '{"mode":"select_line","lines":[{"id":"greeting","text":"# print(\"Welcome!\")"},{"id":"total","text":"total = 12"},{"id":"show","text":"print(total)"}]}'::jsonb, '{"en":"The greeting is commented out, so it never runs. Nothing reports an error, because a comment is perfectly valid — the line simply does nothing. Silent failures like this are why a forgotten `#` can cost so much time.\n"}'::jsonb, '{"en":"Look for a line that Python is ignoring."}'::jsonb, null, false, true, true, array['comments', 'debugging']::text[], 5, 'reviewed'::public.review_status, '446ac0906e5c460f43c55912a48efd88'),
  ('8764fe6c-31ad-43e4-aa11-b920b095f9d2', '4df3daa1-5801-4173-b93d-46ce15a385cd', 'multiple_choice'::public.question_type, 'easy'::public.difficulty_level, '{"en":"Which part of an error message tells you where to look first?"}'::jsonb, null, '{"options":[{"id":"line-number","text":{"en":"The line number"}},{"id":"length","text":{"en":"How long the message is"}},{"id":"first-word","text":{"en":"The first word of the file"}},{"id":"colour","text":{"en":"The colour it is printed in"}}]}'::jsonb, '{"en":"The line number narrows hours of searching down to one line. Check it first, and if that line looks correct, check the line above — a SyntaxError often surfaces late.\n"}'::jsonb, null, null, false, true, true, array['errors']::text[], 1, 'reviewed'::public.review_status, '3a65b93d88eae6589fb0645ed205625b'),
  ('95b7fe8c-8ae5-4930-b84a-9d07f3a43192', '4df3daa1-5801-4173-b93d-46ce15a385cd', 'multiple_choice'::public.question_type, 'medium'::public.difficulty_level, '{"en":"Python says: `NameError: name ''totl'' is not defined`. What has most likely happened?"}'::jsonb, null, '{"options":[{"id":"typo","text":{"en":"A name was misspelled"}},{"id":"broken-python","text":{"en":"Python is installed incorrectly"}},{"id":"too-long","text":{"en":"The name is too long"}},{"id":"needs-quotes","text":{"en":"The name needs quotation marks around it"}}]}'::jsonb, '{"en":"A NameError means Python has never seen that name. Nine times out of ten it is a misspelling of something you did define — here, `totl` where `total` was meant.\n"}'::jsonb, '{"en":"Read the name in the message out loud."}'::jsonb, null, false, true, true, array['errors', 'debugging']::text[], 2, 'reviewed'::public.review_status, 'bd8a1e555995c715d5c714a44ecef94b'),
  ('6ab13905-9dd5-48b5-b9de-3e36cc96ac0a', '4df3daa1-5801-4173-b93d-46ce15a385cd', 'concept_matching'::public.question_type, 'medium'::public.difficulty_level, '{"en":"Match each error type to what causes it."}'::jsonb, null, '{"concepts":[{"id":"syntax","text":{"en":"SyntaxError"}},{"id":"name","text":{"en":"NameError"}},{"id":"type","text":{"en":"TypeError"}}],"definitions":[{"id":"not-valid-python","text":{"en":"The text is not valid Python, so nothing runs at all"}},{"id":"never-seen","text":{"en":"A name was used that Python has never been given"}},{"id":"wrong-kind","text":{"en":"The operation is fine, but not for that kind of value"}}]}'::jsonb, '{"en":"The three differ in when they happen. A SyntaxError stops the program before it starts. A NameError and a TypeError happen while it runs, which means everything before that line already did its work.\n"}'::jsonb, null, null, false, true, true, array['errors']::text[], 3, 'reviewed'::public.review_status, 'a9fe9ddc6af3747e1d34077bc4eb06d0'),
  ('4c85bb3d-07a5-41df-a4f1-ec3fcea3bf10', '4df3daa1-5801-4173-b93d-46ce15a385cd', 'true_false'::public.question_type, 'medium'::public.difficulty_level, '{"en":"If a program has a SyntaxError, the lines before the mistake still run."}'::jsonb, null, '{}'::jsonb, '{"en":"Nothing runs. Python has to read the whole file before it can start, and a SyntaxError means it could not. A NameError is different — it happens while running, so earlier lines have already done their work.\n"}'::jsonb, null, null, false, true, true, array['errors', 'python-basics']::text[], 4, 'reviewed'::public.review_status, 'ea65bcdaa1b8092dd9ad3bc9d100584b'),
  ('a51af7ed-df63-431b-be04-f4762b80590c', '4df3daa1-5801-4173-b93d-46ce15a385cd', 'debugging'::public.question_type, 'easy'::public.difficulty_level, '{"en":"This program will not start. Which line has the mistake?"}'::jsonb, 'print("Ready")
print("Set"
print("Go")
', '{"mode":"select_line","lines":[{"id":"ready","text":"print(\"Ready\")"},{"id":"set","text":"print(\"Set\""},{"id":"go","text":"print(\"Go\")"}]}'::jsonb, '{"en":"The second line never closes its bracket. Python reads on looking for the closing `)`, reaches the next line, and reports the error there — which is why the line it names is often one below the real mistake.\n"}'::jsonb, '{"en":"Count the opening and closing brackets on each line."}'::jsonb, null, false, true, true, array['errors', 'debugging']::text[], 5, 'reviewed'::public.review_status, 'feb6b10742d4053fcef09edb7b96c79e'),
  ('04e705b8-a2ca-4e5e-8821-084eed62ab28', 'a061f1ed-25e6-47db-9bc2-1610f7676d54', 'predict_output'::public.question_type, 'easy'::public.difficulty_level, '{"en":"What does this print?"}'::jsonb, 'city = "Cluj"
print(city)
', '{"input":"text"}'::jsonb, '{"en":"`city` stands for the text \"Cluj\", so printing the name prints the value. Note there are no quotes around `city` in the print — quotes would make it the literal word.\n"}'::jsonb, null, null, false, true, true, array['variables']::text[], 1, 'reviewed'::public.review_status, '6af99cfebcee2b8f47262f435172043a'),
  ('b859ee51-8e4b-4f04-b20c-fc13d23ef29c', 'a061f1ed-25e6-47db-9bc2-1610f7676d54', 'fill_blank'::public.question_type, 'easy'::public.difficulty_level, '{"en":"Complete the line so the name `total` stands for the number 50."}'::jsonb, 'total ___ 50
', '{"input":"tokens","tokens":["=","==",":","=>"]}'::jsonb, '{"en":"A single `=` assigns. A double `==` is a question — it asks whether two values are the same — and you will meet it when you start writing conditions.\n"}'::jsonb, null, null, false, true, true, array['variables']::text[], 2, 'reviewed'::public.review_status, 'd99dbf01c396499640e5068c62102f18'),
  ('57309f58-3482-4930-9a7f-eaa6801b6b43', 'a061f1ed-25e6-47db-9bc2-1610f7676d54', 'multiple_choice'::public.question_type, 'medium'::public.difficulty_level, '{"en":"Why does `5 = score` cause an error?"}'::jsonb, null, '{"options":[{"id":"wrong-side","text":{"en":"The name being assigned to must be on the left"}},{"id":"too-small","text":{"en":"5 is too small to store"}},{"id":"needs-quotes","text":{"en":"Numbers need quotation marks"}},{"id":"reserved","text":{"en":"`score` is a reserved word in Python"}}]}'::jsonb, '{"en":"Assignment always flows right to left: the value on the right is given to the name on the left. `5` is already a number, so there is nothing to name it with.\n"}'::jsonb, '{"en":"Which side of the `=` receives the value?"}'::jsonb, null, false, true, true, array['variables', 'errors']::text[], 3, 'reviewed'::public.review_status, '9c0b948aee7831286e82f58158b489a0'),
  ('ecc4f458-3c1e-48ba-9f4d-de8125d5c911', 'a061f1ed-25e6-47db-9bc2-1610f7676d54', 'code_ordering'::public.question_type, 'medium'::public.difficulty_level, '{"en":"Arrange the lines so the program prints the area of the rectangle."}'::jsonb, null, '{"lines":[{"id":"width","text":"width = 4"},{"id":"height","text":"height = 5"},{"id":"area","text":"area = width * height"},{"id":"show","text":"print(area)"}]}'::jsonb, '{"en":"A name has to exist before it can be used. `area` needs both `width` and `height` already defined, and `print(area)` needs `area`. Running them in any other order gives a NameError.\n"}'::jsonb, null, null, false, true, true, array['variables', 'python-basics']::text[], 4, 'reviewed'::public.review_status, 'b680f6b122a5c1927f1beaaa246ec4e9'),
  ('8eb4cb1b-0219-4f10-bffd-6d834b5c220b', 'a061f1ed-25e6-47db-9bc2-1610f7676d54', 'true_false'::public.question_type, 'easy'::public.difficulty_level, '{"en":"A variable must be created before the line that uses it."}'::jsonb, null, '{}'::jsonb, '{"en":"Python runs top to bottom and only knows a name once it has been assigned. Using it earlier gives a NameError, even if the assignment appears further down the file.\n"}'::jsonb, null, null, false, true, true, array['variables', 'errors']::text[], 5, 'reviewed'::public.review_status, '624be4685312320d617f1ce231d25c54'),
  ('b623e3ea-65c0-41aa-9282-1255ae18f0f0', '3fba4acd-580c-4b58-bb81-3723335f9c95', 'multiple_select'::public.question_type, 'medium'::public.difficulty_level, '{"en":"Which of these are valid variable names in Python?"}'::jsonb, null, '{"options":[{"id":"user-name","text":{"en":"user_name"}},{"id":"score2","text":{"en":"score2"}},{"id":"two-words","text":{"en":"two words"}},{"id":"leading-digit","text":{"en":"2nd_place"}},{"id":"underscore","text":{"en":"_total"}}]}'::jsonb, '{"en":"Letters, digits and underscores are allowed, and a name may start with a letter or an underscore. It may not contain a space, and it may not start with a digit — Python would begin reading `2nd_place` as a number.\n"}'::jsonb, null, null, false, true, true, array['variables', 'naming']::text[], 1, 'reviewed'::public.review_status, '1525c2561f3754d760a1c3afb3d07680'),
  ('93dcaabb-c9f7-4388-8dd7-be3e2ca2aeae', '3fba4acd-580c-4b58-bb81-3723335f9c95', 'predict_output'::public.question_type, 'medium'::public.difficulty_level, '{"en":"What does this print?"}'::jsonb, 'total = 10
Total = 20
print(total)
', '{"input":"text"}'::jsonb, '{"en":"Names are case-sensitive, so `total` and `Total` are two separate variables. The second line creates a new one rather than changing the first — a mistake that produces no error at all, just a wrong answer.\n"}'::jsonb, null, null, false, true, true, array['variables', 'naming']::text[], 2, 'reviewed'::public.review_status, 'a60b1df4d89ff803656bf4603bfae5c9'),
  ('91102369-a309-4de8-be34-02c6bc4c6f72', '3fba4acd-580c-4b58-bb81-3723335f9c95', 'debugging'::public.question_type, 'medium'::public.difficulty_level, '{"en":"This program should print the greeting, but it fails. Which line is wrong?"}'::jsonb, 'message = "Hi there"
print(Message)
', '{"mode":"select_line","lines":[{"id":"assign","text":"message = \"Hi there\""},{"id":"show","text":"print(Message)"}]}'::jsonb, '{"en":"The variable was created as `message` but printed as `Message`. Python treats those as different names, so it reports a NameError for one it has never seen.\n"}'::jsonb, '{"en":"Compare the two names letter by letter."}'::jsonb, null, false, true, true, array['variables', 'naming', 'debugging']::text[], 3, 'reviewed'::public.review_status, 'c0e7fcb7ebb9945d4eb78e948cc8f310'),
  ('5adb7977-9faa-4c44-97f9-851a07dc8c95', '3fba4acd-580c-4b58-bb81-3723335f9c95', 'true_false'::public.question_type, 'easy'::public.difficulty_level, '{"en":"`item count = 5` is a valid way to create a variable."}'::jsonb, null, '{}'::jsonb, '{"en":"A name cannot contain a space — Python would read `item` and then not know what to do with `count`. Use `item_count` instead.\n"}'::jsonb, null, null, false, true, true, array['variables', 'naming']::text[], 4, 'reviewed'::public.review_status, '020b4e21407c3caeab6537ca2ea6e19a'),
  ('796c7463-0715-40eb-a3e5-52c014b93b0e', '3fba4acd-580c-4b58-bb81-3723335f9c95', 'multiple_choice'::public.question_type, 'medium'::public.difficulty_level, '{"en":"Which name best follows Python''s conventions for a person''s date of birth?"}'::jsonb, null, '{"options":[{"id":"snake","text":{"en":"date_of_birth"}},{"id":"camel","text":{"en":"dateOfBirth"}},{"id":"short","text":{"en":"dob"}},{"id":"typed","text":{"en":"str_date"}}]}'::jsonb, '{"en":"Python uses lower case with underscores. `dateOfBirth` is the convention in other languages, `dob` needs explaining, and `str_date` describes the type rather than the meaning — and would be wrong the moment the value changed type.\n"}'::jsonb, null, null, false, true, false, array['naming']::text[], 5, 'reviewed'::public.review_status, '7e139446a5b033167939d21cdef8f97e'),
  ('cd3ed4c6-272d-4c33-bd40-e633e6e1fbff', 'e4d23af9-8917-4945-b4aa-a5ec4878dba5', 'predict_output'::public.question_type, 'easy'::public.difficulty_level, '{"en":"What does this print?"}'::jsonb, 'count = 1
count = 4
print(count)
', '{"input":"text"}'::jsonb, '{"en":"The second assignment replaces the first. A variable holds one value at a time, and the most recent assignment before the print is the one that counts.\n"}'::jsonb, null, null, false, true, true, array['variables', 'reassignment']::text[], 1, 'reviewed'::public.review_status, '2810c675a31825de0e8caf0546085c32'),
  ('56285afe-a6a1-4276-ba21-e15aa10d47f6', 'e4d23af9-8917-4945-b4aa-a5ec4878dba5', 'predict_output'::public.question_type, 'medium'::public.difficulty_level, '{"en":"What does this print?"}'::jsonb, 'total = 7
print(total)
total = 12
', '{"input":"text"}'::jsonb, '{"en":"The print runs before the second assignment, so it shows 7. The value does become 12 — just after the only line that would have shown it.\n"}'::jsonb, '{"en":"Follow the lines strictly in order."}'::jsonb, null, false, true, true, array['variables', 'reassignment']::text[], 2, 'reviewed'::public.review_status, 'c137ffa399d5efe44cbd49dbe417d689'),
  ('697c0320-a823-46f5-a1d5-bbcd013107db', 'e4d23af9-8917-4945-b4aa-a5ec4878dba5', 'multiple_choice'::public.question_type, 'medium'::public.difficulty_level, '{"en":"What is `x` after these two lines?"}'::jsonb, 'x = 6
x = x * 2
', '{"options":[{"id":"twelve","text":{"en":"12"}},{"id":"six","text":{"en":"6"}},{"id":"error","text":{"en":"An error, because x is used to define itself"}},{"id":"two","text":{"en":"2"}}]}'::jsonb, '{"en":"Python calculates the right side first, using the current value: 6 times 2 is 12. Only then does it store that result back in `x`. There is no circularity, because the reading happens before the writing.\n"}'::jsonb, null, null, false, true, true, array['variables', 'reassignment']::text[], 3, 'reviewed'::public.review_status, '60b6780b2378a89e5f3bd2cee6b072c2'),
  ('51f8fc43-8f18-407a-8c3c-6969ed20a125', 'e4d23af9-8917-4945-b4aa-a5ec4878dba5', 'code_ordering'::public.question_type, 'medium'::public.difficulty_level, '{"en":"Arrange the lines so the program ends by printing 8."}'::jsonb, null, '{"lines":[{"id":"start","text":"value = 10"},{"id":"add","text":"value += 1"},{"id":"subtract","text":"value -= 3"},{"id":"show","text":"print(value)"}]}'::jsonb, '{"en":"Ten, plus one, minus three, gives eight — and the print has to come last to see it. Each line changes the value in place, so the order of the arithmetic is the order of the lines.\n"}'::jsonb, null, null, false, true, true, array['variables', 'reassignment']::text[], 4, 'reviewed'::public.review_status, 'ae813c983a8f31ac62a08ede7158bb05'),
  ('184ed59e-ff4f-47c2-a320-351d98580148', 'e4d23af9-8917-4945-b4aa-a5ec4878dba5', 'debugging'::public.question_type, 'hard'::public.difficulty_level, '{"en":"This should print the total after the discount, but it prints the price before it. Which line needs to move?\n"}'::jsonb, 'price = 100
print(price)
price -= 20
', '{"mode":"select_line","lines":[{"id":"set","text":"price = 100"},{"id":"show","text":"print(price)"},{"id":"discount","text":"price -= 20"}]}'::jsonb, '{"en":"Nothing here is wrong in isolation — the mistake is the order. The print happens before the discount is applied, so it reports a value that is technically correct and completely useless. Bugs of this kind never raise an error.\n"}'::jsonb, '{"en":"Every line is valid Python. Ask when each one happens."}'::jsonb, null, false, true, true, array['variables', 'reassignment', 'debugging']::text[], 5, 'reviewed'::public.review_status, '440035d68c588f81ddc98ce5d96d3876'),
  ('89444f12-ab43-44e5-a276-b4bab12c8bc8', '1efcab6f-3118-4d16-966a-83214cc494b8', 'predict_output'::public.question_type, 'medium'::public.difficulty_level, '{"en":"What does this print?"}'::jsonb, 'a = 3
b = 4
print(a + b)
', '{"input":"text"}'::jsonb, '{"en":"Both values are numbers, so `+` adds them. Had they been written \"3\" and \"4\" with quotes, the same `+` would have joined them into \"34\" instead.\n"}'::jsonb, null, null, false, true, true, array['variables', 'arithmetic']::text[], 1, 'reviewed'::public.review_status, '4627214a706eb473ac3bbb72ebd68bea'),
  ('315015b6-963b-4cfb-acc9-ea68b8e5ae51', '1efcab6f-3118-4d16-966a-83214cc494b8', 'fill_blank'::public.question_type, 'medium'::public.difficulty_level, '{"en":"Complete the line so the number can be joined to the text."}'::jsonb, 'count = 5
print("You have " + ___(count) + " messages")
', '{"input":"tokens","tokens":["str","int","float","text"]}'::jsonb, '{"en":"`str()` converts a value to text, which is what `+` needs on both sides here. `int()` would go the other way, and `text()` is not a Python function at all.\n"}'::jsonb, '{"en":"Which kind of value does `+` need on both sides to join them?"}'::jsonb, null, false, true, true, array['variables', 'data-types']::text[], 2, 'reviewed'::public.review_status, '56bc8f47e59ce51b712e12657a59dd8d'),
  ('94627b6b-6cda-4f26-bdc7-17ce7531e214', '1efcab6f-3118-4d16-966a-83214cc494b8', 'multiple_choice'::public.question_type, 'medium'::public.difficulty_level, '{"en":"What happens when you run `print(\"Total: \" + 5)`?"}'::jsonb, null, '{"options":[{"id":"type-error","text":{"en":"A TypeError, because text and a number cannot be joined"}},{"id":"works","text":{"en":"It prints `Total: 5`"}},{"id":"adds","text":{"en":"It prints `Total: ` followed by nothing"}},{"id":"converts","text":{"en":"Python converts the number to text automatically"}}]}'::jsonb, '{"en":"Python refuses to guess. Joining text and adding numbers are different operations that share the `+` symbol, so mixing the two is ambiguous — and Python would rather stop than pick the wrong one silently.\n"}'::jsonb, null, null, false, true, true, array['data-types', 'errors']::text[], 3, 'reviewed'::public.review_status, 'eeac1c08d1b8bd79c88f5025c25892e8'),
  ('b1b87037-2ac7-4068-8dcc-aab0c1172c19', '1efcab6f-3118-4d16-966a-83214cc494b8', 'concept_matching'::public.question_type, 'hard'::public.difficulty_level, '{"en":"Match each expression to what it produces."}'::jsonb, null, '{"concepts":[{"id":"numbers","text":{"en":"2 + 3"}},{"id":"strings","text":{"en":"\"2\" + \"3\""}},{"id":"mixed","text":{"en":"\"2\" + 3"}}],"definitions":[{"id":"five","text":{"en":"The number 5"}},{"id":"twentythree","text":{"en":"The text 23"}},{"id":"error","text":{"en":"A TypeError"}}]}'::jsonb, '{"en":"The same `+` means three different things depending on what sits either side: add for numbers, join for text, and refuse for a mixture. The quotes are the only visible difference, which is why they repay careful reading.\n"}'::jsonb, null, null, false, true, true, array['data-types', 'arithmetic']::text[], 4, 'reviewed'::public.review_status, 'b47c2771e6aca706bc2267f8d9022878'),
  ('f178061f-8985-4d79-81f2-e2daf4bfb9ae', '1efcab6f-3118-4d16-966a-83214cc494b8', 'multiple_select'::public.question_type, 'hard'::public.difficulty_level, '{"en":"Which of these lines print exactly `Score: 9`?"}'::jsonb, null, '{"options":[{"id":"comma","text":{"en":"print(\"Score:\", 9)"}},{"id":"str-join","text":{"en":"print(\"Score: \" + str(9))"}},{"id":"plain-join","text":{"en":"print(\"Score: \" + 9)"}},{"id":"no-space","text":{"en":"print(\"Score:\" + str(9))"}},{"id":"two-args","text":{"en":"print(\"Score:\", \"9\")"}}]}'::jsonb, '{"en":"Commas insert exactly one space, so the first and last both give `Score: 9`. The `str()` version supplies its own space inside the quotes. Joining text to a bare number raises a TypeError, and the fourth has no space at all, giving `Score:9`.\n"}'::jsonb, '{"en":"Work out the spaces character by character."}'::jsonb, null, false, true, true, array['printing', 'data-types']::text[], 5, 'reviewed'::public.review_status, '524061fe84ec1bc0786a1a9bd2748972'),
  ('ea50311a-4796-4b21-8610-4868aa91e956', 'b2755a55-41d3-4e4f-83c0-afef79f9be61', 'multiple_choice'::public.question_type, 'easy'::public.difficulty_level, '{"en":"What type is the value `3.0`?"}'::jsonb, null, '{"options":[{"id":"float","text":{"en":"float"}},{"id":"int","text":{"en":"int"}},{"id":"str","text":{"en":"str"}},{"id":"decimal","text":{"en":"decimal"}}]}'::jsonb, '{"en":"The decimal point makes it a float, even though the value is a whole number. Python has no built-in type called `decimal` in everyday use — floats cover decimals.\n"}'::jsonb, null, null, false, true, true, array['data-types', 'numbers']::text[], 1, 'draft'::public.review_status, 'f9da1abd230bc7c2fb172226d7f35b7f'),
  ('de36e0df-ace2-4d08-88c7-dd0996bd9f88', 'b2755a55-41d3-4e4f-83c0-afef79f9be61', 'predict_output'::public.question_type, 'easy'::public.difficulty_level, '{"en":"What does this print?"}'::jsonb, 'print(9 / 3)
', '{"input":"text"}'::jsonb, '{"en":"Division with `/` always produces a float, so the result is `3.0` rather than `3` — even though 9 divides by 3 exactly.\n"}'::jsonb, '{"en":"What kind of number does `/` always give back?"}'::jsonb, null, false, true, true, array['numbers', 'arithmetic']::text[], 2, 'draft'::public.review_status, 'df8727847dd082905d136d00f18de092'),
  ('1888a90a-fb27-43f9-be70-593e413ddb7b', 'b2755a55-41d3-4e4f-83c0-afef79f9be61', 'true_false'::public.question_type, 'easy'::public.difficulty_level, '{"en":"`5` and `5.0` are the same type."}'::jsonb, null, '{}'::jsonb, '{"en":"They are equal in value, but `5` is an int and `5.0` is a float. `type()` would show the difference.\n"}'::jsonb, null, null, false, true, true, array['data-types', 'numbers']::text[], 3, 'draft'::public.review_status, '1f4bda4558a7b6337f12debae15ae080'),
  ('c9c099ea-454f-4d6f-bf47-b5db8b522daf', 'b2755a55-41d3-4e4f-83c0-afef79f9be61', 'predict_output'::public.question_type, 'medium'::public.difficulty_level, '{"en":"What does this print?"}'::jsonb, 'print(type(2 * 3.0))
', '{"input":"choice","options":[{"id":"float","text":{"en":"<class ''float''>"}},{"id":"int","text":{"en":"<class ''int''>"}},{"id":"value","text":{"en":"6.0"}},{"id":"number","text":{"en":"<class ''number''>"}}]}'::jsonb, '{"en":"Multiplying an int by a float gives a float, and `type()` reports the type, not the value. So the answer is the float class, not `6.0`.\n"}'::jsonb, null, null, false, true, true, array['data-types', 'numbers']::text[], 4, 'draft'::public.review_status, '7cc700705c90c049c4698cc1dd48e97c'),
  ('d06ac792-4b99-4520-8e22-340efc8ebeaa', 'b2755a55-41d3-4e4f-83c0-afef79f9be61', 'multiple_select'::public.question_type, 'medium'::public.difficulty_level, '{"en":"Which of these expressions produce a float?"}'::jsonb, null, '{"options":[{"id":"divide","text":{"en":"8 / 4"}},{"id":"multiply","text":{"en":"8 * 4"}},{"id":"add-half","text":{"en":"8 + 0.5"}},{"id":"subtract","text":{"en":"8 - 3"}},{"id":"times-one","text":{"en":"2 * 1.0"}}]}'::jsonb, '{"en":"`/` always gives a float, and any arithmetic involving a float gives a float. Adding, subtracting and multiplying two ints keeps the result an int.\n"}'::jsonb, '{"en":"Look for a `/`, or for a number with a decimal point."}'::jsonb, null, false, true, true, array['numbers', 'arithmetic']::text[], 5, 'draft'::public.review_status, 'd372dcbdb7688faf75cbd57221d5b81f'),
  ('727abeac-6d68-437a-8634-ad4d3b12264c', 'b2755a55-41d3-4e4f-83c0-afef79f9be61', 'predict_output'::public.question_type, 'hard'::public.difficulty_level, '{"en":"What does this print?"}'::jsonb, 'print(round(2.675, 2))
', '{"input":"text"}'::jsonb, '{"en":"On paper 2.675 rounds up to 2.68, but the float actually stored is a hair below 2.675, so it rounds down to 2.67. It is the same binary approximation that makes `0.1 + 0.2` print with a long tail.\n"}'::jsonb, '{"en":"Remember that floats are not always stored exactly."}'::jsonb, null, false, true, true, array['numbers', 'floats']::text[], 6, 'draft'::public.review_status, 'cd73b4414039c00827572bc5f390dd4d'),
  ('e3ce4890-1d0b-496f-94de-1648107212d4', '2b995cc8-265a-440c-b602-a63eca6a08ad', 'true_false'::public.question_type, 'easy'::public.difficulty_level, '{"en":"`\"42\"`, written with quotes, is a number."}'::jsonb, null, '{}'::jsonb, '{"en":"The quotes make it a string — text made of the characters 4 and 2. To do arithmetic with it you would first have to convert it.\n"}'::jsonb, null, null, false, true, true, array['data-types', 'strings']::text[], 1, 'draft'::public.review_status, '308b25738d1cba826df4d00db64b972c'),
  ('855ff9dc-c9b3-4af2-a161-bc2b7445ab64', '2b995cc8-265a-440c-b602-a63eca6a08ad', 'multiple_choice'::public.question_type, 'easy'::public.difficulty_level, '{"en":"Which of these is a boolean value in Python?"}'::jsonb, null, '{"options":[{"id":"capital","text":{"en":"True"}},{"id":"lower","text":{"en":"true"}},{"id":"upper","text":{"en":"TRUE"}},{"id":"quoted","text":{"en":"\"True\""}}]}'::jsonb, '{"en":"Only `True`, with a capital T and no quotes, is the boolean. `\"True\"` in quotes is a string, and the other spellings are not values Python recognises at all.\n"}'::jsonb, null, null, false, true, true, array['booleans']::text[], 2, 'draft'::public.review_status, '578f47b62066547bec85065cb766294e'),
  ('15cac6fb-f82c-4769-a6ca-47ce3feb372a', '2b995cc8-265a-440c-b602-a63eca6a08ad', 'predict_output'::public.question_type, 'easy'::public.difficulty_level, '{"en":"What does this print?"}'::jsonb, 'print(len("hello world"))
', '{"input":"text"}'::jsonb, '{"en":"Five letters, one space, five letters. The space is a character like any other, so the total is 11.\n"}'::jsonb, '{"en":"Count the space as well."}'::jsonb, null, false, true, true, array['strings']::text[], 3, 'draft'::public.review_status, '3a4784ea4f2e6a32b3a93e96b10a9d66'),
  ('c432c489-9171-4e39-9a1e-856c51a451fb', '2b995cc8-265a-440c-b602-a63eca6a08ad', 'predict_output'::public.question_type, 'medium'::public.difficulty_level, '{"en":"What does this print?"}'::jsonb, 'print(10 == 10.0)
', '{"input":"text"}'::jsonb, '{"en":"`==` compares values, and ten is ten whether it is written as an int or a float. The two values are different types, but they are equal.\n"}'::jsonb, null, null, false, true, true, array['booleans', 'numbers']::text[], 4, 'draft'::public.review_status, 'bfe68bd7fa58291509e7d7ae857fc497'),
  ('4b76e759-379a-451b-9586-2e7e0c7d1239', '2b995cc8-265a-440c-b602-a63eca6a08ad', 'concept_matching'::public.question_type, 'medium'::public.difficulty_level, '{"en":"Match each value to its type."}'::jsonb, null, '{"concepts":[{"id":"seven-text","text":{"en":"\"7\""}},{"id":"seven","text":{"en":"7"}},{"id":"seven-half","text":{"en":"7.5"}},{"id":"false-value","text":{"en":"False"}}],"definitions":[{"id":"str","text":{"en":"str"}},{"id":"int","text":{"en":"int"}},{"id":"float","text":{"en":"float"}},{"id":"bool","text":{"en":"bool"}}]}'::jsonb, '{"en":"Quotes make a string, a whole number is an int, a decimal point makes a float, and `False` is one of the two boolean values.\n"}'::jsonb, null, null, false, true, true, array['data-types']::text[], 5, 'draft'::public.review_status, '8e149b670fcb1b85085891908ab9a255'),
  ('7189db76-c3df-40d8-b022-86b67b79a76e', '2b995cc8-265a-440c-b602-a63eca6a08ad', 'debugging'::public.question_type, 'hard'::public.difficulty_level, '{"en":"This program stops with a NameError. Which line causes it?"}'::jsonb, 'is_ready = true
print(is_ready)
', '{"mode":"select_line","lines":[{"id":"assign","text":"is_ready = true"},{"id":"show","text":"print(is_ready)"}]}'::jsonb, '{"en":"Lowercase `true` is not a boolean, so Python looks for a variable called `true`, finds none, and raises a NameError. The error is reported on the first line, before `print` ever runs.\n"}'::jsonb, '{"en":"Check the capital letters."}'::jsonb, null, false, true, true, array['booleans', 'errors']::text[], 6, 'draft'::public.review_status, 'ced81e27912f8e52d9212e195633a373'),
  ('5dedd6e1-6fed-4171-b9ea-4f41fa58f35e', '4853a1ed-eb9c-4c8f-9387-6c2b7aaa2fdf', 'predict_output'::public.question_type, 'easy'::public.difficulty_level, '{"en":"What does this print?"}'::jsonb, 'print(int("7") * 2)
', '{"input":"text"}'::jsonb, '{"en":"`int(\"7\")` turns the text into the number 7, so `* 2` multiplies it. Without the conversion, `\"7\" * 2` would repeat the text and give `77`.\n"}'::jsonb, null, null, false, true, true, array['type-conversion']::text[], 1, 'draft'::public.review_status, 'bfac29e31c38426cf82a017c9b18b36e'),
  ('3aa8b19e-d725-4beb-ae3b-47d23e9b96d7', '4853a1ed-eb9c-4c8f-9387-6c2b7aaa2fdf', 'true_false'::public.question_type, 'easy'::public.difficulty_level, '{"en":"`str(10) + str(5)` produces the text `105`."}'::jsonb, null, '{}'::jsonb, '{"en":"Both numbers become text first, so `+` joins them rather than adding them. Joining \"10\" and \"5\" gives \"105\".\n"}'::jsonb, null, null, false, true, true, array['type-conversion', 'strings']::text[], 2, 'draft'::public.review_status, 'ef1c2089ef733f06c3393bc7f596acea'),
  ('596d6609-d882-4297-b007-ceb1f1b1b629', '4853a1ed-eb9c-4c8f-9387-6c2b7aaa2fdf', 'multiple_choice'::public.question_type, 'medium'::public.difficulty_level, '{"en":"What does `int(4.8)` give?"}'::jsonb, null, '{"options":[{"id":"four","text":{"en":"4"}},{"id":"five","text":{"en":"5"}},{"id":"same","text":{"en":"4.8"}},{"id":"error","text":{"en":"A ValueError"}}]}'::jsonb, '{"en":"`int()` cuts off the decimal part without rounding, so 4.8 becomes 4. Use `round()` when you want the nearest whole number.\n"}'::jsonb, null, null, false, true, true, array['type-conversion', 'numbers']::text[], 3, 'draft'::public.review_status, 'be2d0314c5ff34a6cb4c0950a0d51f8c'),
  ('08e80b18-640c-483d-a908-9c3126eb8635', '4853a1ed-eb9c-4c8f-9387-6c2b7aaa2fdf', 'multiple_choice'::public.question_type, 'medium'::public.difficulty_level, '{"en":"What happens when you run `int(\"3.5\")`?"}'::jsonb, null, '{"options":[{"id":"value-error","text":{"en":"A ValueError, because the text is not a whole number"}},{"id":"three","text":{"en":"It gives 3"}},{"id":"four","text":{"en":"It gives 4"}},{"id":"float","text":{"en":"It gives 3.5"}}]}'::jsonb, '{"en":"`int()` can drop the decimals of a float, but it will not read a decimal point inside text. Convert with `float()` first, then with `int()`.\n"}'::jsonb, null, null, false, true, true, array['type-conversion', 'errors']::text[], 4, 'draft'::public.review_status, 'a2d3b050e4f9ca876d83aa553781ccce'),
  ('535c4b97-d472-46a4-b0fe-5c5d8b301676', '4853a1ed-eb9c-4c8f-9387-6c2b7aaa2fdf', 'fill_blank'::public.question_type, 'medium'::public.difficulty_level, '{"en":"Complete the line so the price can be doubled."}'::jsonb, 'price = "4.50"
total = ___(price) * 2
print(total)
', '{"input":"tokens","tokens":["float","int","str","round"]}'::jsonb, '{"en":"The text contains a decimal point, so it has to become a float. `int()` would fail on the decimal point, and `str()` would leave it as text.\n"}'::jsonb, '{"en":"The price has a decimal point in it."}'::jsonb, null, false, true, true, array['type-conversion']::text[], 5, 'draft'::public.review_status, 'af736b94479bd12c9158116ec80e5968'),
  ('7a270675-4baf-4d32-be72-af11fe9ab41d', '4853a1ed-eb9c-4c8f-9387-6c2b7aaa2fdf', 'predict_output'::public.question_type, 'hard'::public.difficulty_level, '{"en":"What does this print?"}'::jsonb, 'print(str(2) * 3)
', '{"input":"choice","options":[{"id":"repeated","text":{"en":"222"}},{"id":"product","text":{"en":"6"}},{"id":"spaced","text":{"en":"2 2 2"}},{"id":"error","text":{"en":"A TypeError"}}]}'::jsonb, '{"en":"`str(2)` is the text \"2\", and multiplying text by a number repeats it. So the result is \"2\" three times in a row, with no spaces added.\n"}'::jsonb, '{"en":"What does `*` do when one side is text?"}'::jsonb, null, false, true, true, array['type-conversion', 'strings']::text[], 6, 'draft'::public.review_status, 'b7d8a4cde6173491eb7f9f946b21e90e'),
  ('6047dd29-2efc-43ac-b87b-ec496d00bbf4', '4853a1ed-eb9c-4c8f-9387-6c2b7aaa2fdf', 'code_ordering'::public.question_type, 'hard'::public.difficulty_level, '{"en":"Arrange the lines so the program reads a number from text, adds 8, and prints 20."}'::jsonb, null, '{"lines":[{"id":"text","text":"text = \"12\""},{"id":"convert","text":"number = int(text)"},{"id":"add","text":"total = number + 8"},{"id":"show","text":"print(total)"}]}'::jsonb, '{"en":"Each line uses a name the line before created: the text, then the number made from it, then the total made from the number. A name has to exist before a later line can use it.\n"}'::jsonb, null, null, false, true, true, array['type-conversion', 'variables']::text[], 7, 'draft'::public.review_status, 'd0739cb76921196e2c431ab2c3a3265c'),
  ('8850d187-073e-4873-8d4c-a2f22c18757c', '6cdd8360-333c-4eee-ae88-b7aa7120493c', 'true_false'::public.question_type, 'easy'::public.difficulty_level, '{"en":"`None` is the same as `0`."}'::jsonb, null, '{}'::jsonb, '{"en":"`0` is a number with a value of zero. `None` means there is no value at all — it has its own type, `NoneType`.\n"}'::jsonb, null, null, false, true, true, array['none', 'data-types']::text[], 1, 'draft'::public.review_status, '4a273bc6640f189bb88dfdf22445fe73'),
  ('bba88ba8-52b7-4ffb-ac24-2b84c1eb027d', '6cdd8360-333c-4eee-ae88-b7aa7120493c', 'predict_output'::public.question_type, 'easy'::public.difficulty_level, '{"en":"What does this print?"}'::jsonb, 'print(type(None))
', '{"input":"choice","options":[{"id":"nonetype","text":{"en":"<class ''NoneType''>"}},{"id":"none-class","text":{"en":"<class ''None''>"}},{"id":"bare","text":{"en":"None"}},{"id":"zero","text":{"en":"0"}}]}'::jsonb, '{"en":"`None` is the only value of the type `NoneType`, and `type()` reports the type. It is one of the few type names that is not simply the value''s name.\n"}'::jsonb, null, null, false, true, true, array['none', 'data-types']::text[], 2, 'draft'::public.review_status, '8ff437deaa04be06b7f5369b0b984071'),
  ('87dabe33-20ab-44ce-989c-0f1c12098b69', '6cdd8360-333c-4eee-ae88-b7aa7120493c', 'predict_output'::public.question_type, 'medium'::public.difficulty_level, '{"en":"What does this print?"}'::jsonb, 'x = print("A")
print(x)
', '{"input":"choice","options":[{"id":"a-none","text":{"en":"A\nNone"}},{"id":"a-a","text":{"en":"A\nA"}},{"id":"none","text":{"en":"None"}},{"id":"a","text":{"en":"A"}}]}'::jsonb, '{"en":"The first line prints \"A\" while it runs, and stores what `print` returns, which is `None`. The second line then prints that `None`.\n"}'::jsonb, '{"en":"What does `print` give back, as opposed to what it shows?"}'::jsonb, null, false, true, true, array['none', 'printing']::text[], 3, 'draft'::public.review_status, '1a19fed360b221571f1b391f9bdaccec'),
  ('ff17234b-2f61-4398-963a-a36a0029d38c', '6cdd8360-333c-4eee-ae88-b7aa7120493c', 'multiple_select'::public.question_type, 'medium'::public.difficulty_level, '{"en":"Which of these are `True`?"}'::jsonb, null, '{"options":[{"id":"int-int","text":{"en":"isinstance(5, int)"}},{"id":"float-int","text":{"en":"isinstance(5.0, int)"}},{"id":"str-str","text":{"en":"isinstance(\"5\", str)"}},{"id":"int-float","text":{"en":"isinstance(5, float)"}}]}'::jsonb, '{"en":"`5` is an int and `\"5\"` is a string, so those two are true. `5.0` is a float, not an int, and `5` is an int, not a float — Python does not treat them as each other.\n"}'::jsonb, null, null, false, true, true, array['data-types']::text[], 4, 'draft'::public.review_status, 'b9a46af1b8db66c45fc6b18a984abe88'),
  ('97b67f1b-3915-4b3b-88cb-d34ded78907a', '6cdd8360-333c-4eee-ae88-b7aa7120493c', 'predict_output'::public.question_type, 'hard'::public.difficulty_level, '{"en":"What does this print?"}'::jsonb, 'print(isinstance(True, int))
', '{"input":"text"}'::jsonb, '{"en":"A surprise: in Python a boolean is a special kind of int, with `True` behaving like 1 and `False` like 0. So `True` counts as an instance of `int`.\n"}'::jsonb, '{"en":"Try `print(True + True)` in your head."}'::jsonb, null, false, true, true, array['booleans', 'data-types']::text[], 5, 'draft'::public.review_status, 'e012f350238ebaa34de3447a86597d6e'),
  ('ec2f7e2a-3150-4053-87f4-7d352ccff0c9', '07903697-df6e-4c58-9684-0b81fbf1fe92', 'predict_output'::public.question_type, 'easy'::public.difficulty_level, '{"en":"What does this print?"}'::jsonb, 'print(20 // 6)
', '{"input":"text"}'::jsonb, '{"en":"6 goes into 20 three whole times (18), with 2 left over. `//` keeps the 3 and discards the remainder.\n"}'::jsonb, null, null, false, true, true, array['arithmetic']::text[], 1, 'draft'::public.review_status, '47ae79f0aac264ea2f8b86bee1fb68e3'),
  ('cd1bfcc4-5907-46d8-8d52-559d9ecbb065', '07903697-df6e-4c58-9684-0b81fbf1fe92', 'predict_output'::public.question_type, 'easy'::public.difficulty_level, '{"en":"What does this print?"}'::jsonb, 'print(2 ** 3)
', '{"input":"text"}'::jsonb, '{"en":"`**` is a power: two to the power of three is 2 × 2 × 2, which is 8. It is not 2 × 3.\n"}'::jsonb, null, null, false, true, true, array['arithmetic']::text[], 2, 'draft'::public.review_status, 'ccc0ce7c3697558daf8ec024ceee491d'),
  ('930cf6d1-4bfd-4908-adea-7b8b00a3b042', '07903697-df6e-4c58-9684-0b81fbf1fe92', 'multiple_choice'::public.question_type, 'medium'::public.difficulty_level, '{"en":"What is the value of `23 % 5`?"}'::jsonb, null, '{"options":[{"id":"three","text":{"en":"3"}},{"id":"four","text":{"en":"4"}},{"id":"decimal","text":{"en":"4.6"}},{"id":"five","text":{"en":"5"}}]}'::jsonb, '{"en":"Five goes into 23 four times, which makes 20. What is left over is 3, and `%` gives only that remainder. 4 is what `//` would give; 4.6 is what `/` would give.\n"}'::jsonb, null, null, false, true, true, array['arithmetic']::text[], 3, 'draft'::public.review_status, '60bf7ab78f8f45b67db5341b5ad0f841'),
  ('c5a0574a-2bcf-434e-842e-dbd0a4020e30', '07903697-df6e-4c58-9684-0b81fbf1fe92', 'fill_blank'::public.question_type, 'medium'::public.difficulty_level, '{"en":"Complete the line so it prints `0`, showing that 12 is even."}'::jsonb, 'print(12 ___ 2)
', '{"input":"tokens","tokens":["%","//","/","**"]}'::jsonb, '{"en":"The remainder of 12 divided by 2 is 0, which is what makes 12 even. `//` would give 6, `/` would give 6.0, and `**` would give 144.\n"}'::jsonb, '{"en":"You want what is left over, not how many times it fits."}'::jsonb, null, false, true, true, array['arithmetic']::text[], 4, 'draft'::public.review_status, 'f39eee56d388d5d729a931aa1a0323c5'),
  ('7a23abe7-7374-4901-9cc6-8795fff9d58e', '07903697-df6e-4c58-9684-0b81fbf1fe92', 'concept_matching'::public.question_type, 'medium'::public.difficulty_level, '{"en":"Match each expression to its result."}'::jsonb, null, '{"concepts":[{"id":"divide","text":{"en":"9 / 2"}},{"id":"floor","text":{"en":"9 // 2"}},{"id":"remainder","text":{"en":"9 % 2"}},{"id":"power","text":{"en":"9 ** 2"}}],"definitions":[{"id":"four-half","text":{"en":"4.5"}},{"id":"four","text":{"en":"4"}},{"id":"one","text":{"en":"1"}},{"id":"eighty-one","text":{"en":"81"}}]}'::jsonb, '{"en":"Same two numbers, four different questions: the exact quotient, how many whole twos fit, what is left over, and nine squared.\n"}'::jsonb, null, null, false, true, true, array['arithmetic']::text[], 5, 'draft'::public.review_status, 'a46da7a0d62462044c03bdde51e02dee'),
  ('0c36abc9-f0d4-40ff-a758-051d7141afee', '07903697-df6e-4c58-9684-0b81fbf1fe92', 'predict_output'::public.question_type, 'hard'::public.difficulty_level, '{"en":"What does this print?"}'::jsonb, 'print(-9 // 4)
', '{"input":"text"}'::jsonb, '{"en":"-9 divided by 4 is -2.25, and `//` always rounds down — towards the smaller number. Down from -2.25 is -3, not -2.\n"}'::jsonb, '{"en":"Which whole number is just below -2.25?"}'::jsonb, null, false, true, true, array['arithmetic']::text[], 6, 'draft'::public.review_status, '555bb02b81aac4205da347f98c848a33'),
  ('e79896d5-48d3-446f-b0c0-b8c5b9053a07', 'ba67a0e1-2d0c-4b41-b0b5-33e49b82a647', 'predict_output'::public.question_type, 'easy'::public.difficulty_level, '{"en":"What does this print?"}'::jsonb, 'print(1 + 2 * 3)
', '{"input":"text"}'::jsonb, '{"en":"Multiplication happens before addition, so this is 1 + 6, not 3 × 3.\n"}'::jsonb, null, null, false, true, true, array['arithmetic', 'precedence']::text[], 1, 'draft'::public.review_status, '93cfe705559f6868ca18bc1a0a17c3f9'),
  ('12ded32d-64f9-42b0-b3ff-9b98ac4d7e9c', 'ba67a0e1-2d0c-4b41-b0b5-33e49b82a647', 'true_false'::public.question_type, 'easy'::public.difficulty_level, '{"en":"`(1 + 2) * 3` gives 9."}'::jsonb, null, '{}'::jsonb, '{"en":"The parentheses are worked out first, giving 3, and 3 × 3 is 9. Without them the answer would be 7.\n"}'::jsonb, null, null, false, true, true, array['precedence']::text[], 2, 'draft'::public.review_status, '5fd5b4afd3447f168ef118ffc98626ed'),
  ('70a4c1f0-f06d-4303-9cf3-150ab4ce3ce0', 'ba67a0e1-2d0c-4b41-b0b5-33e49b82a647', 'predict_output'::public.question_type, 'medium'::public.difficulty_level, '{"en":"What does this print?"}'::jsonb, 'print(20 - 10 / 5)
', '{"input":"text"}'::jsonb, '{"en":"Division comes first: 10 / 5 is 2.0, a float because `/` always gives one. Then 20 − 2.0 is 18.0.\n"}'::jsonb, '{"en":"Which operator goes first — and what type does it produce?"}'::jsonb, null, false, true, true, array['arithmetic', 'precedence']::text[], 3, 'draft'::public.review_status, '477cd41c3551e1fb672a2c708efc56fd'),
  ('edfad4eb-a21e-4cd1-8de0-a24ceada9aee', 'ba67a0e1-2d0c-4b41-b0b5-33e49b82a647', 'multiple_choice'::public.question_type, 'medium'::public.difficulty_level, '{"en":"Which of these expressions gives 20?"}'::jsonb, null, '{"options":[{"id":"grouped","text":{"en":"(2 + 3) * 4"}},{"id":"plain","text":{"en":"2 + 3 * 4"}},{"id":"reversed","text":{"en":"2 * 3 + 4"}},{"id":"redundant","text":{"en":"2 + (3 * 4)"}}]}'::jsonb, '{"en":"Only the first forces the addition to happen before the multiplication. The second and fourth both work out 3 × 4 first and give 14; the third gives 10.\n"}'::jsonb, null, null, false, true, true, array['precedence']::text[], 4, 'draft'::public.review_status, '5a7eff50ba5554e47b0f2231eb41c232'),
  ('fb1a96b8-36ff-4532-b93b-7238acffc652', 'ba67a0e1-2d0c-4b41-b0b5-33e49b82a647', 'code_ordering'::public.question_type, 'medium'::public.difficulty_level, '{"en":"Arrange the lines to average 4 and 8, round the result, and print 6."}'::jsonb, null, '{"lines":[{"id":"total","text":"total = 4 + 8"},{"id":"average","text":"average = total / 2"},{"id":"rounded","text":"rounded = round(average)"},{"id":"show","text":"print(rounded)"}]}'::jsonb, '{"en":"Each step needs the one before it: the average needs the total, and the rounding needs the average. Named steps make the order impossible to get wrong once you see what each line depends on.\n"}'::jsonb, null, null, false, true, true, array['arithmetic', 'variables']::text[], 5, 'draft'::public.review_status, 'f7c8d3d60adac999c9bb5c4802555916'),
  ('6605e3c0-e432-4890-8166-bcf799e9f0c3', 'ba67a0e1-2d0c-4b41-b0b5-33e49b82a647', 'predict_output'::public.question_type, 'hard'::public.difficulty_level, '{"en":"What does this print?"}'::jsonb, 'print(-2 ** 2)
', '{"input":"text"}'::jsonb, '{"en":"`**` binds more tightly than the minus sign in front of the 2. Python reads this as −(2 ** 2), which is −4. Write `(-2) ** 2` to square negative two and get 4.\n"}'::jsonb, '{"en":"Does the minus sign belong to the 2, or to the result?"}'::jsonb, null, false, true, true, array['arithmetic', 'precedence']::text[], 6, 'draft'::public.review_status, '4ae5afbf968be5144410b88b803d80cc'),
  ('0ac326d0-b910-42af-bc63-d22b220741e4', '175a507f-9409-48a6-8f22-1a6ec4f34c17', 'multiple_choice'::public.question_type, 'easy'::public.difficulty_level, '{"en":"Which operator checks whether two values are equal?"}'::jsonb, null, '{"options":[{"id":"double","text":{"en":"=="}},{"id":"single","text":{"en":"="}},{"id":"not-equal","text":{"en":"!="}},{"id":"triple","text":{"en":"==="}}]}'::jsonb, '{"en":"`==` compares. A single `=` stores a value in a variable, `!=` asks the opposite question, and `===` does not exist in Python.\n"}'::jsonb, null, null, false, true, true, array['comparisons']::text[], 1, 'draft'::public.review_status, '226c7f41904c789d0a994a4363a4c0e4'),
  ('21fc7883-109b-4b04-8817-efb8a3ffa3f3', '175a507f-9409-48a6-8f22-1a6ec4f34c17', 'predict_output'::public.question_type, 'easy'::public.difficulty_level, '{"en":"What does this print?"}'::jsonb, 'print(5 >= 5)
', '{"input":"text"}'::jsonb, '{"en":"`>=` means greater than **or equal to**. 5 is not greater than 5, but it is equal to it, so the answer is True.\n"}'::jsonb, null, null, false, true, true, array['comparisons']::text[], 2, 'draft'::public.review_status, '89751cd493059e8953701bc5fb3f12bc'),
  ('3ad72061-ec3a-4624-8a15-993d39e39d37', '175a507f-9409-48a6-8f22-1a6ec4f34c17', 'predict_output'::public.question_type, 'medium'::public.difficulty_level, '{"en":"What does this print?"}'::jsonb, 'x = 3
print(x != 3)
', '{"input":"text"}'::jsonb, '{"en":"`!=` asks \"are these different?\". `x` is 3, so they are not different, and the answer is False.\n"}'::jsonb, null, null, false, true, true, array['comparisons']::text[], 3, 'draft'::public.review_status, '57a948205e58848997d6fe837dea872e'),
  ('2ccae378-e741-4e78-8840-b0060a3818e2', '175a507f-9409-48a6-8f22-1a6ec4f34c17', 'multiple_select'::public.question_type, 'medium'::public.difficulty_level, '{"en":"With `x = 10`, which of these are `True`?"}'::jsonb, null, '{"options":[{"id":"greater","text":{"en":"x > 5"}},{"id":"less","text":{"en":"x < 10"}},{"id":"less-equal","text":{"en":"x <= 10"}},{"id":"float-equal","text":{"en":"x == 10.0"}},{"id":"not-equal","text":{"en":"x != 10"}}]}'::jsonb, '{"en":"10 is more than 5, and it is at most 10. It also equals 10.0, because `==` compares value, not type. It is not less than 10, and it is not different from 10.\n"}'::jsonb, '{"en":"Watch the difference between `<` and `<=`."}'::jsonb, null, false, true, true, array['comparisons']::text[], 4, 'draft'::public.review_status, '26617927b796c0245fb8fc4510fff2ca'),
  ('8b27c027-0176-4763-924f-fb53f840ce8e', '175a507f-9409-48a6-8f22-1a6ec4f34c17', 'debugging'::public.question_type, 'medium'::public.difficulty_level, '{"en":"This should print True for any price of 10 or less, but for a price of exactly 10 it prints False. Which line is wrong?\n"}'::jsonb, 'price = 10
print(price < 10)
', '{"mode":"select_line","lines":[{"id":"assign","text":"price = 10"},{"id":"compare","text":"print(price < 10)"}]}'::jsonb, '{"en":"\"10 or less\" includes 10, so the comparison needs `<=`. With `<`, the boundary value itself is left out — a classic off-by-one error.\n"}'::jsonb, '{"en":"Does the comparison include the value 10 itself?"}'::jsonb, null, false, true, true, array['comparisons', 'debugging']::text[], 5, 'draft'::public.review_status, 'd461ab430f9e5edf661ec708bf7e88c1'),
  ('cc092fcd-d8d0-4e5d-80ea-74ae2204bb67', '175a507f-9409-48a6-8f22-1a6ec4f34c17', 'predict_output'::public.question_type, 'hard'::public.difficulty_level, '{"en":"What does this print?"}'::jsonb, 'print(1 < 3 > 2)
', '{"input":"text"}'::jsonb, '{"en":"A chain means every link must hold: this is `1 < 3 and 3 > 2`. Both are true, so the whole chain is True. It does not compare the result of `1 < 3` with 2.\n"}'::jsonb, '{"en":"Split the chain into two separate comparisons."}'::jsonb, null, false, true, true, array['comparisons']::text[], 6, 'draft'::public.review_status, '4e543ccb80c3e6ece7bead5d223f9f22'),
  ('e635fa8e-2152-466b-8d56-507deda73d01', '25cc8af2-388a-4aee-bceb-4c8cd486ca30', 'true_false'::public.question_type, 'easy'::public.difficulty_level, '{"en":"`True or False` is `True`."}'::jsonb, null, '{}'::jsonb, '{"en":"`or` needs only one side to be True, and the left side is.\n"}'::jsonb, null, null, false, true, true, array['logic']::text[], 1, 'draft'::public.review_status, '5a5af054bbf2ef6c7d3ab30a99ba7e22'),
  ('0811d96b-4240-4daa-8ea3-be5efefa1f9a', '25cc8af2-388a-4aee-bceb-4c8cd486ca30', 'predict_output'::public.question_type, 'easy'::public.difficulty_level, '{"en":"What does this print?"}'::jsonb, 'print(not False)
', '{"input":"text"}'::jsonb, '{"en":"`not` flips a boolean to its opposite, so not False is True.\n"}'::jsonb, null, null, false, true, true, array['logic']::text[], 2, 'draft'::public.review_status, 'bf59a359717ca2158ec5a08b7b43fc67'),
  ('831e1ba4-060b-46d8-94cc-965fa183c572', '25cc8af2-388a-4aee-bceb-4c8cd486ca30', 'predict_output'::public.question_type, 'medium'::public.difficulty_level, '{"en":"What does this print?"}'::jsonb, 'x = 7
print(x > 5 and x < 10)
', '{"input":"text"}'::jsonb, '{"en":"7 is greater than 5 and less than 10, so both sides of `and` are True. This is the long way of writing `5 < x < 10`.\n"}'::jsonb, null, null, false, true, true, array['logic', 'comparisons']::text[], 3, 'draft'::public.review_status, 'a0bd9fd38e69becf099031d320c5b513'),
  ('436e11b6-fb85-401f-a117-4f15cf9c6ef2', '25cc8af2-388a-4aee-bceb-4c8cd486ca30', 'concept_matching'::public.question_type, 'medium'::public.difficulty_level, '{"en":"Match each expression to when it is True."}'::jsonb, null, '{"concepts":[{"id":"and","text":{"en":"a and b"}},{"id":"or","text":{"en":"a or b"}},{"id":"not","text":{"en":"not a"}}],"definitions":[{"id":"both","text":{"en":"Only when both are True"}},{"id":"either","text":{"en":"When at least one is True"}},{"id":"opposite","text":{"en":"Only when a is False"}}]}'::jsonb, '{"en":"`and` is strict and needs both, `or` is generous and needs one, and `not` simply turns the answer around.\n"}'::jsonb, null, null, false, true, true, array['logic']::text[], 4, 'draft'::public.review_status, 'ad9d1a6e1f76f52a9145745667c0ef9c'),
  ('963bd77f-5961-4520-9e24-23987b7c4423', '25cc8af2-388a-4aee-bceb-4c8cd486ca30', 'fill_blank'::public.question_type, 'medium'::public.difficulty_level, '{"en":"Complete the line so it prints `True`."}'::jsonb, 'is_weekend = False
is_holiday = True
print(is_weekend ___ is_holiday)
', '{"input":"tokens","tokens":["or","and","not","=="]}'::jsonb, '{"en":"Only one of the two is True, which is enough for `or`. `and` would need both, `==` would compare them and find them different, and `not` cannot sit between two values.\n"}'::jsonb, '{"en":"Only one of the two values is True."}'::jsonb, null, false, true, true, array['logic']::text[], 5, 'draft'::public.review_status, 'af8e405849c5fc83dff919c0e005ada5'),
  ('d3f0083b-e0f0-4c3c-ad21-aabe606fbe40', '25cc8af2-388a-4aee-bceb-4c8cd486ca30', 'predict_output'::public.question_type, 'hard'::public.difficulty_level, '{"en":"What does this print?"}'::jsonb, 'print(not 3 > 5 and 2 < 1)
', '{"input":"text"}'::jsonb, '{"en":"Comparisons happen first, then `not`, then `and`. So this is `(not False) and False`, which is `True and False` — False.\n"}'::jsonb, '{"en":"Work out the two comparisons before anything else."}'::jsonb, null, false, true, true, array['logic', 'precedence']::text[], 6, 'draft'::public.review_status, '92c200e8ed741a15a8f88191ef8adc8a'),
  ('d305bd23-4f0c-4f73-a8d6-1b04557b418c', '6e1b0021-5c8b-408c-8bd3-26299d15cfef', 'predict_output'::public.question_type, 'easy'::public.difficulty_level, '{"en":"What does this print?"}'::jsonb, 'print("ha" * 3)
', '{"input":"text"}'::jsonb, '{"en":"Multiplying a string by a number repeats it that many times, with nothing added in between.\n"}'::jsonb, null, null, false, true, true, array['strings']::text[], 1, 'draft'::public.review_status, 'ae503038f50ccf9f67f30fceb0f98554'),
  ('8b811e1e-f896-4afc-a934-9dbf7302b3af', '6e1b0021-5c8b-408c-8bd3-26299d15cfef', 'true_false'::public.question_type, 'easy'::public.difficulty_level, '{"en":"`\"cat\" in \"concatenate\"` is `True`."}'::jsonb, null, '{}'::jsonb, '{"en":"Look closely: con-**cat**-enate. `in` finds the three letters together, in order, anywhere inside the longer string.\n"}'::jsonb, null, null, false, true, true, array['strings']::text[], 2, 'draft'::public.review_status, '7b6dcd604d9ca3b37dc8adf8fce19550'),
  ('3934cd27-0056-4a23-b3fd-5a82ef0565d0', '6e1b0021-5c8b-408c-8bd3-26299d15cfef', 'predict_output'::public.question_type, 'medium'::public.difficulty_level, '{"en":"What does this print?"}'::jsonb, 'print("ba" + "na" * 2)
', '{"input":"text"}'::jsonb, '{"en":"The precedence rules still apply to strings: `*` happens before `+`. So \"na\" is repeated first, giving \"nana\", and then \"ba\" is joined to the front.\n"}'::jsonb, '{"en":"Which happens first, `*` or `+`?"}'::jsonb, null, false, true, true, array['strings', 'precedence']::text[], 3, 'draft'::public.review_status, 'ed6cdd0969514a191544ddd97d013825'),
  ('0cdc7170-23f8-4738-b544-1169d4f11974', '6e1b0021-5c8b-408c-8bd3-26299d15cfef', 'multiple_choice'::public.question_type, 'medium'::public.difficulty_level, '{"en":"What is the value of `\"Python\" == \"python\"`?"}'::jsonb, null, '{"options":[{"id":"is-false","text":{"en":"False"}},{"id":"is-true","text":{"en":"True"}},{"id":"error","text":{"en":"A TypeError"}},{"id":"lower","text":{"en":"\"python\""}}]}'::jsonb, '{"en":"The first letters differ — a capital P and a lowercase p — so the strings are not equal. String comparison never ignores case unless you ask it to.\n"}'::jsonb, null, null, false, true, true, array['strings', 'comparisons']::text[], 4, 'draft'::public.review_status, '95e72e00e4d997395df6cdd11c2570a1'),
  ('e2f96f83-b5bc-4be0-8522-4d403607dd92', '6e1b0021-5c8b-408c-8bd3-26299d15cfef', 'multiple_select'::public.question_type, 'medium'::public.difficulty_level, '{"en":"Which of these are `True`?"}'::jsonb, null, '{"options":[{"id":"letter","text":{"en":"\"a\" in \"cat\""}},{"id":"capital","text":{"en":"\"A\" in \"cat\""}},{"id":"pair","text":{"en":"\"at\" in \"cat\""}},{"id":"backwards","text":{"en":"\"tac\" in \"cat\""}},{"id":"prefix","text":{"en":"\"cat\" in \"category\""}}]}'::jsonb, '{"en":"`in` looks for the exact characters, together and in order. \"a\", \"at\" and \"cat\" all appear that way. \"A\" is a different character from \"a\", and \"tac\" is the right letters in the wrong order.\n"}'::jsonb, null, null, false, true, true, array['strings']::text[], 5, 'draft'::public.review_status, '279298fe9039973cb3553aa3124344fe'),
  ('ba788b60-3d6a-4acf-8b13-24c876850681', '6e1b0021-5c8b-408c-8bd3-26299d15cfef', 'predict_output'::public.question_type, 'hard'::public.difficulty_level, '{"en":"What does this print?"}'::jsonb, 'print("10" < "9")
', '{"input":"text"}'::jsonb, '{"en":"These are strings, not numbers, so they are compared character by character. The first characters are \"1\" and \"9\", and \"1\" comes first — so \"10\" sorts before \"9\". Convert with `int()` to compare them as numbers.\n"}'::jsonb, '{"en":"Look at the quotes. Are these numbers?"}'::jsonb, null, false, true, true, array['strings', 'comparisons']::text[], 6, 'draft'::public.review_status, '2c3ed5e0349f4e41307832579c155601'),
  ('6531dfd0-cc1e-41a4-b8b4-5bd7bcbe94d9', '2aa52e4e-d060-476c-a7c3-ab6f3f0bae46', 'multiple_choice'::public.question_type, 'easy'::public.difficulty_level, '{"en":"Which of these lines is valid Python?"}'::jsonb, null, '{"options":[{"id":"double-outside","text":{"en":"print(\"It''s\")"}},{"id":"single-clash","text":{"en":"print(''It''s'')"}},{"id":"mismatch-a","text":{"en":"print(\"hi'')"}},{"id":"mismatch-b","text":{"en":"print(''hi\")"}}]}'::jsonb, '{"en":"Double quotes on the outside let the apostrophe sit inside safely. In the second, the apostrophe ends the string early. The last two open with one kind of quote and close with the other, so the string never ends.\n"}'::jsonb, null, null, false, true, true, array['strings']::text[], 1, 'draft'::public.review_status, '21905de248861f700a1849c11bf6f027'),
  ('2c86eb73-0e8b-4922-9cfd-efa5113c3f5b', '2aa52e4e-d060-476c-a7c3-ab6f3f0bae46', 'true_false'::public.question_type, 'easy'::public.difficulty_level, '{"en":"`''hello''` and `\"hello\"` are the same string."}'::jsonb, null, '{}'::jsonb, '{"en":"The kind of quote only marks where the string starts and ends. The text inside is the same five characters either way.\n"}'::jsonb, null, null, false, true, true, array['strings']::text[], 2, 'draft'::public.review_status, '29b57f2863c6049b8a3dd8631077edd7'),
  ('2b0a4eb1-eabd-4ceb-974c-3e777d0a3b8a', '2aa52e4e-d060-476c-a7c3-ab6f3f0bae46', 'predict_output'::public.question_type, 'easy'::public.difficulty_level, '{"en":"What does this print?"}'::jsonb, 'print("up\ndown")
', '{"input":"choice","options":[{"id":"two-lines","text":{"en":"up\ndown"}},{"id":"literal","text":{"en":"up\\ndown"}},{"id":"space","text":{"en":"up down"}},{"id":"joined","text":{"en":"updown"}}]}'::jsonb, '{"en":"`\\n` inside a string is a line break, so the text is printed on two lines. The backslash and the n never appear on screen.\n"}'::jsonb, null, null, false, true, true, array['strings']::text[], 3, 'draft'::public.review_status, '8a00db069c883c9be695596c32c08d0f'),
  ('e8b29806-b74c-4f8a-824b-3ebb28b07e20', '2aa52e4e-d060-476c-a7c3-ab6f3f0bae46', 'predict_output'::public.question_type, 'medium'::public.difficulty_level, '{"en":"What does this print?"}'::jsonb, 'print(len("a\nb"))
', '{"input":"text"}'::jsonb, '{"en":"The string holds three characters: \"a\", a line break, and \"b\". The escape `\\n` is written with two keystrokes but stored as a single character.\n"}'::jsonb, '{"en":"How many characters does `\\n` really stand for?"}'::jsonb, null, false, true, true, array['strings']::text[], 4, 'draft'::public.review_status, '5024b9399bec950fdd8de3fc720e116b'),
  ('289e7203-f369-4460-b7a5-ddf3d3934357', '2aa52e4e-d060-476c-a7c3-ab6f3f0bae46', 'predict_output'::public.question_type, 'hard'::public.difficulty_level, '{"en":"A Windows path, printed. What appears?"}'::jsonb, 'print("C:\new")
', '{"input":"choice","options":[{"id":"broken","text":{"en":"C:\new"}},{"id":"literal","text":{"en":"C:\\new"}},{"id":"dropped","text":{"en":"C:new"}},{"id":"error","text":{"en":"A SyntaxError"}}]}'::jsonb, '{"en":"Python reads `\\n` as a line break, so \"C:\" is printed, then a new line, then \"ew\". Paths are a common trap: write `\\\\` for a real backslash, or use forward slashes.\n"}'::jsonb, '{"en":"What does Python do when it sees a backslash followed by n?"}'::jsonb, null, false, true, true, array['strings']::text[], 5, 'draft'::public.review_status, '97fbc63c05ce952e8cd8b30d842727b4'),
  ('0253124a-2c47-46f2-bbd5-95c55914913b', '337a55fa-37c4-4d19-87bb-eb125093290c', 'predict_output'::public.question_type, 'easy'::public.difficulty_level, '{"en":"What does this print?"}'::jsonb, 'print("hello"[1])
', '{"input":"text"}'::jsonb, '{"en":"Counting starts at 0, so index 0 is \"h\" and index 1 is \"e\".\n"}'::jsonb, null, null, false, true, true, array['strings', 'indexing']::text[], 1, 'draft'::public.review_status, '0278b759670c6bf12a9673ffb31d998c'),
  ('a78877a5-ee39-44e8-a074-aa9d9e5366bd', '337a55fa-37c4-4d19-87bb-eb125093290c', 'multiple_choice'::public.question_type, 'easy'::public.difficulty_level, '{"en":"What is the index of the first character in a string?"}'::jsonb, null, '{"options":[{"id":"zero","text":{"en":"0"}},{"id":"one","text":{"en":"1"}},{"id":"minus-one","text":{"en":"-1"}},{"id":"depends","text":{"en":"It depends on the string"}}]}'::jsonb, '{"en":"Python always counts positions from 0. `-1` is the last character, not the first.\n"}'::jsonb, null, null, false, true, true, array['indexing']::text[], 2, 'draft'::public.review_status, '0ebaef2a95d29019295a69d2bf284796'),
  ('5ca3ac04-b028-4701-8e41-b219ea27c65a', '337a55fa-37c4-4d19-87bb-eb125093290c', 'predict_output'::public.question_type, 'medium'::public.difficulty_level, '{"en":"What does this print?"}'::jsonb, 'word = "banana"
print(word[-1] + word[0])
', '{"input":"text"}'::jsonb, '{"en":"`word[-1]` is the last letter, \"a\", and `word[0]` is the first, \"b\". Joined in that order they give \"ab\".\n"}'::jsonb, null, null, false, true, true, array['strings', 'indexing']::text[], 3, 'draft'::public.review_status, 'cc15b03f9c7c843a3b283ac3af015b0a'),
  ('c2aedeeb-d57b-4635-ad68-87602e5221ec', '337a55fa-37c4-4d19-87bb-eb125093290c', 'fill_blank'::public.question_type, 'medium'::public.difficulty_level, '{"en":"Complete the line so it prints the last character of any word, whatever its length."}'::jsonb, 'print(word[___])
', '{"input":"tokens","tokens":["-1","0","1","len(word)"]}'::jsonb, '{"en":"`-1` always means the last character. `len(word)` is one past the end and would raise an IndexError.\n"}'::jsonb, '{"en":"Count from the end instead of the start."}'::jsonb, null, false, true, true, array['indexing']::text[], 4, 'draft'::public.review_status, 'b723f82d0b4c5f04ba16a5c22330b7cd'),
  ('525f80ed-f057-4aaf-8b6d-0c3ffd4ada58', '337a55fa-37c4-4d19-87bb-eb125093290c', 'true_false'::public.question_type, 'medium'::public.difficulty_level, '{"en":"For a five-letter string `s`, `s[5]` gives its last character."}'::jsonb, null, '{}'::jsonb, '{"en":"Five characters sit at positions 0 to 4. `s[5]` is past the end and raises an IndexError. The last character is `s[4]`, or `s[-1]`.\n"}'::jsonb, null, null, false, true, true, array['indexing', 'errors']::text[], 5, 'draft'::public.review_status, '1777b4e94fc83cc43010a95841de1242'),
  ('be69e6ef-d979-41ab-88e5-934a12f22220', '337a55fa-37c4-4d19-87bb-eb125093290c', 'debugging'::public.question_type, 'hard'::public.difficulty_level, '{"en":"This should print the last letter of \"cat\", but it crashes. Which line is wrong?"}'::jsonb, 'word = "cat"
last = word[3]
print(last)
', '{"mode":"select_line","lines":[{"id":"assign","text":"word = \"cat\""},{"id":"pick","text":"last = word[3]"},{"id":"show","text":"print(last)"}]}'::jsonb, '{"en":"\"cat\" has three letters at positions 0, 1 and 2, so index 3 does not exist. `word[2]` or `word[-1]` both give \"t\".\n"}'::jsonb, '{"en":"How many positions does a three-letter word have, starting from 0?"}'::jsonb, null, false, true, true, array['indexing', 'debugging']::text[], 6, 'draft'::public.review_status, '92cd09c35b64e06e29e1b474582bed7e'),
  ('b8306d93-0775-4853-b921-7209ec347066', '9a76c6fd-c3b6-44cf-8fca-e424ac03d8f9', 'predict_output'::public.question_type, 'easy'::public.difficulty_level, '{"en":"What does this print?"}'::jsonb, 'print("Python"[0:3])
', '{"input":"text"}'::jsonb, '{"en":"Positions 0, 1 and 2 — \"P\", \"y\" and \"t\". Position 3 is where the slice stops, so \"h\" is not included.\n"}'::jsonb, null, null, false, true, true, array['strings', 'slicing']::text[], 1, 'draft'::public.review_status, '41a339444ef88b102db2210f8f3a77d9'),
  ('6bdeb65c-f9ce-47bd-9f44-4d594d4720bb', '9a76c6fd-c3b6-44cf-8fca-e424ac03d8f9', 'true_false'::public.question_type, 'easy'::public.difficulty_level, '{"en":"In `word[2:5]`, the character at index 5 is included in the slice."}'::jsonb, null, '{}'::jsonb, '{"en":"A slice runs up to the stop but not including it. `word[2:5]` gives the characters at positions 2, 3 and 4.\n"}'::jsonb, null, null, false, true, true, array['slicing']::text[], 2, 'draft'::public.review_status, '0cef7073b194635a93cb07627bc67692'),
  ('7bb0e1df-b4e5-4338-98e7-26036ddee92c', '9a76c6fd-c3b6-44cf-8fca-e424ac03d8f9', 'predict_output'::public.question_type, 'medium'::public.difficulty_level, '{"en":"What does this print?"}'::jsonb, 'print("abcdef"[2:])
', '{"input":"text"}'::jsonb, '{"en":"With no stop, the slice runs from index 2 to the end. Index 2 is \"c\", so the result is \"cdef\".\n"}'::jsonb, null, null, false, true, true, array['slicing']::text[], 3, 'draft'::public.review_status, 'a1d1a6115215f69d4681069fca1c50a2'),
  ('1aa88729-d977-470d-af51-bd576a44facc', '9a76c6fd-c3b6-44cf-8fca-e424ac03d8f9', 'multiple_choice'::public.question_type, 'medium'::public.difficulty_level, '{"en":"With `s = \"hello\"`, which slice gives `\"ell\"`?"}'::jsonb, null, '{"options":[{"id":"right","text":{"en":"s[1:4]"}},{"id":"short","text":{"en":"s[1:3]"}},{"id":"shifted","text":{"en":"s[2:4]"}},{"id":"start","text":{"en":"s[0:3]"}}]}'::jsonb, '{"en":"\"ell\" is at positions 1, 2 and 3. The stop has to be one past the last position you want, so the slice is `[1:4]`.\n"}'::jsonb, '{"en":"The stop is one past the last character you want."}'::jsonb, null, false, true, true, array['slicing']::text[], 4, 'draft'::public.review_status, '10f8e27696907147e4f00c551076b4fc'),
  ('568f9101-7e51-443a-9048-ae3b71177ab9', '9a76c6fd-c3b6-44cf-8fca-e424ac03d8f9', 'predict_output'::public.question_type, 'hard'::public.difficulty_level, '{"en":"What does this print?"}'::jsonb, 'print("abcdef"[1:5:2])
', '{"input":"text"}'::jsonb, '{"en":"The slice starts at index 1 (\"b\"), stops before index 5, and moves two steps at a time: index 1, then 3. That gives \"b\" and \"d\". Index 5 would be next, but the slice stops before it.\n"}'::jsonb, '{"en":"List the indexes the slice visits, starting at 1 and adding 2 each time."}'::jsonb, null, false, true, true, array['slicing']::text[], 5, 'draft'::public.review_status, '274a425142abaf979d21ad291a7dd3c4'),
  ('41b7ecbc-6373-47b6-be68-3527ecff4f66', '4a9f9773-c6c9-4873-8084-cf230f79c381', 'predict_output'::public.question_type, 'easy'::public.difficulty_level, '{"en":"What does this print?"}'::jsonb, 'x = 4
print(f"x is {x}")
', '{"input":"text"}'::jsonb, '{"en":"The value of `x` replaces `{x}`. The rest of the text, including the letter x at the start, is printed exactly as written.\n"}'::jsonb, null, null, false, true, true, array['strings', 'f-strings']::text[], 1, 'draft'::public.review_status, 'fd70818cfdcddcc5cf3e61837ad6825e'),
  ('ca7a8093-efdf-4f07-952e-89f198850e3a', '4a9f9773-c6c9-4873-8084-cf230f79c381', 'multiple_choice'::public.question_type, 'easy'::public.difficulty_level, '{"en":"What turns an ordinary string into an f-string?"}'::jsonb, null, '{"options":[{"id":"prefix","text":{"en":"The letter f just before the opening quote"}},{"id":"braces","text":{"en":"Curly braces anywhere inside it"}},{"id":"format","text":{"en":"The word format at the end"}},{"id":"dollar","text":{"en":"A $ sign before each value"}}]}'::jsonb, '{"en":"The `f` prefix is what tells Python to fill in the braces. Braces in an ordinary string are printed as they are.\n"}'::jsonb, null, null, false, true, true, array['f-strings']::text[], 2, 'draft'::public.review_status, 'ee6a23bb8f94e83d6afcef8c914ceec3'),
  ('96b2ca33-d0a8-45a1-b292-13a777454d18', '4a9f9773-c6c9-4873-8084-cf230f79c381', 'predict_output'::public.question_type, 'medium'::public.difficulty_level, '{"en":"What does this print?"}'::jsonb, 'n = 3
print(f"{n} * 2 = {n * 2}")
', '{"input":"text"}'::jsonb, '{"en":"Only the parts inside braces are worked out. The `* 2 =` between them is ordinary text, while `{n * 2}` is a calculation that gives 6.\n"}'::jsonb, null, null, false, true, true, array['f-strings']::text[], 3, 'draft'::public.review_status, '521367c2580357a0e6871a13cb7e64ea'),
  ('babf8462-5bcc-4f75-9b50-c99a507dcdd8', '4a9f9773-c6c9-4873-8084-cf230f79c381', 'debugging'::public.question_type, 'medium'::public.difficulty_level, '{"en":"This should print \"Hello, Sam!\", but it prints \"Hello, {name}!\". How do you fix it?"}'::jsonb, 'name = "Sam"
