  ('c6770581-a5bb-404e-b07a-0b354d24962b', '4a9f9773-c6c9-4873-8084-cf230f79c381', 'fill_blank'::public.question_type, 'medium'::public.difficulty_level, '{"en":"Complete the line so it prints `2.50`."}'::jsonb, 'price = 2.5
