', '{"input":"tokens","tokens":[".2f",".1f","2f","2"]}'::jsonb, '{"en":"`.2f` asks for two digits after the decimal point. `.1f` would give 2.5, and the last two do not control decimal places at all.\n"}'::jsonb, '{"en":"How many digits do you want after the point?"}'::jsonb, null, false, true, true, array['f-strings']::text[], 5, 'draft'::public.review_status, 'fc2d538ece44f2088c2f954aac694280'),
  ('3362370d-e7ee-4bf8-bc64-aabe91c36e4c', '4a9f9773-c6c9-4873-8084-cf230f79c381', 'predict_output'::public.question_type, 'hard'::public.difficulty_level, '{"en":"What does this print?"}'::jsonb, 'print(f"{2.5:.0f}")
', '{"input":"text"}'::jsonb, '{"en":"A value exactly halfway is rounded to the nearest **even** number, not always up. 2.5 is halfway between 2 and 3, and 2 is even. `round(2.5)` does the same, while `round(3.5)` gives 4.\n"}'::jsonb, '{"en":"Halfway cases do not always round up in Python."}'::jsonb, null, false, true, true, array['f-strings', 'numbers']::text[], 6, 'draft'::public.review_status, 'c9d13e3754a08d622ea8d4a1d459554a'),
  ('a8bf8dbb-a9fd-4869-ad57-b2728e095a2d', 'ec113538-c53e-4725-858f-e002722477c1', 'predict_output'::public.question_type, 'easy'::public.difficulty_level, '{"en":"What does this print?"}'::jsonb, 'print("python".upper())
', '{"input":"text"}'::jsonb, '{"en":"`upper()` returns a copy of the string with every letter in capitals.\n"}'::jsonb, null, null, false, true, true, array['string-methods']::text[], 1, 'draft'::public.review_status, 'e452ef6f0972d6cf332b54afa1b4f1de'),
  ('72e13076-03dd-42e4-a331-19a841b1d5e2', 'ec113538-c53e-4725-858f-e002722477c1', 'true_false'::public.question_type, 'easy'::public.difficulty_level, '{"en":"`strip()` removes the spaces from the middle of a string."}'::jsonb, null, '{}'::jsonb, '{"en":"`strip()` only removes spaces from the two ends. Spaces between words are left alone.\n"}'::jsonb, null, null, false, true, true, array['string-methods']::text[], 2, 'draft'::public.review_status, 'ff4e571d2c953f036d5bff05fed89f38'),
  ('4bc46b6f-6b7f-4acc-a361-e5116a913626', 'ec113538-c53e-4725-858f-e002722477c1', 'predict_output'::public.question_type, 'medium'::public.difficulty_level, '{"en":"What does this print?"}'::jsonb, 's = "banana"
print(s.replace("a", "o"))
', '{"input":"text"}'::jsonb, '{"en":"`replace()` swaps **every** \"a\", not just the first one. All three become \"o\".\n"}'::jsonb, null, null, false, true, true, array['string-methods']::text[], 3, 'draft'::public.review_status, '2a259d413eeb9a3709b4575bcf18e098'),
  ('f1c958d5-9e51-4c79-80a6-6dd98507e393', 'ec113538-c53e-4725-858f-e002722477c1', 'concept_matching'::public.question_type, 'medium'::public.difficulty_level, '{"en":"Match each method to what it gives back."}'::jsonb, null, '{"concepts":[{"id":"upper","text":{"en":"upper()"}},{"id":"lower","text":{"en":"lower()"}},{"id":"strip","text":{"en":"strip()"}},{"id":"replace","text":{"en":"replace(\"a\", \"b\")"}}],"definitions":[{"id":"capitals","text":{"en":"The text in capital letters"}},{"id":"small","text":{"en":"The text in lowercase letters"}},{"id":"trimmed","text":{"en":"The text without spaces at either end"}},{"id":"swapped","text":{"en":"The text with every a changed to b"}}]}'::jsonb, '{"en":"Each one returns a new string built from the old one. None of them changes the original.\n"}'::jsonb, null, null, false, true, true, array['string-methods']::text[], 4, 'draft'::public.review_status, '163fe57e4f9b0e2da4810017c77b3bd7'),
  ('5b507580-b48d-4c30-a901-ec4feabb2989', 'ec113538-c53e-4725-858f-e002722477c1', 'multiple_select'::public.question_type, 'medium'::public.difficulty_level, '{"en":"Starting from `s = \"Hi\"`, which lines leave `s` still holding `\"Hi\"`?"}'::jsonb, null, '{"options":[{"id":"discarded","text":{"en":"s.upper()"}},{"id":"reassigned","text":{"en":"s = s.upper()"}},{"id":"other-name","text":{"en":"t = s.lower()"}},{"id":"printed","text":{"en":"print(s.replace(\"H\", \"J\"))"}},{"id":"extended","text":{"en":"s = s + \"!\""}}]}'::jsonb, '{"en":"Methods never change `s` itself. Only a line that assigns back to `s` — the second and the last — gives it a new value. The others build a new string and either throw it away, store it elsewhere, or print it.\n"}'::jsonb, '{"en":"Look for `s =` at the start of the line."}'::jsonb, null, false, true, true, array['string-methods', 'variables']::text[], 5, 'draft'::public.review_status, 'f3c21761ed8d7cbabbcda430d9700dc2'),
  ('5547081d-873d-47f2-a6eb-fd38514ac781', 'ec113538-c53e-4725-858f-e002722477c1', 'code_ordering'::public.question_type, 'hard'::public.difficulty_level, '{"en":"Arrange the lines so the program prints `HELLO!`."}'::jsonb, null, '{"lines":[{"id":"raw","text":"raw = \"  hello  \""},{"id":"clean","text":"clean = raw.strip()"},{"id":"loud","text":"loud = clean.upper()"},{"id":"show","text":"print(loud + \"!\")"}]}'::jsonb, '{"en":"Each line works on the result of the one before: strip the spaces, then shout, then add the exclamation mark. Because strings never change in place, every step needs its own name to keep its result.\n"}'::jsonb, null, null, false, true, true, array['string-methods', 'variables']::text[], 6, 'draft'::public.review_status, '7492ef87b970ee362924c261a9ac2f26'),
  ('4ef18f70-2100-4bef-aea3-106901dbc542', 'c37dd7cc-f1df-4bd0-a741-63174d5dd4e2', 'true_false'::public.question_type, 'easy'::public.difficulty_level, '{"en":"The lines indented under an `if` run only when its condition is True."}'::jsonb, null, '{}'::jsonb, '{"en":"That is exactly what the indentation says: these lines belong to the `if`. When the condition is False, Python skips them and carries on with the next unindented line.\n"}'::jsonb, null, null, false, true, true, array['conditions']::text[], 1, 'draft'::public.review_status, '29d36b6e80c8b8fdfce0affb1f874c4d'),
  ('fa2e0990-70fd-4ab9-ba28-9405645447bb', 'c37dd7cc-f1df-4bd0-a741-63174d5dd4e2', 'multiple_choice'::public.question_type, 'easy'::public.difficulty_level, '{"en":"What must come at the end of an `if` line?"}'::jsonb, null, '{"options":[{"id":"colon","text":{"en":"A colon (:)"}},{"id":"semicolon","text":{"en":"A semicolon (;)"}},{"id":"nothing","text":{"en":"Nothing at all"}},{"id":"brace","text":{"en":"An opening brace ({)"}}]}'::jsonb, '{"en":"The colon says \"a block starts here\". Python uses indentation instead of braces to mark where the block begins and ends.\n"}'::jsonb, null, null, false, true, true, array['conditions', 'syntax']::text[], 2, 'draft'::public.review_status, '685329f78fb2105feb54acab6a00600e'),
  ('b5af4e72-abbd-420c-8b2c-fabdc6120f2c', 'c37dd7cc-f1df-4bd0-a741-63174d5dd4e2', 'predict_output'::public.question_type, 'medium'::public.difficulty_level, '{"en":"What does this print?"}'::jsonb, 'x = 3
