  ('ecea39aa-60eb-46b5-a71a-152ceb6b6dbb', 'c37dd7cc-f1df-4bd0-a741-63174d5dd4e2', 'debugging'::public.question_type, 'medium'::public.difficulty_level, '{"en":"This will not run at all. Which line is the problem?"}'::jsonb, 'score = 90
