  ('9cb611ad-025b-45c8-af77-d1aa6a66eda3', 'c37dd7cc-f1df-4bd0-a741-63174d5dd4e2', 'predict_output'::public.question_type, 'hard'::public.difficulty_level, '{"en":"What does this print?"}'::jsonb, 'x = 2
