  ('ccb6aee2-6970-4446-a092-59f495e363e6', 'd8e1f3f4-3857-4b1b-a3ad-a4e75d8eaff9', 'true_false'::public.question_type, 'easy'::public.difficulty_level, '{"en":"An `else` can have its own condition, like `else x > 5:`."}'::jsonb, null, '{}'::jsonb, '{"en":"`else` never takes a condition — it simply means \"in every other case\". To test a second condition you need `elif`, which is the next lesson.\n"}'::jsonb, null, null, false, true, true, array['conditions', 'syntax']::text[], 2, 'draft'::public.review_status, '8f8df4e3d7f6ae7c6100bc9cd76ca3f4'),
  ('1aa3ef4f-9078-4301-b7f5-0c4e65603873', 'd8e1f3f4-3857-4b1b-a3ad-a4e75d8eaff9', 'fill_blank'::public.question_type, 'medium'::public.difficulty_level, '{"en":"Complete the program so the second message appears when there is not enough money."}'::jsonb, 'if balance >= price:
