  ('07341cbb-364d-4c8e-954f-5b68aa339023', 'd8e1f3f4-3857-4b1b-a3ad-a4e75d8eaff9', 'multiple_choice'::public.question_type, 'medium'::public.difficulty_level, '{"en":"When does the `else` block run?"}'::jsonb, null, '{"options":[{"id":"when-false","text":{"en":"When the if condition is False"}},{"id":"always","text":{"en":"Always, after the if block"}},{"id":"when-true","text":{"en":"When the if condition is True"}},{"id":"on-error","text":{"en":"Only when the program hits an error"}}]}'::jsonb, '{"en":"`if` and `else` are two halves of one decision. The `else` half runs exactly when the `if` half does not.\n"}'::jsonb, null, null, false, true, true, array['conditions']::text[], 4, 'draft'::public.review_status, '621662097e850596068039be87cb1348'),
  ('d520a066-0bdf-4a8f-96e6-be829b7d2659', 'd8e1f3f4-3857-4b1b-a3ad-a4e75d8eaff9', 'predict_output'::public.question_type, 'hard'::public.difficulty_level, '{"en":"What does this print?"}'::jsonb, 'x = 10
