  ('6ffc7716-119e-4b06-b745-de8e4746c5b0', '8e0aadeb-48fd-438e-b2cf-26546a943d23', 'multiple_choice'::public.question_type, 'easy'::public.difficulty_level, '{"en":"In an if / elif / else chain, how many blocks run?"}'::jsonb, null, '{"options":[{"id":"one","text":{"en":"One — the first whose condition is True, or the else"}},{"id":"every-true","text":{"en":"Every block whose condition is True"}},{"id":"all","text":{"en":"All of them, top to bottom"}},{"id":"last","text":{"en":"Only the last one"}}]}'::jsonb, '{"en":"The chain stops at the first True condition. If none is True, the `else` runs — so with an `else`, exactly one block always runs.\n"}'::jsonb, null, null, false, true, true, array['conditions']::text[], 1, 'draft'::public.review_status, '07c5c549ed447eef126a7894d669d8d3'),
  ('668cce95-c43d-46cd-a2d6-616593090160', '8e0aadeb-48fd-438e-b2cf-26546a943d23', 'true_false'::public.question_type, 'easy'::public.difficulty_level, '{"en":"`elif` is short for \"else if\"."}'::jsonb, null, '{}'::jsonb, '{"en":"It means: if nothing above matched, check this condition next.\n"}'::jsonb, null, null, false, true, true, array['conditions']::text[], 2, 'draft'::public.review_status, '547117eadda7ced1f8f6e082250a0cf2'),
  ('77b6cabb-7ea7-4e97-8b3a-7ae6f8ef1a25', '8e0aadeb-48fd-438e-b2cf-26546a943d23', 'predict_output'::public.question_type, 'medium'::public.difficulty_level, '{"en":"What does this print?"}'::jsonb, 'temp = 15
