  ('0e34bf48-95f3-413c-bbfb-fd8255908e11', '8e0aadeb-48fd-438e-b2cf-26546a943d23', 'predict_output'::public.question_type, 'medium'::public.difficulty_level, '{"en":"What does this print?"}'::jsonb, 'n = 0
