  ('0fc974ea-ae63-45d0-bf9f-4e11f5cbeb91', '8e0aadeb-48fd-438e-b2cf-26546a943d23', 'multiple_select'::public.question_type, 'medium'::public.difficulty_level, '{"en":"Which of these scores would make this chain print B?"}'::jsonb, 'if score >= 90:
