  ('24d72f0b-743d-4d00-8911-0edfbfee206d', '8e0aadeb-48fd-438e-b2cf-26546a943d23', 'debugging'::public.question_type, 'hard'::public.difficulty_level, '{"en":"The rule is: 90 and above is an A, 50 to 89 is a C. But a score of 95 gets a C. Which change makes the program follow the rule for every score?\n"}'::jsonb, 'score = 95
