  ('4be79f7e-7474-4fc4-bd38-b0d0a0954bc6', 'c0c663c6-9bd5-4bb6-929a-fe0c32662a1f', 'true_false'::public.question_type, 'easy'::public.difficulty_level, '{"en":"A nested `if` is only checked when the outer `if` condition is True."}'::jsonb, null, '{}'::jsonb, '{"en":"The inner `if` lives inside the outer block. If the outer block is skipped, so is everything in it, including the inner check.\n"}'::jsonb, null, null, false, true, true, array['conditions']::text[], 2, 'draft'::public.review_status, '91fa95d45b2832bb9d8ddfa5747448f2'),
  ('7df95cef-4b60-4950-b105-6d946e628d5f', 'c0c663c6-9bd5-4bb6-929a-fe0c32662a1f', 'predict_output'::public.question_type, 'medium'::public.difficulty_level, '{"en":"What does this print?"}'::jsonb, 'rain = True
