  ('1c061773-3fce-460b-96aa-e56b45d3f48b', 'c0c663c6-9bd5-4bb6-929a-fe0c32662a1f', 'multiple_choice'::public.question_type, 'medium'::public.difficulty_level, '{"en":"Which single `if` does the same job as this nested pair?"}'::jsonb, 'if a:
