  ('ede2ad3a-f487-4ddb-8b72-4cf5e4152362', '14558780-0061-4706-8700-39d8d24f1dfd', 'true_false'::public.question_type, 'easy'::public.difficulty_level, '{"en":"A `while` loop checks its condition before every round."}'::jsonb, null, '{}'::jsonb, '{"en":"Including the very first one — so if the condition starts out False, the block never runs at all.\n"}'::jsonb, null, null, false, true, true, array['loops']::text[], 1, 'draft'::public.review_status, 'a97f98ac5d4e15d13bf460d05e5b063a'),
  ('2824bcbe-710d-40cf-850a-223a6bc5a084', '14558780-0061-4706-8700-39d8d24f1dfd', 'multiple_choice'::public.question_type, 'easy'::public.difficulty_level, '{"en":"What makes a `while` loop stop?"}'::jsonb, null, '{"options":[{"id":"condition","text":{"en":"Its condition becoming False"}},{"id":"file-end","text":{"en":"Reaching the end of the file"}},{"id":"ten","text":{"en":"Running ten times"}},{"id":"print","text":{"en":"Calling print"}}]}'::jsonb, '{"en":"A `while` loop has no built-in limit. It runs until its condition is False when it is checked.\n"}'::jsonb, null, null, false, true, true, array['loops']::text[], 2, 'draft'::public.review_status, 'b46ef2cd9d1c1167f2699e1fc0b3112f'),
