  ('30e1653f-1bfe-4781-b351-93ad9e2c9ec7', '14558780-0061-4706-8700-39d8d24f1dfd', 'multiple_select'::public.question_type, 'hard'::public.difficulty_level, '{"en":"Which of these loops would never stop on their own?"}'::jsonb, null, '{"options":[{"id":"grows","text":{"en":"n starts at 1; the loop runs while n > 0 and adds 1 each round"}},{"id":"reaches","text":{"en":"n starts at 1; the loop runs while n < 5 and adds 1 each round"}},{"id":"skips","text":{"en":"n starts at 1; the loop runs while n != 10 and adds 2 each round"}},{"id":"passes","text":{"en":"n starts at 10; the loop runs while n > 0 and subtracts 3 each round"}},{"id":"forever","text":{"en":"The loop runs while True and only prints"}}]}'::jsonb, '{"en":"The first moves away from its stopping point. The third goes 1, 3, 5, 7, 9, 11 — it jumps straight over 10, so `n != 10` stays True. `while True` never becomes False. The other two reach their stopping points.\n"}'::jsonb, '{"en":"For each one, ask whether n ever makes the condition False."}'::jsonb, null, false, true, true, array['loops']::text[], 5, 'draft'::public.review_status, '35eb08cb5dfbac7a3b2da2a0fa0c82af'),
  ('c626273c-c3e8-4428-a119-f7d256b1634b', 'd09cc47b-e32a-447b-af4a-5f7da1b4977a', 'multiple_choice'::public.question_type, 'easy'::public.difficulty_level, '{"en":"What does `break` do inside a loop?"}'::jsonb, null, '{"options":[{"id":"leave","text":{"en":"Leaves the loop immediately"}},{"id":"skip","text":{"en":"Skips to the next round"}},{"id":"stop-program","text":{"en":"Stops the whole program"}},{"id":"restart","text":{"en":"Starts the loop again from the beginning"}}]}'::jsonb, '{"en":"`break` ends the loop at once, and the program continues with the first line after the loop. Skipping to the next round is what `continue` does.\n"}'::jsonb, null, null, false, true, true, array['loops']::text[], 1, 'draft'::public.review_status, '6549f37174356f2f501b2c2a53ea6d21'),
  ('eee7d121-1792-4e1e-bc88-b38c8f9a6a4b', 'd09cc47b-e32a-447b-af4a-5f7da1b4977a', 'true_false'::public.question_type, 'easy'::public.difficulty_level, '{"en":"`continue` ends the loop completely."}'::jsonb, null, '{}'::jsonb, '{"en":"`continue` only abandons the current round. The loop goes on with the next value.\n"}'::jsonb, null, null, false, true, true, array['loops']::text[], 2, 'draft'::public.review_status, 'aae2830fe40776a9ff0fdc390b19697b'),
  ('5c6fdd65-46d2-4e29-acfc-f182291d9ceb', 'd09cc47b-e32a-447b-af4a-5f7da1b4977a', 'predict_output'::public.question_type, 'medium'::public.difficulty_level, '{"en":"What does this print?"}'::jsonb, 'for i in range(5):
    if i == 2:
        continue
    print(i)
