  ('ce805186-f9a0-4471-8b6f-92e7ec47947b', 'd09cc47b-e32a-447b-af4a-5f7da1b4977a', 'predict_output'::public.question_type, 'medium'::public.difficulty_level, '{"en":"What does this print?"}'::jsonb, 'for i in range(5):
