  ('f0eb7171-62b7-4496-aa8f-c9cda46bec06', 'd09cc47b-e32a-447b-af4a-5f7da1b4977a', 'concept_matching'::public.question_type, 'medium'::public.difficulty_level, '{"en":"Match each one to what it does."}'::jsonb, null, '{"concepts":[{"id":"break","text":{"en":"break"}},{"id":"continue","text":{"en":"continue"}},{"id":"false-condition","text":{"en":"A while condition turning False"}}],"definitions":[{"id":"leave-now","text":{"en":"Leaves the loop at once, in the middle of a round"}},{"id":"next-round","text":{"en":"Skips the rest of this round and starts the next"}},{"id":"ends-at-check","text":{"en":"Ends the loop the next time the condition is checked"}}]}'::jsonb, '{"en":"`break` and `continue` act the moment they run. A condition only matters when it is checked, which is at the top of each round.\n"}'::jsonb, null, null, false, true, true, array['loops']::text[], 5, 'draft'::public.review_status, 'aa8be12b9d25dd02d73e505137eaa6c8'),
  ('db033ab0-235a-451f-835b-7169b7d17456', 'd09cc47b-e32a-447b-af4a-5f7da1b4977a', 'predict_output'::public.question_type, 'hard'::public.difficulty_level, '{"en":"What does this print?"}'::jsonb, 'n = 0
