  ('a876a506-1be3-4e01-ab50-606e234229ee', '99d03e20-2ae2-48b7-b027-5d1ba3c0d9d2', 'concept_matching'::public.question_type, 'hard'::public.difficulty_level, '{"en":"Match each line to what `b` ends up being."}'::jsonb, null, '{"concepts":[{"id":"alias","text":{"en":"b = a"}},{"id":"copy","text":{"en":"b = a.copy()"}},{"id":"tail","text":{"en":"b = a[1:]"}}],"definitions":[{"id":"same","text":{"en":"The same list as a, under a second name"}},{"id":"separate","text":{"en":"A separate list with all of a''s items"}},{"id":"shorter","text":{"en":"A new list without a''s first item"}}]}'::jsonb, '{"en":"Only plain assignment shares the list. Both `copy()` and a slice build a new list, so later changes to `b` stay in `b`.\n"}'::jsonb, null, null, false, true, true, array['lists', 'slicing']::text[], 5, 'draft'::public.review_status, 'b51ef58b71f9c3fdcb17ea8ed38685b1'),
