  ('6b491324-c74e-450e-ac92-2cd2a7cf55da', '7cdeab88-9b51-474c-89cd-351e7ff4895e', 'multiple_choice'::public.question_type, 'easy'::public.difficulty_level, '{"en":"Which keyword starts a function definition in Python?"}'::jsonb, null, '{"options":[{"id":"def","text":{"en":"def"}},{"id":"function","text":{"en":"function"}},{"id":"fn","text":{"en":"fn"}},{"id":"define","text":{"en":"define"}}]}'::jsonb, '{"en":"Python uses `def`, short for define. `function` and `fn` are used by other languages.\n"}'::jsonb, null, null, false, true, true, array['functions']::text[], 1, 'draft'::public.review_status, '5014810dbafa3e9c488927a8b4ac566d'),
  ('d0e421da-7c49-449e-87b1-85f8e8970cf8', '7cdeab88-9b51-474c-89cd-351e7ff4895e', 'true_false'::public.question_type, 'easy'::public.difficulty_level, '{"en":"Defining a function runs the code inside it straight away."}'::jsonb, null, '{}'::jsonb, '{"en":"`def` only stores the function under its name. The body runs each time the function is called.\n"}'::jsonb, null, null, false, true, true, array['functions']::text[], 2, 'draft'::public.review_status, 'c4a5d7fa8a976963c0c13eaafac5f52e'),
  ('8cfae932-3bfb-471c-aba5-78d378d7b54c', '7cdeab88-9b51-474c-89cd-351e7ff4895e', 'predict_output'::public.question_type, 'medium'::public.difficulty_level, '{"en":"What does this print?"}'::jsonb, 'def ping():
