  ('ca21c309-63be-4092-bef6-4e58e0863611', '7cdeab88-9b51-474c-89cd-351e7ff4895e', 'debugging'::public.question_type, 'medium'::public.difficulty_level, '{"en":"This stops with a NameError. Which line is in the wrong place?"}'::jsonb, 'say_hi()
