  ('92e02a50-703b-4fab-a6c9-50488ecac8bc', '7cdeab88-9b51-474c-89cd-351e7ff4895e', 'predict_output'::public.question_type, 'hard'::public.difficulty_level, '{"en":"What does this print?"}'::jsonb, 'def a():
