  ('38038d86-7918-4b9d-9c0e-a644a8296ae9', 'b3d55681-24cb-451f-b9b3-ba15d269ba33', 'predict_output'::public.question_type, 'easy'::public.difficulty_level, '{"en":"What does this print?"}'::jsonb, 'def double(n):
