  ('40549fe6-33e1-4a66-bc90-952c982e138e', 'b3d55681-24cb-451f-b9b3-ba15d269ba33', 'multiple_choice'::public.question_type, 'easy'::public.difficulty_level, '{"en":"In `def area(w, h):`, what are `w` and `h` called?"}'::jsonb, null, '{"options":[{"id":"parameters","text":{"en":"Parameters"}},{"id":"returns","text":{"en":"Return values"}},{"id":"globals","text":{"en":"Global variables"}},{"id":"keywords","text":{"en":"Keywords"}}]}'::jsonb, '{"en":"The names in the definition are parameters. The actual values passed in a call, like the 3 and 4 in `area(3, 4)`, are arguments.\n"}'::jsonb, null, null, false, true, true, array['functions', 'parameters']::text[], 2, 'draft'::public.review_status, 'e69d4077868fbc5c0bdc9f6bbaea3164'),
  ('24d7fb88-84a7-4fcb-9955-a56c5aba7738', 'b3d55681-24cb-451f-b9b3-ba15d269ba33', 'predict_output'::public.question_type, 'medium'::public.difficulty_level, '{"en":"What does this print?"}'::jsonb, 'def minus(a, b):
