  ('de783549-ba6e-49f6-9c7d-fcb7b7672867', 'b3d55681-24cb-451f-b9b3-ba15d269ba33', 'true_false'::public.question_type, 'medium'::public.difficulty_level, '{"en":"Plain arguments are matched to parameters by their position."}'::jsonb, null, '{}'::jsonb, '{"en":"The first argument fills the first parameter, the second fills the second. The next lesson shows how to name them instead.\n"}'::jsonb, null, null, false, true, true, array['functions', 'parameters']::text[], 4, 'draft'::public.review_status, '062ec229cf522e7ee0a1910c0d5e9097'),
  ('0f1e9f43-c693-493d-ba2b-a3edb30b8e3a', 'b3d55681-24cb-451f-b9b3-ba15d269ba33', 'fill_blank'::public.question_type, 'medium'::public.difficulty_level, '{"en":"Complete the definition so the call prints `Hi Bo`."}'::jsonb, 'def greet(___):
