  ('fc21b405-77cb-4819-aff9-4a10e4a53c8b', 'b3d55681-24cb-451f-b9b3-ba15d269ba33', 'multiple_select'::public.question_type, 'hard'::public.difficulty_level, '{"en":"For `def box(w, h, d):`, which calls stop with a TypeError?"}'::jsonb, null, '{"options":[{"id":"two","text":{"en":"box(1, 2)"}},{"id":"three","text":{"en":"box(1, 2, 3)"}},{"id":"none","text":{"en":"box()"}},{"id":"four","text":{"en":"box(1, 2, 3, 4)"}},{"id":"reversed","text":{"en":"box(3, 2, 1)"}}]}'::jsonb, '{"en":"`box` needs exactly three arguments. Two, none or four is a TypeError. Three in a different order is perfectly legal — Python cannot know you meant them another way.\n"}'::jsonb, '{"en":"Count the arguments. Their order does not cause an error."}'::jsonb, null, false, true, true, array['functions', 'parameters', 'errors']::text[], 6, 'draft'::public.review_status, 'be765ea79d93758d809d60b4b57ea1aa'),
  ('37c4c1fe-7d92-413d-bb0d-3ad5cc18fcc6', '812a8031-d53b-4ae0-bc13-517856c5c4ab', 'predict_output'::public.question_type, 'easy'::public.difficulty_level, '{"en":"What does this print?"}'::jsonb, 'def add(a, b):
