  ('0796c892-cbf5-4f3a-a9d8-c7fe98ee6c6b', '812a8031-d53b-4ae0-bc13-517856c5c4ab', 'true_false'::public.question_type, 'easy'::public.difficulty_level, '{"en":"A function with no `return` statement gives back `None`."}'::jsonb, null, '{}'::jsonb, '{"en":"Every call produces a value. Without a `return`, that value is `None`.\n"}'::jsonb, null, null, false, true, true, array['functions', 'return', 'none']::text[], 2, 'draft'::public.review_status, '5919ae59b75f0755b2c21220d98599fc'),
  ('ec9498bd-589d-4514-81ab-3004772072c7', '812a8031-d53b-4ae0-bc13-517856c5c4ab', 'predict_output'::public.question_type, 'medium'::public.difficulty_level, '{"en":"What does this print?"}'::jsonb, 'def f(x):
