  ('0e28c005-b444-4d8e-aa3a-aa861afb973c', '812a8031-d53b-4ae0-bc13-517856c5c4ab', 'concept_matching'::public.question_type, 'medium'::public.difficulty_level, '{"en":"Match each one to what it does."}'::jsonb, null, '{"concepts":[{"id":"print","text":{"en":"print(value)"}},{"id":"return","text":{"en":"return value"}},{"id":"missing","text":{"en":"A function with no return"}}],"definitions":[{"id":"shows","text":{"en":"Shows the value on screen and keeps nothing"}},{"id":"hands-back","text":{"en":"Hands the value back to the caller and ends the function"}},{"id":"gives-none","text":{"en":"Gives back None when it finishes"}}]}'::jsonb, '{"en":"Only `return` passes a value on for the rest of the program to use. `print` is for the person reading the screen.\n"}'::jsonb, null, null, false, true, true, array['functions', 'return']::text[], 4, 'draft'::public.review_status, 'ffcb2668513d924801e202a976f5d902'),
  ('2adb0700-645c-4b62-a616-710f168637ac', '812a8031-d53b-4ae0-bc13-517856c5c4ab', 'predict_output'::public.question_type, 'medium'::public.difficulty_level, '{"en":"What does this print?"}'::jsonb, 'def sign(n):
