  ('99ef81cb-f07f-4fe6-864b-1fb36f3dccac', '812a8031-d53b-4ae0-bc13-517856c5c4ab', 'debugging'::public.question_type, 'hard'::public.difficulty_level, '{"en":"This prints 5 and then crashes instead of printing 6. How do you fix it?"}'::jsonb, 'def total(prices):
