  ('d4330159-d1bd-469f-a2f0-0fc9e9f19350', 'd7ee5965-25be-4a57-bb15-7bf92ec6b0ef', 'predict_output'::public.question_type, 'easy'::public.difficulty_level, '{"en":"What does this print?"}'::jsonb, 'def power(n, exp=2):
