  ('2ec5c6b3-fe02-440d-890e-31cd8999fd7c', 'd7ee5965-25be-4a57-bb15-7bf92ec6b0ef', 'true_false'::public.question_type, 'easy'::public.difficulty_level, '{"en":"An argument whose parameter has a default value can be left out of the call."}'::jsonb, null, '{}'::jsonb, '{"en":"That is what the default is for. Arguments without a default must always be given.\n"}'::jsonb, null, null, false, true, true, array['functions', 'parameters']::text[], 2, 'draft'::public.review_status, 'f2056974de99544a78041cee02e5f5ce'),
  ('70805913-d33a-4b39-a439-dd29a8132d4a', 'd7ee5965-25be-4a57-bb15-7bf92ec6b0ef', 'predict_output'::public.question_type, 'medium'::public.difficulty_level, '{"en":"What does this print?"}'::jsonb, 'def power(n, exp=2):
