  ('6da6aca2-41d2-4d4a-8159-123e4ed12c00', 'd7ee5965-25be-4a57-bb15-7bf92ec6b0ef', 'multiple_choice'::public.question_type, 'medium'::public.difficulty_level, '{"en":"For `def order(item, qty=1):`, which call is valid?"}'::jsonb, null, '{"options":[{"id":"valid","text":{"en":"order(\"tea\", qty=2)"}},{"id":"missing","text":{"en":"order(qty=2)"}},{"id":"out-of-order","text":{"en":"order(item=\"tea\", 2)"}},{"id":"empty","text":{"en":"order()"}}]}'::jsonb, '{"en":"`item` has no default, so it must always be supplied — ruling out the second and fourth. The third puts a plain argument after a named one, which Python refuses to run.\n"}'::jsonb, null, null, false, true, true, array['functions', 'parameters']::text[], 4, 'draft'::public.review_status, 'bae3fd957a097802ce52eded95d97d6c'),
  ('2c9184b3-009c-4cae-93cf-f8985cb4bd43', 'd7ee5965-25be-4a57-bb15-7bf92ec6b0ef', 'predict_output'::public.question_type, 'hard'::public.difficulty_level, '{"en":"What does this print?"}'::jsonb, 'def label(text, left="[", right="]"):
