  ('656c1077-f4b0-419b-9940-a215ee93a31b', '581ae866-7516-4166-914e-1d96dc07fa6b', 'true_false'::public.question_type, 'easy'::public.difficulty_level, '{"en":"A variable created inside a function can still be used after the function finishes."}'::jsonb, null, '{}'::jsonb, '{"en":"Local variables vanish when the function ends. To keep a value, return it.\n"}'::jsonb, null, null, false, true, true, array['functions', 'scope']::text[], 1, 'draft'::public.review_status, '20411ac0f1c40a29ece77ce8383f6cd7'),
  ('c5636918-ec9c-4b3b-b958-194c731a3edb', '581ae866-7516-4166-914e-1d96dc07fa6b', 'multiple_choice'::public.question_type, 'easy'::public.difficulty_level, '{"en":"What is the clearest way to get a result out of a function?"}'::jsonb, null, '{"options":[{"id":"return","text":{"en":"Return it"}},{"id":"global","text":{"en":"Change a global variable"}},{"id":"print","text":{"en":"Print it"}},{"id":"rename","text":{"en":"Give the local variable the same name as an outside one"}}]}'::jsonb, '{"en":"`return` makes the result the value of the call, so the caller decides what to do with it. Printing keeps nothing, and a same-named local does not reach outside.\n"}'::jsonb, null, null, false, true, true, array['functions', 'scope', 'return']::text[], 2, 'draft'::public.review_status, '417635ed7b6189612990133d6aab9d3d'),
  ('d3792168-03cb-4d20-aaf6-044cf785fd4b', '581ae866-7516-4166-914e-1d96dc07fa6b', 'predict_output'::public.question_type, 'medium'::public.difficulty_level, '{"en":"What does this print?"}'::jsonb, 'x = 5

