  ('09c07e0b-f03c-4824-952f-bbdc7ecc11ce', '581ae866-7516-4166-914e-1d96dc07fa6b', 'debugging'::public.question_type, 'medium'::public.difficulty_level, '{"en":"This stops with a NameError instead of printing 12. How do you fix it?"}'::jsonb, 'def area(w, h):
