  ('02e40778-0056-42ed-bf57-d1ee9d904841', '15bfa7f2-5148-4a07-a77a-715843c0f20a', 'multiple_choice'::public.question_type, 'easy'::public.difficulty_level, '{"en":"Which of these creates a tuple?"}'::jsonb, null, '{"options":[{"id":"round","text":{"en":"(1, 2)"}},{"id":"square","text":{"en":"[1, 2]"}},{"id":"curly","text":{"en":"{1, 2}"}},{"id":"text","text":{"en":"\"1, 2\""}}]}'::jsonb, '{"en":"Round brackets with a comma make a tuple. Square brackets make a list, curly braces make a set, and the quoted version is a string.\n"}'::jsonb, null, null, false, true, true, array['tuples']::text[], 1, 'draft'::public.review_status, 'c71b9b28470a6c0673265b3232c3550f'),
  ('b7a5eb75-06f8-4eb8-a3e0-83544f89812c', '15bfa7f2-5148-4a07-a77a-715843c0f20a', 'true_false'::public.question_type, 'easy'::public.difficulty_level, '{"en":"You can change an item of a tuple after creating it."}'::jsonb, null, '{}'::jsonb, '{"en":"Tuples are **immutable**. To \"change\" one you build a new tuple and assign it to the name.\n"}'::jsonb, null, null, false, true, true, array['tuples']::text[], 2, 'draft'::public.review_status, 'b13db86fd6f662aa1243536db7d63601'),
