  ('fd168007-e40b-4d76-b29b-5a4fc8054e9c', '15bfa7f2-5148-4a07-a77a-715843c0f20a', 'predict_output'::public.question_type, 'medium'::public.difficulty_level, '{"en":"What does this print?"}'::jsonb, 'print((1, 2) + (3,))
