  ('1f13623d-4195-4104-9918-6afde3374279', 'a2f08dae-1e33-412d-9ac9-0ebd9ea3266b', 'true_false'::public.question_type, 'easy'::public.difficulty_level, '{"en":"`a, b = b, a` swaps the values of `a` and `b`."}'::jsonb, null, '{}'::jsonb, '{"en":"The right side is built first as the tuple `(b, a)`, using the old values. Only then is it unpacked into `a` and `b`.\n"}'::jsonb, null, null, false, true, true, array['unpacking']::text[], 2, 'draft'::public.review_status, '939aaf0c92c69c7d60f6a02b3c1354ac'),
