  ('67ed400e-3e29-4c5d-81a4-e06dcbac67fb', 'ab1753c6-d426-4e26-bc24-af2259924d57', 'true_false'::public.question_type, 'easy'::public.difficulty_level, '{"en":"A set can contain the same value twice."}'::jsonb, null, '{}'::jsonb, '{"en":"That is the defining rule of a set. Adding a value that is already there changes nothing.\n"}'::jsonb, null, null, false, true, true, array['sets']::text[], 1, 'draft'::public.review_status, '8b8322bfc8348fd68cb25e6700bcc12f'),
