  ('c3cd2823-8169-419e-9f14-9fe98133150d', 'ab1753c6-d426-4e26-bc24-af2259924d57', 'multiple_select'::public.question_type, 'medium'::public.difficulty_level, '{"en":"Which of these are true of sets?"}'::jsonb, null, '{"options":[{"id":"dedupe","text":{"en":"Duplicates are removed automatically"}},{"id":"ordered","text":{"en":"Items stay in the order you added them"}},{"id":"membership","text":{"en":"You can check membership with in"}},{"id":"index","text":{"en":"You can get the first item with s[0]"}},{"id":"add","text":{"en":"add() puts a new item in"}}]}'::jsonb, '{"en":"Sets drop duplicates, support `in`, and grow with `add`. They make no promise about order, which is also why they cannot be indexed.\n"}'::jsonb, null, null, false, true, true, array['sets']::text[], 5, 'draft'::public.review_status, '4bf74b927350f0d7fadfc7ee28033b46'),
