  ('3ee0ecbd-c02d-4f6f-9625-273639d9d6bb', '5d8046f6-19c2-4eba-80c7-175d05b38e6e', 'concept_matching'::public.question_type, 'easy'::public.difficulty_level, '{"en":"Match each operation to what it keeps."}'::jsonb, null, '{"concepts":[{"id":"union","text":{"en":"a | b"}},{"id":"intersection","text":{"en":"a & b"}},{"id":"difference","text":{"en":"a - b"}}],"definitions":[{"id":"either","text":{"en":"Everything in either set"}},{"id":"both","text":{"en":"Only what is in both sets"}},{"id":"first-only","text":{"en":"What is in a but not in b"}}]}'::jsonb, '{"en":"Union joins, intersection keeps the overlap, and difference takes away what the second set has.\n"}'::jsonb, null, null, false, true, true, array['sets']::text[], 1, 'draft'::public.review_status, 'bfbd9338706b33dad5c4f6110699c807'),
  ('46141c3f-3006-4fb1-9ce7-f30866142419', '5d8046f6-19c2-4eba-80c7-175d05b38e6e', 'predict_output'::public.question_type, 'easy'::public.difficulty_level, '{"en":"What does this print?"}'::jsonb, 'print(sorted({1, 2} | {2, 3}))
