  ('97683c03-50ed-42c9-82dc-f88b9aee978c', '5d8046f6-19c2-4eba-80c7-175d05b38e6e', 'true_false'::public.question_type, 'medium'::public.difficulty_level, '{"en":"`{1, 2, 3} - {3, 4}` gives the same set as `{3, 4} - {1, 2, 3}`."}'::jsonb, null, '{}'::jsonb, '{"en":"The first is `{1, 2}` — what the first set has that the second lacks. The second is `{4}`. Difference depends on which set comes first.\n"}'::jsonb, null, null, false, true, true, array['sets']::text[], 4, 'draft'::public.review_status, 'b1400013e96bbc7c76ea6a2871bd3f34'),
