    print("missing")
', '{"input":"text"}'::jsonb, '{"en":"\"c\" is found at index 0 — and 0 counts as False, so the `else` runs. This is exactly why `find` should not be used as a yes-or-no test. `if \"c\" in s:` says what is meant.\n"}'::jsonb, '{"en":"What index does `find` return, and how does an `if` treat it?"}'::jsonb, null, false, true, true, array['strings', 'string-methods', 'conditions']::text[], 6, 'draft'::public.review_status, '31e4b80b6e678f2a9e43be59e5907e8c'),
  ('a5e40663-80d5-4ec2-8abb-20c0d7856a26', '8f9da6d6-047e-4eea-ad58-29190027b0f0', 'predict_output'::public.question_type, 'easy'::public.difficulty_level, '{"en":"What does this print?"}'::jsonb, 'print([x + 1 for x in [1, 2, 3]])
', '{"input":"choice","options":[{"id":"right","text":{"en":"[2, 3, 4]"}},{"id":"unchanged","text":{"en":"[1, 2, 3]"}},{"id":"sum","text":{"en":"9"}},{"id":"doubled","text":{"en":"[2, 4, 6]"}}]}'::jsonb, '{"en":"The expression `x + 1` is worked out for each item, and the results are collected into a new list.\n"}'::jsonb, null, null, false, true, true, array['comprehensions', 'lists']::text[], 1, 'draft'::public.review_status, 'e221ce99ed3e2cde1ed418611797c3ce'),
  ('c7cd8338-58b5-4881-a5ec-f707e32faa50', '8f9da6d6-047e-4eea-ad58-29190027b0f0', 'true_false'::public.question_type, 'easy'::public.difficulty_level, '{"en":"A list comprehension always produces a list."}'::jsonb, null, '{}'::jsonb, '{"en":"The square brackets say so. Whatever the source was — a string, a range — the result is a list.\n"}'::jsonb, null, null, false, true, true, array['comprehensions']::text[], 2, 'draft'::public.review_status, 'c22bff515bc07fcd0850fc73d8c0cd94'),
  ('0cc6589e-e778-44db-a768-f9e425328287', '8f9da6d6-047e-4eea-ad58-29190027b0f0', 'predict_output'::public.question_type, 'medium'::public.difficulty_level, '{"en":"What does this print?"}'::jsonb, 'print([len(w) for w in ["a", "bb", "ccc"]])
', '{"input":"choice","options":[{"id":"lengths","text":{"en":"[1, 2, 3]"}},{"id":"words","text":{"en":"[''a'', ''bb'', ''ccc'']"}},{"id":"total","text":{"en":"6"}},{"id":"count","text":{"en":"3"}}]}'::jsonb, '{"en":"Each word is replaced by its length, so the new list holds three numbers.\n"}'::jsonb, null, null, false, true, true, array['comprehensions', 'lists']::text[], 3, 'draft'::public.review_status, '1b7eb57eb91e8647b1da2541c01c2331'),
  ('6e4ba95a-f697-4aaf-9769-e618c5ae3186', '8f9da6d6-047e-4eea-ad58-29190027b0f0', 'fill_blank'::public.question_type, 'medium'::public.difficulty_level, '{"en":"Complete the comprehension so it builds `[0, 1, 4, 9]`."}'::jsonb, 'squares = [n ___ 2 for n in range(4)]
', '{"input":"tokens","tokens":["**","*","+","//"]}'::jsonb, '{"en":"Squaring is `n ** 2`. `n * 2` would double instead, giving [0, 2, 4, 6].\n"}'::jsonb, null, null, false, true, true, array['comprehensions', 'arithmetic']::text[], 4, 'draft'::public.review_status, '9f9f65830515829df7569f414b2d90a6'),
  ('bb8b2d2a-4e36-4a07-ab91-155aac401772', '8f9da6d6-047e-4eea-ad58-29190027b0f0', 'multiple_choice'::public.question_type, 'medium'::public.difficulty_level, '{"en":"Which of these gives `[''A'', ''B'']`?"}'::jsonb, null, '{"options":[{"id":"right","text":{"en":"[c.upper() for c in \"ab\"]"}},{"id":"lowered","text":{"en":"[c for c in \"AB\".lower()]"}},{"id":"whole","text":{"en":"[\"ab\".upper()]"}},{"id":"function","text":{"en":"[upper(c) for c in \"ab\"]"}}]}'::jsonb, '{"en":"Looping over \"ab\" gives each letter, and `upper()` capitalises it. The third gives a one-item list [''AB''], and `upper` is a method, not a free function.\n"}'::jsonb, null, null, false, true, true, array['comprehensions', 'string-methods']::text[], 5, 'draft'::public.review_status, '2fe0d9062b5bccbbefac83334e1ef3ae'),
  ('a32c7c2e-d9a7-4931-b27e-45e3093c59ca', '8f9da6d6-047e-4eea-ad58-29190027b0f0', 'predict_output'::public.question_type, 'hard'::public.difficulty_level, '{"en":"What does this print?"}'::jsonb, 'print("-".join([str(n * 10) for n in range(3)]))
', '{"input":"text"}'::jsonb, '{"en":"The comprehension builds [''0'', ''10'', ''20''] — strings, thanks to `str` — and `join` glues them with dashes.\n"}'::jsonb, '{"en":"Work out the list first, then the join."}'::jsonb, null, false, true, true, array['comprehensions', 'string-methods']::text[], 6, 'draft'::public.review_status, 'c3b0e6f30ae19db0a419ff36484756f8'),
  ('7a5e66c3-f24c-4685-b77c-9fa9134b9279', 'ba36487d-d2ec-4a8e-a81d-110733d61728', 'predict_output'::public.question_type, 'easy'::public.difficulty_level, '{"en":"What does this print?"}'::jsonb, 'print([n for n in [3, 8, 1, 9] if n > 5])
', '{"input":"choice","options":[{"id":"kept","text":{"en":"[8, 9]"}},{"id":"dropped","text":{"en":"[3, 1]"}},{"id":"booleans","text":{"en":"[False, True, False, True]"}},{"id":"all","text":{"en":"[3, 8, 1, 9]"}}]}'::jsonb, '{"en":"Only the numbers greater than 5 pass the condition, and they keep their original order.\n"}'::jsonb, null, null, false, true, true, array['comprehensions', 'conditions']::text[], 1, 'draft'::public.review_status, '0ea972f3bf5f676f041458f32c7e3761'),
  ('2440dc6c-f750-4df2-99d3-22179b0b0a11', 'ba36487d-d2ec-4a8e-a81d-110733d61728', 'true_false'::public.question_type, 'easy'::public.difficulty_level, '{"en":"In `[x for x in items if x > 0]`, items that fail the condition are left out."}'::jsonb, null, '{}'::jsonb, '{"en":"The condition decides whether each item makes it into the new list. Failing items are skipped, not replaced.\n"}'::jsonb, null, null, false, true, true, array['comprehensions']::text[], 2, 'draft'::public.review_status, '2cdb1a1ca726e10aee5914880d137e1f'),
  ('28ea0cb6-6965-495f-8908-16b585366abb', 'ba36487d-d2ec-4a8e-a81d-110733d61728', 'predict_output'::public.question_type, 'medium'::public.difficulty_level, '{"en":"What does this print?"}'::jsonb, 'print({n: n * n for n in range(3)})
', '{"input":"choice","options":[{"id":"dict","text":{"en":"{0: 0, 1: 1, 2: 4}"}},{"id":"list","text":{"en":"[0, 1, 4]"}},{"id":"keys","text":{"en":"{0, 1, 2}"}},{"id":"shifted","text":{"en":"{1: 1, 2: 4, 3: 9}"}}]}'::jsonb, '{"en":"Each number from `range(3)` becomes a key, with its square as the value.\n"}'::jsonb, null, null, false, true, true, array['comprehensions', 'dictionaries']::text[], 3, 'draft'::public.review_status, '7533ed8aba3ee841c603a8753ff61b15'),
  ('72b4d213-107e-4e55-97e5-f640ba0428b3', 'ba36487d-d2ec-4a8e-a81d-110733d61728', 'predict_output'::public.question_type, 'medium'::public.difficulty_level, '{"en":"What does this print?"}'::jsonb, 'print(len([c for c in "banana" if c == "a"]))
', '{"input":"text"}'::jsonb, '{"en":"The comprehension keeps only the three a''s, and `len` counts them — a longer way of writing `\"banana\".count(\"a\")`.\n"}'::jsonb, null, null, false, true, true, array['comprehensions', 'strings']::text[], 4, 'draft'::public.review_status, '829ddc0bdc78ca2d950ff7c834c75ee0'),
  ('3ac4a194-a5cc-418f-b3e2-66c8b7b6cbfe', 'ba36487d-d2ec-4a8e-a81d-110733d61728', 'multiple_choice'::public.question_type, 'medium'::public.difficulty_level, '{"en":"Which line keeps only the non-empty strings from `names`?"}'::jsonb, null, '{"options":[{"id":"right","text":{"en":"[n for n in names if n]"}},{"id":"early-if","text":{"en":"[n if n for n in names]"}},{"id":"empties","text":{"en":"[n for n in names if n == \"\"]"}},{"id":"statement","text":{"en":"[if n: n for n in names]"}}]}'::jsonb, '{"en":"An empty string counts as False, so `if n` keeps exactly the non-empty ones. The filter has to come at the end; the other two positions are not valid Python, and the third keeps only the empty strings.\n"}'::jsonb, null, null, false, true, true, array['comprehensions', 'booleans']::text[], 5, 'draft'::public.review_status, '742c834c2aba93a5a1d80676c69e395f'),
  ('50d2a84e-f084-47d1-8bb6-c79589496698', 'ba36487d-d2ec-4a8e-a81d-110733d61728', 'predict_output'::public.question_type, 'hard'::public.difficulty_level, '{"en":"What does this print?"}'::jsonb, 'words = ["Sun", "moon", "Star"]
print([w.lower() for w in words if w[0].isupper()])
', '{"input":"choice","options":[{"id":"right","text":{"en":"[''sun'', ''star'']"}},{"id":"unfiltered","text":{"en":"[''sun'', ''moon'', ''star'']"}},{"id":"original-case","text":{"en":"[''Sun'', ''Star'']"}},{"id":"wrong-one","text":{"en":"[''moon'']"}}]}'::jsonb, '{"en":"`isupper()` asks whether the first letter is a capital. \"Sun\" and \"Star\" pass, \"moon\" does not. The survivors are then lowered — the check happens before the change.\n"}'::jsonb, '{"en":"Filter first, then transform."}'::jsonb, null, false, true, true, array['comprehensions', 'string-methods']::text[], 6, 'draft'::public.review_status, '25b86b185294849b287f825d23aa15d3'),
  ('4d4e8b91-884b-45b4-95d5-40af41d120a5', '07725667-26a9-4d8b-87c0-53cf36f9d823', 'multiple_choice'::public.question_type, 'easy'::public.difficulty_level, '{"en":"Which exception does `int(\"abc\")` raise?"}'::jsonb, null, '{"options":[{"id":"value","text":{"en":"ValueError"}},{"id":"type","text":{"en":"TypeError"}},{"id":"name","text":{"en":"NameError"}},{"id":"key","text":{"en":"KeyError"}}]}'::jsonb, '{"en":"`int` is happy to receive a string — that is the right type — but \"abc\" is not a value it can turn into a number.\n"}'::jsonb, null, null, false, true, true, array['exceptions']::text[], 1, 'draft'::public.review_status, 'afa38318c321f9c9966fa7bd4b1ecb17'),
  ('7341b873-f452-482d-9f0a-8553f8ef7400', '07725667-26a9-4d8b-87c0-53cf36f9d823', 'true_false'::public.question_type, 'easy'::public.difficulty_level, '{"en":"An exception that nothing handles stops the program."}'::jsonb, null, '{}'::jsonb, '{"en":"The program ends at the line that raised it, and every line after it is skipped. The next lesson shows how to handle one and carry on.\n"}'::jsonb, null, null, false, true, true, array['exceptions']::text[], 2, 'draft'::public.review_status, '184c4c7f77f9d75914ca732bfe046fc1'),
  ('d76b9fc6-bd77-44a8-806c-e5105670d97b', '07725667-26a9-4d8b-87c0-53cf36f9d823', 'concept_matching'::public.question_type, 'medium'::public.difficulty_level, '{"en":"Match each line to the exception it raises."}'::jsonb, null, '{"concepts":[{"id":"key","text":{"en":"{\"a\": 1}[\"b\"]"}},{"id":"index","text":{"en":"[1, 2][5]"}},{"id":"zero","text":{"en":"10 / 0"}},{"id":"type","text":{"en":"\"a\" + 1"}}],"definitions":[{"id":"key-error","text":{"en":"KeyError"}},{"id":"index-error","text":{"en":"IndexError"}},{"id":"zero-error","text":{"en":"ZeroDivisionError"}},{"id":"type-error","text":{"en":"TypeError"}}]}'::jsonb, '{"en":"A missing key, a position past the end, a division by zero, and text joined to a number — each gets its own, precisely named, exception.\n"}'::jsonb, null, null, false, true, true, array['exceptions']::text[], 3, 'draft'::public.review_status, '2eede46052c46ba85de9f3e9d465f6a9'),
  ('76eb667e-3d72-470c-b581-a493ecddaf79', '07725667-26a9-4d8b-87c0-53cf36f9d823', 'multiple_choice'::public.question_type, 'medium'::public.difficulty_level, '{"en":"What happens when Python runs `\"5\" + 5`?"}'::jsonb, null, '{"options":[{"id":"type-error","text":{"en":"A TypeError"}},{"id":"value-error","text":{"en":"A ValueError"}},{"id":"syntax","text":{"en":"A SyntaxError"}},{"id":"joined","text":{"en":"Nothing goes wrong — it gives \"55\""}}]}'::jsonb, '{"en":"Text and a number are different types, and `+` does not know whether to join or add. The code is perfectly valid Python, so it is not a SyntaxError — it fails only when it runs.\n"}'::jsonb, null, null, false, true, true, array['exceptions', 'data-types']::text[], 4, 'draft'::public.review_status, '81adc0a45f55dbd9597528dbd462006a'),
  ('9562393e-68e5-481c-b8cf-034a9f8795cf', '07725667-26a9-4d8b-87c0-53cf36f9d823', 'multiple_select'::public.question_type, 'medium'::public.difficulty_level, '{"en":"Which of these raise an exception?"}'::jsonb, null, '{"options":[{"id":"float-text","text":{"en":"int(\"3.0\")"}},{"id":"float","text":{"en":"int(3.9)"}},{"id":"past-end","text":{"en":"[1, 2][2]"}},{"id":"get","text":{"en":"{\"a\": 1}.get(\"b\")"}},{"id":"zero","text":{"en":"1 / 0"}}]}'::jsonb, '{"en":"`int` will not read a decimal point inside text, index 2 is past the end of a two-item list, and dividing by zero is never allowed. `int(3.9)` simply gives 3, and `get` returns None for a missing key instead of raising.\n"}'::jsonb, '{"en":"Two of these quietly give back a value."}'::jsonb, null, false, true, true, array['exceptions']::text[], 5, 'draft'::public.review_status, '2aa981ef905d8d259e17df7a671defb1'),
  ('5029fba1-05d1-4d7a-bc7b-d4169438e182', '07725667-26a9-4d8b-87c0-53cf36f9d823', 'multiple_choice'::public.question_type, 'hard'::public.difficulty_level, '{"en":"A program stops with \"IndexError: list index out of range\". Which line could have caused it?"}'::jsonb, null, '{"options":[{"id":"length","text":{"en":"items[len(items)]"}},{"id":"append","text":{"en":"items.append(5)"}},{"id":"len","text":{"en":"len(items)"}},{"id":"last","text":{"en":"items[-1], on a list with three items"}}]}'::jsonb, '{"en":"The last valid index is always one less than the length, so `items[len(items)]` is always one step too far. Appending and measuring never index at all, and `-1` is fine on any non-empty list.\n"}'::jsonb, '{"en":"What is the highest valid index for a list of length n?"}'::jsonb, null, false, true, true, array['exceptions', 'lists', 'indexing']::text[], 6, 'draft'::public.review_status, 'd0f55d90386a7358deeb5a5f1510ec14'),
  ('95690bd6-0107-44e6-8e1d-108ef14dc137', '5eb1acb5-fffc-424f-bd33-78f57e71fb5c', 'predict_output'::public.question_type, 'easy'::public.difficulty_level, '{"en":"What does this print?"}'::jsonb, 'try:
    print(1 / 0)
except ZeroDivisionError:
    print("oops")
', '{"input":"text"}'::jsonb, '{"en":"Dividing by zero raises a ZeroDivisionError before anything is printed, and the `except` block catches it.\n"}'::jsonb, null, null, false, true, true, array['exceptions']::text[], 1, 'draft'::public.review_status, '730454437ffbf64a4f216129a5ea76de'),
  ('acb5f9f0-53e9-4c1c-9b38-7a64e4fd8fc2', '5eb1acb5-fffc-424f-bd33-78f57e71fb5c', 'true_false'::public.question_type, 'easy'::public.difficulty_level, '{"en":"If the `try` block runs without any error, the `except` block is skipped."}'::jsonb, null, '{}'::jsonb, '{"en":"`except` only runs when a matching exception actually happens.\n"}'::jsonb, null, null, false, true, true, array['exceptions']::text[], 2, 'draft'::public.review_status, 'de7126e0f7bb1df3534b87463f388d86'),
  ('8738addb-c60a-422d-888b-63745d11e63c', '5eb1acb5-fffc-424f-bd33-78f57e71fb5c', 'predict_output'::public.question_type, 'medium'::public.difficulty_level, '{"en":"What does this print?"}'::jsonb, 'try:
    x = int("7")
    print(x * 2)
except ValueError:
    print("bad")
print("end")
', '{"input":"choice","options":[{"id":"success","text":{"en":"14\nend"}},{"id":"failed","text":{"en":"bad\nend"}},{"id":"both","text":{"en":"14\nbad\nend"}},{"id":"only-end","text":{"en":"end"}}]}'::jsonb, '{"en":"\"7\" converts fine, so the whole `try` block runs and the `except` is skipped. The last line always runs.\n"}'::jsonb, null, null, false, true, true, array['exceptions']::text[], 3, 'draft'::public.review_status, '3a663c92397a20981d9f23f2cead5d38'),
  ('bc6ed8df-980f-41bc-bbe5-9d677624734c', '5eb1acb5-fffc-424f-bd33-78f57e71fb5c', 'predict_output'::public.question_type, 'medium'::public.difficulty_level, '{"en":"What does this print?"}'::jsonb, 'try:
    print("a")
    n = int("x")
    print("b")
except ValueError:
    print("c")
', '{"input":"choice","options":[{"id":"jumps","text":{"en":"a\nc"}},{"id":"all","text":{"en":"a\nb\nc"}},{"id":"only-c","text":{"en":"c"}},{"id":"a-b","text":{"en":"a\nb"}}]}'::jsonb, '{"en":"\"a\" prints before anything goes wrong. The failing line jumps straight to `except`, so the rest of the `try` block — the \"b\" — never runs.\n"}'::jsonb, '{"en":"What happens to the lines after the one that fails?"}'::jsonb, null, false, true, true, array['exceptions']::text[], 4, 'draft'::public.review_status, 'af68da463ec314745982a7912623dcc0'),
  ('c26ad780-73fb-45e7-8f1f-5f6346e6cd00', '5eb1acb5-fffc-424f-bd33-78f57e71fb5c', 'fill_blank'::public.question_type, 'medium'::public.difficulty_level, '{"en":"Complete the handler so a count of 0 gives a total of 0 instead of crashing."}'::jsonb, 'try:
    total = 10 / count
except ___:
    total = 0
', '{"input":"tokens","tokens":["ZeroDivisionError","ValueError","KeyError","IndexError"]}'::jsonb, '{"en":"Dividing by a count of 0 raises a ZeroDivisionError, so that is the type to catch. Catching any other type would let this one through.\n"}'::jsonb, null, null, false, true, true, array['exceptions']::text[], 5, 'draft'::public.review_status, '8056062c02bfa4e0597ed2731852f1c9'),
  ('5e7a2cfc-f037-4254-8d6b-7e94fbbd64db', '5eb1acb5-fffc-424f-bd33-78f57e71fb5c', 'debugging'::public.question_type, 'hard'::public.difficulty_level, '{"en":"This should print \"missing\", but it crashes anyway. How do you fix it?"}'::jsonb, 'items = ["a", "b"]
try:
    print(items[5])
except KeyError:
    print("missing")
', '{"mode":"choose_fix","options":[{"id":"index-error","text":{"en":"Catch IndexError instead of KeyError"}},{"id":"value-error","text":{"en":"Catch ValueError instead of KeyError"}},{"id":"nested","text":{"en":"Wrap the whole thing in a second try"}},{"id":"get","text":{"en":"Use items.get(5) instead of items[5]"}}]}'::jsonb, '{"en":"A position past the end of a **list** raises an IndexError. KeyError is for dictionaries, so the handler never matches and the exception escapes. Lists have no `get` method.\n"}'::jsonb, '{"en":"Is `items` a list or a dictionary?"}'::jsonb, null, false, true, true, array['exceptions', 'debugging']::text[], 6, 'draft'::public.review_status, 'eaa0b5ed35c0d6ce6e8fa35e70288d00'),
  ('0f426b80-e1a3-45f2-99a8-e64e2665d5da', '5ed29179-105c-4b68-b7e1-04ea86b59479', 'multiple_choice'::public.question_type, 'easy'::public.difficulty_level, '{"en":"When does the `else` block of a `try` run?"}'::jsonb, null, '{"options":[{"id":"no-error","text":{"en":"When the try block raised no exception"}},{"id":"error","text":{"en":"When an exception happened"}},{"id":"always","text":{"en":"Always, after the try block"}},{"id":"never","text":{"en":"Only when finally is missing"}}]}'::jsonb, '{"en":"`else` is the success path. `except` handles failure, and `finally` runs in every case.\n"}'::jsonb, null, null, false, true, true, array['exceptions']::text[], 1, 'draft'::public.review_status, '6bd22425a7752b319a3b269f73ac5c84'),
  ('8266f32a-5dc0-4341-928b-76f40f9c64ee', '5ed29179-105c-4b68-b7e1-04ea86b59479', 'true_false'::public.question_type, 'easy'::public.difficulty_level, '{"en":"`finally` still runs when an exception was caught by `except`."}'::jsonb, null, '{}'::jsonb, '{"en":"`finally` runs in every case — that is its whole purpose.\n"}'::jsonb, null, null, false, true, true, array['exceptions']::text[], 2, 'draft'::public.review_status, '2a78c394a55d5b50f8dc7ea913b84798'),
  ('a007461d-fcd4-46d0-b343-d16950b3b201', '5ed29179-105c-4b68-b7e1-04ea86b59479', 'predict_output'::public.question_type, 'medium'::public.difficulty_level, '{"en":"What does this print?"}'::jsonb, 'try:
    n = int("x")
except ValueError:
    print("A")
else:
    print("B")
finally:
    print("C")
', '{"input":"choice","options":[{"id":"failed","text":{"en":"A\nC"}},{"id":"succeeded","text":{"en":"B\nC"}},{"id":"all","text":{"en":"A\nB\nC"}},{"id":"only-a","text":{"en":"A"}}]}'::jsonb, '{"en":"The conversion fails, so `except` runs and `else` does not. `finally` runs either way.\n"}'::jsonb, null, null, false, true, true, array['exceptions']::text[], 3, 'draft'::public.review_status, '36d454baa21e63c5ae8baef07dd46a53'),
  ('4b6b2cb7-f022-49b2-a7bd-ed203e755cfa', '5ed29179-105c-4b68-b7e1-04ea86b59479', 'predict_output'::public.question_type, 'medium'::public.difficulty_level, '{"en":"What does this print?"}'::jsonb, 'try:
    n = int("4")
except ValueError:
    print("A")
else:
    print("B")
finally:
