  ('5191e30e-d6d4-425c-9b6c-f209366f52cc', 'ef7e193a-d1e2-4f37-9b65-bc9c25e97f69', 'multiple_choice'::public.question_type, 'easy'::public.difficulty_level, '{"en":"What is an object?"}'::jsonb, null, '{"options":[{"id":"instance","text":{"en":"One particular thing built from a class"}},{"id":"blueprint","text":{"en":"The blueprint that describes a kind of thing"}},{"id":"function","text":{"en":"A function that belongs to a module"}},{"id":"module","text":{"en":"A file of Python code"}}]}'::jsonb, '{"en":"The class is the blueprint; each object is one thing made from it. A single class can produce any number of objects.\n"}'::jsonb, null, null, false, true, true, array['oop']::text[], 1, 'draft'::public.review_status, '9491cb62b5d6812bef51558c9810905d'),
  ('e4e86d2b-571b-42a5-942d-4edfa00265c8', 'ef7e193a-d1e2-4f37-9b65-bc9c25e97f69', 'true_false'::public.question_type, 'easy'::public.difficulty_level, '{"en":"Two objects made from the same class are the same object."}'::jsonb, null, '{}'::jsonb, '{"en":"Each call to the class builds a brand-new object. They share a blueprint, not an identity.\n"}'::jsonb, null, null, false, true, true, array['oop']::text[], 2, 'draft'::public.review_status, 'adc2a4e884eb216037265b72c69fa292'),
