  ('7a215518-1a69-44d9-b734-a42b160f7a0b', 'ef7e193a-d1e2-4f37-9b65-bc9c25e97f69', 'multiple_choice'::public.question_type, 'medium'::public.difficulty_level, '{"en":"Which line creates a new object from a class called `Car`?"}'::jsonb, null, '{"options":[{"id":"call","text":{"en":"my_car = Car()"}},{"id":"no-brackets","text":{"en":"my_car = Car"}},{"id":"new","text":{"en":"my_car = new Car()"}},{"id":"class","text":{"en":"class my_car(Car)"}}]}'::jsonb, '{"en":"Calling the class, with brackets, builds an object. Without brackets you only get the class itself, and Python has no `new` keyword.\n"}'::jsonb, null, null, false, true, true, array['oop']::text[], 4, 'draft'::public.review_status, 'ea56c60ab872556d4f226d103745f8c8'),
