  ('e7f83003-447d-498a-91c8-edd153c5900e', '659f290a-3e00-4b81-9972-4e598d2b42dc', 'true_false'::public.question_type, 'easy'::public.difficulty_level, '{"en":"`__init__` runs automatically when an object is created."}'::jsonb, null, '{}'::jsonb, '{"en":"You never call it by name. `Dog(\"Rex\")` builds the object and runs `__init__` on it straight away.\n"}'::jsonb, null, null, false, true, true, array['oop']::text[], 1, 'draft'::public.review_status, 'd9651647d04ef97cfea9af0c47aaa365'),
  ('9b29f805-37fc-4213-a04a-93c2305493e2', '659f290a-3e00-4b81-9972-4e598d2b42dc', 'predict_output'::public.question_type, 'easy'::public.difficulty_level, '{"en":"What does this print?"}'::jsonb, 'class Book:
