  ('940e37d7-3289-46db-aada-2d07d7ad960a', '659f290a-3e00-4b81-9972-4e598d2b42dc', 'multiple_choice'::public.question_type, 'medium'::public.difficulty_level, '{"en":"In `def __init__(self, name):`, what is `self`?"}'::jsonb, null, '{"options":[{"id":"object","text":{"en":"The object being created"}},{"id":"class","text":{"en":"The class itself"}},{"id":"first-arg","text":{"en":"The first argument you pass when calling"}},{"id":"keyword","text":{"en":"A word you have to type when creating the object"}}]}'::jsonb, '{"en":"`self` is the particular object being set up. Python fills it in automatically, so your first argument goes to `name`.\n"}'::jsonb, null, null, false, true, true, array['oop']::text[], 3, 'draft'::public.review_status, '322dc5e70ab3787420848946fa33dcab'),
  ('6e782a0c-f07d-4384-82c8-0a1f916a8183', '659f290a-3e00-4b81-9972-4e598d2b42dc', 'fill_blank'::public.question_type, 'medium'::public.difficulty_level, '{"en":"Complete the line so every cat keeps its name."}'::jsonb, 'class Cat:
