  ('0c7ed0dd-091b-4270-bd9a-0425af8c2afc', '659f290a-3e00-4b81-9972-4e598d2b42dc', 'predict_output'::public.question_type, 'medium'::public.difficulty_level, '{"en":"What does this print?"}'::jsonb, 'class Counter:
