  ('d58dd52d-24c2-4136-8096-457ddb912b1f', '659f290a-3e00-4b81-9972-4e598d2b42dc', 'debugging'::public.question_type, 'hard'::public.difficulty_level, '{"en":"This stops with an AttributeError. Which line is the problem?"}'::jsonb, 'class Player:
