  ('4022d91c-58f8-49ce-85a3-2c8f3f0ab363', '21ecdae3-8c50-46eb-b368-e36591f98e73', 'true_false'::public.question_type, 'easy'::public.difficulty_level, '{"en":"When calling `r.area()`, you must pass `r` yourself as an argument."}'::jsonb, null, '{}'::jsonb, '{"en":"The object before the dot is passed automatically as `self`. You pass only the arguments after it.\n"}'::jsonb, null, null, false, true, true, array['oop']::text[], 1, 'draft'::public.review_status, 'bdaff72e746679ddd6c761ac78766d14'),
  ('2377c20d-f693-4989-b2b7-501335001297', '21ecdae3-8c50-46eb-b368-e36591f98e73', 'predict_output'::public.question_type, 'easy'::public.difficulty_level, '{"en":"What does this print?"}'::jsonb, 'class Greeter:
