  ('e2474450-e270-4cce-868a-6344c24d1f2b', '21ecdae3-8c50-46eb-b368-e36591f98e73', 'predict_output'::public.question_type, 'medium'::public.difficulty_level, '{"en":"What does this print?"}'::jsonb, 'class Jar:
