  ('789e7ca4-e82e-4d48-b46e-6e4beb370686', '21ecdae3-8c50-46eb-b368-e36591f98e73', 'debugging'::public.question_type, 'medium'::public.difficulty_level, '{"en":"This should print 10 but stops with a TypeError. How do you fix it?"}'::jsonb, 'class Circle:
