  ('42cb0f90-a903-42a1-bf77-c7d96ff647da', '21ecdae3-8c50-46eb-b368-e36591f98e73', 'multiple_select'::public.question_type, 'medium'::public.difficulty_level, '{"en":"With this class and `r = Rectangle(2, 5)`, which lines print 10?"}'::jsonb, 'class Rectangle:
