  ('abf28095-14cf-46df-aa83-b0ee84971488', '21ecdae3-8c50-46eb-b368-e36591f98e73', 'predict_output'::public.question_type, 'hard'::public.difficulty_level, '{"en":"What does this print?"}'::jsonb, 'class Counter:
