  ('b8ac82ed-d2ce-46e5-917d-218d97e9f093', '40305ec5-0370-4985-ad6e-554134c14d81', 'multiple_choice'::public.question_type, 'easy'::public.difficulty_level, '{"en":"What decides what `print(obj)` shows for an object of your own class?"}'::jsonb, null, '{"options":[{"id":"str","text":{"en":"Its __str__ method"}},{"id":"init","text":{"en":"Its __init__ method"}},{"id":"variable","text":{"en":"The name of the variable holding it"}},{"id":"class","text":{"en":"The class name, always"}}]}'::jsonb, '{"en":"`print` asks the object for its text form, which comes from `__str__`. Without one, you get the class name and an address.\n"}'::jsonb, null, null, false, true, true, array['oop']::text[], 1, 'draft'::public.review_status, 'a8d01ffa8f2d85c0cba54d7b72f4091f'),
  ('7a79455c-e362-424c-abd4-281799b79bef', '40305ec5-0370-4985-ad6e-554134c14d81', 'true_false'::public.question_type, 'easy'::public.difficulty_level, '{"en":"`__str__` must return a string."}'::jsonb, null, '{}'::jsonb, '{"en":"Anything else — including the `None` you get from forgetting `return` — is refused with a TypeError.\n"}'::jsonb, null, null, false, true, true, array['oop']::text[], 2, 'draft'::public.review_status, 'df62d33e5e36208e4cb95eaa0e8ca154'),
  ('d3632037-f3b2-4669-816c-bc9c2074401d', '40305ec5-0370-4985-ad6e-554134c14d81', 'predict_output'::public.question_type, 'medium'::public.difficulty_level, '{"en":"What does this print?"}'::jsonb, 'class Temp:
