  ('6001b7df-dd23-448e-ae29-862af8cbeaa2', '40305ec5-0370-4985-ad6e-554134c14d81', 'predict_output'::public.question_type, 'medium'::public.difficulty_level, '{"en":"What does this print?"}'::jsonb, 'class Pet:
