  ('6c5e2cf7-8f55-4271-ac84-6d1074eefd88', '40305ec5-0370-4985-ad6e-554134c14d81', 'debugging'::public.question_type, 'hard'::public.difficulty_level, '{"en":"This prints \"Card K\" and then crashes with a TypeError. Which line is the problem?"}'::jsonb, 'class Card:
