  ('477c626d-febf-4b8b-8f0d-cbf6180da4e4', '7d62e2b5-b672-40a5-8d4e-72cea26fb726', 'true_false'::public.question_type, 'easy'::public.difficulty_level, '{"en":"A child class can use methods it inherits without defining them itself."}'::jsonb, null, '{}'::jsonb, '{"en":"That is the point of inheriting. The child only defines what it wants to add or do differently.\n"}'::jsonb, null, null, false, true, true, array['oop', 'inheritance']::text[], 1, 'draft'::public.review_status, '11a7cd2866f1074b7701996162133887'),
  ('8aa2e230-9a56-4588-afca-09d67237f0cf', '7d62e2b5-b672-40a5-8d4e-72cea26fb726', 'multiple_choice'::public.question_type, 'easy'::public.difficulty_level, '{"en":"How do you make a class `Dog` inherit from `Animal`?"}'::jsonb, null, '{"options":[{"id":"brackets","text":{"en":"class Dog(Animal):"}},{"id":"extends","text":{"en":"class Dog extends Animal:"}},{"id":"inherits","text":{"en":"class Dog inherits Animal:"}},{"id":"backwards","text":{"en":"class Animal(Dog):"}}]}'::jsonb, '{"en":"The parent goes in brackets after the child''s name. The last option has them the wrong way round, making Animal a kind of Dog.\n"}'::jsonb, null, null, false, true, true, array['oop', 'inheritance']::text[], 2, 'draft'::public.review_status, '8ef6221d8b7b05c654e28cdeb370b977'),
  ('b3bbc269-0537-4bf6-abad-50399d1b4ec6', '7d62e2b5-b672-40a5-8d4e-72cea26fb726', 'predict_output'::public.question_type, 'medium'::public.difficulty_level, '{"en":"What does this print?"}'::jsonb, 'class Vehicle:
