', '{"input":"text"}'::jsonb, '{"en":"Bike overrides `wheels` and gives 2. Car does not, so it uses Vehicle''s 4.\n"}'::jsonb, null, null, false, true, true, array['oop', 'inheritance']::text[], 3, 'draft'::public.review_status, 'e2b6a1ff193187368acb32813eac4ce3'),
  ('dcacb064-2af9-4a62-b267-180863d75ac9', '7d62e2b5-b672-40a5-8d4e-72cea26fb726', 'predict_output'::public.question_type, 'medium'::public.difficulty_level, '{"en":"What does this print?"}'::jsonb, 'class Shape:
    def __init__(self, name):
        self.name = name

