', '{"input":"text"}'::jsonb, '{"en":"Square''s `__init__` hands \"square\" to Shape''s `__init__` through `super()`, then adds its own `side`. The object ends up with both attributes.\n"}'::jsonb, null, null, false, true, true, array['oop', 'inheritance']::text[], 4, 'draft'::public.review_status, 'e6a4e224995649bf6f70fa3fe6d91e85'),
  ('ae6e155f-e419-476c-b4f8-d711848c11e2', '7d62e2b5-b672-40a5-8d4e-72cea26fb726', 'concept_matching'::public.question_type, 'medium'::public.difficulty_level, '{"en":"Match each term to its meaning."}'::jsonb, null, '{"concepts":[{"id":"parent","text":{"en":"Parent class"}},{"id":"child","text":{"en":"Child class"}},{"id":"override","text":{"en":"Overriding"}},{"id":"super","text":{"en":"super()"}}],"definitions":[{"id":"inherited-from","text":{"en":"The class being inherited from"}},{"id":"inherits","text":{"en":"The class that inherits"}},{"id":"replace","text":{"en":"Defining a method again in the child to replace the parent''s"}},{"id":"call-parent","text":{"en":"Calling the parent''s version of a method"}}]}'::jsonb, '{"en":"A child inherits from a parent, may override what it wants to change, and can still reach the parent''s version through `super()`.\n"}'::jsonb, null, null, false, true, true, array['oop', 'inheritance']::text[], 5, 'draft'::public.review_status, '4d6eba301b81faaa28f2f66803f0dcba'),
  ('f2b1c927-5189-406a-b0ac-47d2745e7087', '7d62e2b5-b672-40a5-8d4e-72cea26fb726', 'predict_output'::public.question_type, 'hard'::public.difficulty_level, '{"en":"What does this print?"}'::jsonb, 'class A:
    def who(self):
        return "A"

    def hello(self):
        return "I am " + self.who()

class B(A):
    def who(self):
        return "B"

print(B().hello())
', '{"input":"text"}'::jsonb, '{"en":"`hello` is inherited from A, but `self` is a B. When it calls `self.who()`, Python looks on the object first and finds B''s version. Methods are chosen by what the object is, not by where the calling code was written.\n"}'::jsonb, '{"en":"What kind of object is `self` inside `hello`?"}'::jsonb, null, false, true, true, array['oop', 'inheritance']::text[], 6, 'draft'::public.review_status, '9a85351dab1af4ace9f86752c8982227'),
  ('f63f5f1f-e3e9-4539-abbc-4511683e6e65', 'c67de1e5-fb2c-4114-9177-b0b3f72df446', 'multiple_choice'::public.question_type, 'easy'::public.difficulty_level, '{"en":"What is a good first step when facing a new problem?"}'::jsonb, null, '{"options":[{"id":"plan","text":{"en":"Describe the steps in plain words"}},{"id":"type","text":{"en":"Start typing code straight away"}},{"id":"copy","text":{"en":"Find the longest program you can and copy it"}},{"id":"prints","text":{"en":"Add print calls everywhere"}}]}'::jsonb, '{"en":"A plain-words plan tells you what code to write and in what order. Code written without one tends to be rewritten.\n"}'::jsonb, null, null, false, true, true, array['problem-solving']::text[], 1, 'draft'::public.review_status, '50d1035548d9e427047aa159c1acb27e'),
  ('8952c80d-4290-43d5-9201-e1dc4141974a', 'c67de1e5-fb2c-4114-9177-b0b3f72df446', 'true_false'::public.question_type, 'easy'::public.difficulty_level, '{"en":"In `longest_word`, when two words have the same length, the first one is kept."}'::jsonb, null, '{}'::jsonb, '{"en":"The comparison is `>`, not `>=`, so a word of equal length never replaces the current best.\n"}'::jsonb, null, null, false, true, true, array['problem-solving', 'comparisons']::text[], 2, 'draft'::public.review_status, '13c849ed9af5bc6046af5e54d3c4892f'),
  ('10bdcc64-5027-49c8-a47d-fb406de78b36', 'c67de1e5-fb2c-4114-9177-b0b3f72df446', 'code_ordering'::public.question_type, 'medium'::public.difficulty_level, '{"en":"Arrange the steps so the program prints the length of the longest word, 3."}'::jsonb, null, '{"lines":[{"id":"split","text":"words = \"a bb ccc\".split()"},{"id":"lengths","text":"lengths = [len(w) for w in words]"},{"id":"longest","text":"longest = max(lengths)"},{"id":"show","text":"print(longest)"}]}'::jsonb, '{"en":"Each step feeds the next: words, then their lengths, then the biggest length, then the output. Breaking a problem down usually produces exactly this kind of chain.\n"}'::jsonb, null, null, false, true, true, array['problem-solving', 'comprehensions']::text[], 3, 'draft'::public.review_status, '0c091cfc8d4132ad01f531fb0f45c34a'),
  ('647d8445-b52e-448a-8825-21290203b32c', 'c67de1e5-fb2c-4114-9177-b0b3f72df446', 'predict_output'::public.question_type, 'medium'::public.difficulty_level, '{"en":"What does this print?"}'::jsonb, 'def count_long(words, n):
