  ('a5b4a90d-32fa-411e-86c5-fd308ed31b08', 'c67de1e5-fb2c-4114-9177-b0b3f72df446', 'debugging'::public.question_type, 'hard'::public.difficulty_level, '{"en":"This works for most lists but crashes for an empty one. How do you fix it?"}'::jsonb, 'def average(nums):
