  ('e243dda0-6dbd-4305-b621-99bc63281d86', 'bf086c8a-ca58-41e4-9895-86cb77574926', 'predict_output'::public.question_type, 'easy'::public.difficulty_level, '{"en":"What does this print?"}'::jsonb, 'def find(items, target):
