  ('bdeabf1b-dba9-4494-ac3c-b5bcf569ff56', 'bf086c8a-ca58-41e4-9895-86cb77574926', 'predict_output'::public.question_type, 'hard'::public.difficulty_level, '{"en":"What does this print?"}'::jsonb, 'def count_checks(items, target):
