  ('081e539c-bf6d-49ca-9903-7ff8888e30f3', 'f7fee9c3-1b51-4e38-afee-b80392ff9c5b', 'true_false'::public.question_type, 'easy'::public.difficulty_level, '{"en":"Binary search only works correctly on a sorted list."}'::jsonb, null, '{}'::jsonb, '{"en":"Discarding half the list is only safe when the order tells you which half the target cannot be in.\n"}'::jsonb, null, null, false, true, true, array['searching']::text[], 1, 'draft'::public.review_status, '462a93d2ff9039681c3d2dda3ef1c70d'),
  ('408ff317-0f94-41f9-aaf1-0ed0df8af64b', 'f7fee9c3-1b51-4e38-afee-b80392ff9c5b', 'multiple_choice'::public.question_type, 'easy'::public.difficulty_level, '{"en":"What does each step of a binary search do to the part of the list still being searched?"}'::jsonb, null, '{"options":[{"id":"halves","text":{"en":"Halves it"}},{"id":"one","text":{"en":"Removes one item"}},{"id":"doubles","text":{"en":"Doubles it"}},{"id":"sorts","text":{"en":"Sorts it"}}]}'::jsonb, '{"en":"Each comparison with the middle item rules out half of what is left. That is where the speed comes from.\n"}'::jsonb, null, null, false, true, true, array['searching']::text[], 2, 'draft'::public.review_status, '39a63af62ea587443f25f46b25ac243b'),
  ('7e4846a1-8a46-4082-98b8-eebb0c418137', 'f7fee9c3-1b51-4e38-afee-b80392ff9c5b', 'predict_output'::public.question_type, 'medium'::public.difficulty_level, '{"en":"What does this print?"}'::jsonb, 'def binary_search(items, target):
    low = 0
    high = len(items) - 1
    while low <= high:
        mid = (low + high) // 2
        if items[mid] == target:
            return mid
        elif items[mid] < target:
            low = mid + 1
        else:
            high = mid - 1
    return -1

print(binary_search([1, 3, 5, 7, 9], 3))
', '{"input":"text"}'::jsonb, '{"en":"The middle is 5, which is too big, so the search moves left to [1, 3]. The new middle is 1, too small, so it moves right and finds 3 at index 1.\n"}'::jsonb, null, null, false, true, true, array['searching']::text[], 3, 'draft'::public.review_status, '7f892eb94287270443feec1d329623af'),
  ('170f6997-d041-4045-b622-5d3e8fe935b1', 'f7fee9c3-1b51-4e38-afee-b80392ff9c5b', 'multiple_choice'::public.question_type, 'medium'::public.difficulty_level, '{"en":"Roughly how many checks does binary search need, at most, for a sorted list of 1,000,000 items?"}'::jsonb, null, '{"options":[{"id":"twenty","text":{"en":"About 20"}},{"id":"thousand","text":{"en":"About 1,000"}},{"id":"half","text":{"en":"About 500,000"}},{"id":"million","text":{"en":"About 1,000,000"}}]}'::jsonb, '{"en":"Halving a million about 20 times brings it down to one item, because 2 to the power of 20 is just over a million.\n"}'::jsonb, null, null, false, true, true, array['searching', 'complexity']::text[], 4, 'draft'::public.review_status, '775bd7497fa7753951421f0bc6492cc0'),
  ('c2f2c3ff-78f6-4c77-b4a7-c286092caf1d', 'f7fee9c3-1b51-4e38-afee-b80392ff9c5b', 'predict_output'::public.question_type, 'medium'::public.difficulty_level, '{"en":"How many times can 1024 be halved before reaching 1? What does this print?"}'::jsonb, 'def steps(n):
